"use client";

import { useEffect, useLayoutEffect, useMemo, useRef, type CSSProperties, type ReactNode } from "react";
import {
  useDataGridActiveCell,
  useDataGridRowCount,
  useDataGridRowIds,
  useDataGridRowMarkers,
  type AnyColumnDef,
} from "./store";
import { useRowWindow } from "./windowing/use-row-window";
import { useDataGridRootContext, type WindowedColumn } from "./layout-context";
import { DataGridRow } from "./row";
import { DataGridOverlays } from "./overlays";
import { isDev } from "./is-dev";

/** Real-index `[min, max+1)` bounds of the currently rendered UNPINNED columns.
 * Overlay segmentation clamps its unpinned segment to this, so it never reaches off-screen track
 * positions the virtualized window did not render. An empty window collapses to a zero-width range. */
function unpinnedWindowRange(
  windowedColumns: readonly WindowedColumn[],
  pins: readonly (AnyColumnDef["pin"] | undefined)[],
): { start: number; end: number } {
  let min = Infinity;
  let max = -Infinity;
  for (const { index } of windowedColumns) {
    if (pins[index] !== undefined) continue;
    if (index < min) min = index;
    if (index > max) max = index;
  }
  return Number.isFinite(min) ? { start: min, end: max + 1 } : { start: 0, end: 0 };
}

let warnedRowCountMismatch = false;

/** Renders only the windowed rows for the current scroll position, plus the active row so focus survives scrolling it out of view. */
export function DataGridBody(): ReactNode {
  const {
    scrollRef,
    windowedColumns,
    rowHeight,
    headerHeight,
    pinnedTopHeight,
    pinnedBottomHeight,
    pinnedTopCount,
    template,
    layout,
    readOnly,
    interaction,
    getRowClassName,
    getCellClassName,
    onCellClick,
    onRowClick,
    onRowWindowChange,
  } = useDataGridRootContext();
  const rowMarkers = useDataGridRowMarkers();
  const rowCount = useDataGridRowCount();
  const activeCell = useDataGridActiveCell();
  // Data row 0 starts below the header AND any pinned-top band (shrunken effective viewport);
  // the pinned-bottom band shrinks the window's bottom edge the same way.
  const effectiveHeaderHeight = headerHeight + pinnedTopHeight;
  const { start, end, windowTop, measured } = useRowWindow(scrollRef, {
    rowCount,
    rowHeight,
    dataRowTop: effectiveHeaderHeight,
    bottomInset: pinnedBottomHeight,
  });

  // Fires post-commit, never during render — DataGridBody already re-renders every window tick
  // regardless (it calls useRowWindow directly), so this adds no extra subscription and can't
  // affect the single-flushSync-per-tick scroll commit (the effect runs after that commit, on its
  // own microtask-free schedule). Gated on [start, end] identity so it fires once on mount and
  // again only when the committed range actually moved, never on a same-window scroll tick.
  //
  // `!measured` skips the one render before the scroll element is attached: useRowWindow's mount
  // effect measures the real element and force-updates to the real window in the SAME effect flush
  // this component's own effect runs in, so without this guard the fixed {0, min(rowCount,30)}
  // fallback and the real window both looked like genuine, distinct committed ranges and this fired
  // twice on every mount (root cause of the double-fire bug) — the fallback was never a range a
  // consumer (e.g. data-grid-lazy's fetch-on-window) should act on in the first place.
  const lastFiredRangeRef = useRef<{ start: number; end: number } | null>(null);
  useEffect(() => {
    if (!measured) return;
    const last = lastFiredRangeRef.current;
    if (last && last.start === start && last.end === end) return;
    lastFiredRangeRef.current = { start, end };
    onRowWindowChange?.({ start, end });
  }, [start, end, measured, onRowWindowChange]);

  // A naive "clear then repopulate" would blank the body for a frame on every window shift.
  // Rows are keyed by getRowId and mapped straight from viewRowIndices, so keyed reconciliation
  // unmounts only the rows that left the range and mounts only the rows that entered it; the
  // rows common to both windows never unmount.
  const viewRowIndices = useMemo(() => {
    const indices: number[] = [];
    for (let i = start; i < end; i++) indices.push(i);
    // the active row always renders, even off-window, so focus survives scroll
    const activeRowOffWindow = activeCell !== null && (activeCell.row < start || activeCell.row >= end) && activeCell.row < rowCount;
    if (activeRowOffWindow) indices.push(activeCell.row);

    // Dev-only invariant: the rendered set must be exactly computeWindow's [start,end) plus the
    // off-window active row, never more/fewer — catches a regression that silently drops or
    // duplicates rows.
    if (isDev()) {
      const expected = end - start + (activeRowOffWindow ? 1 : 0);
      if (indices.length !== expected && !warnedRowCountMismatch) {
        warnedRowCountMismatch = true;
        console.warn(
          `gridcn: rendered row count (${indices.length}) does not match the expected window size (${expected}) — start=${start} end=${end} activeRowOffWindow=${activeRowOffWindow}.`,
        );
      }
    }
    return indices;
  }, [start, end, activeCell, rowCount]);

  // Rows are memoized by getRowId, not viewRowIndex, so sort/filter/insert/delete reuses the right DOM row.
  const rowIds = useDataGridRowIds(viewRowIndices);

  // Keyed by getRowId (matches the row's own React key) so a row kept across a shift is found by
  // identity, not array position — viewRowIndices order can change (e.g. the off-window active row
  // entry moving) independent of which DOM nodes actually moved. React calls the ref callback with
  // null on unmount, so a scrolled-out row removes its own rowElements entry — no pruning needed here.
  const rowElements = useRef(new Map<string | number, HTMLDivElement>());
  // A fresh inline ref callback every render would itself defeat DataGridRow's memo (ref is a plain
  // prop in React 19, included in memo's shallow compare) — cache one stable callback per row key so
  // reused rows (same key across a shift) get the same function reference every render.
  const rowRefCallbacks = useRef(new Map<string | number, (el: HTMLDivElement | null) => void>());
  // Rows churn through unique getRowId keys during a long scroll session (e.g. 100k rows) — the
  // callback cache would otherwise grow unbounded. React unmounts stale rows (calling their ref
  // callback with null) before this component's next render, so pruning on that same rAF-driven
  // cadence is redundant work on the full-swap hot path (a Map scan for cols*rows keys every tick);
  // amortize it instead, sweeping only once the cache has grown well past a live window's size.
  const PRUNE_THRESHOLD = 500;
  const getRowRefCallback = (key: string | number) => {
    let cb = rowRefCallbacks.current.get(key);
    if (!cb) {
      cb = (el) => {
        if (el) rowElements.current.set(key, el);
        else {
          rowElements.current.delete(key);
          rowRefCallbacks.current.delete(key);
        }
      };
      rowRefCallbacks.current.set(key, cb);
      if (rowRefCallbacks.current.size > PRUNE_THRESHOLD) {
        // defensive sweep for any key whose unmount ref-callback somehow didn't fire (should not
        // happen under normal React unmounts, but keeps the cache bounded even so).
        for (const k of rowRefCallbacks.current.keys()) {
          if (!rowElements.current.has(k)) rowRefCallbacks.current.delete(k);
        }
      }
    }
    return cb;
  };

  // When the active row sits ABOVE the window, gridRowStart (viewRowIndex - windowStart + 1) would
  // be <= 0 — an invalid <integer> (dropped, falls back to auto placement) or a negative index
  // (counts from the end of the explicit grid) — either way it corrupts canvas layout. Extend the
  // effective window start down to the active row and shift the canvas transform by the same
  // amount, so every rendered row keeps a valid (>=1) gridRowStart with no visual change.
  const effectiveStart = activeCell ? Math.min(start, activeCell.row) : start;
  const effectiveWindowTop = windowTop - (start - effectiveStart) * rowHeight;

  // Writes gridRowStart straight into each row's DOM node, bypassing React for this value.
  // The body re-renders every window tick anyway, so the write costs nothing extra, and
  // DataGridRow stays memoized without windowStart in its props.
  useLayoutEffect(() => {
    for (let i = 0; i < viewRowIndices.length; i++) {
      // i < viewRowIndices.length by loop condition
      const viewRowIndex = viewRowIndices[i]!;
      const key = rowIds[i] ?? viewRowIndex;
      const el = rowElements.current.get(key);
      if (el) el.style.gridRowStart = String(viewRowIndex - effectiveStart + 1);
    }
  });

  const canvasStyle: CSSProperties & Record<string, string | number> = {
    position: "absolute",
    insetBlockStart: 0,
    insetInlineStart: 0,
    display: "grid",
    gridTemplateColumns: template,
    gridAutoRows: `${rowHeight}px`,
    "--grid-window-top": `${effectiveWindowTop}px`,
    // X: cancel native scroll like the header. Y: place the canvas at effectiveHeaderHeight +
    // windowTop (below the header AND any pinned-top band), then cancel native scroll's vertical
    // component too — one transform, both axes, every tick.
    // --grid-dir (-1 in LTR, 1 in RTL) signs the horizontal term: transforms are always physical
    // while the grid tracks under them mirror themselves, so the sign is the only difference.
    transform: `translate3d(calc(var(--grid-dir, -1) * var(--grid-scroll-left, 0px)), calc(var(--grid-window-top) - var(--grid-scroll-top, 0px) + ${effectiveHeaderHeight}px), 0)`,
  };

  return (
    <div style={canvasStyle} data-grid-rows-canvas="">
      {viewRowIndices.map((viewRowIndex, i) => {
        const key = rowIds[i] ?? viewRowIndex;
        return (
          <DataGridRow
            key={key}
            viewRowIndex={viewRowIndex}
            windowedColumns={windowedColumns}
            layout={layout}
            readOnly={readOnly}
            rowMarkers={rowMarkers}
            onMarkerPointerDown={interaction.onMarkerPointerDown}
            onMarkerCheckboxPointerDown={interaction.onMarkerCheckboxPointerDown}
            rowRef={getRowRefCallback(key)}
            ariaRowIndexOffset={pinnedTopCount}
            getRowClassName={getRowClassName}
            getCellClassName={getCellClassName}
            onCellClick={onCellClick}
            onRowClick={onRowClick}
          />
        );
      })}
      <DataGridOverlays
        windowStart={effectiveStart}
        rowCount={viewRowIndices.length}
        // contiguous rendered span for clamping: [effectiveStart, effectiveStart + length) is
        // disjoint whenever the active row was appended off-window
        clampRowStart={start}
        clampRowEnd={end}
        // total visible columns (real index space), not the rendered window size — bands and
        // pin-zone segmentation must span the FULL grid width
        colCount={layout.pins.length}
        colOffset={layout.markerWidth > 0 ? 2 : 1}
        pinTrack={{
          pins: layout.pins,
          trackLefts: layout.trackLefts,
          trackRights: layout.trackRights,
          renderedUnpinnedRange: unpinnedWindowRange(windowedColumns, layout.pins),
        }}
      />
    </div>
  );
}

import { cn } from "@/lib/utils";

/**
 * Shared display span: truncates and honors the type's text alignment. `align` names are reading
 * relative, not physical — `"right"` is the END of the reading direction, so a right-aligned
 * numeric column hugs the inline end in both LTR and RTL.
 */
export function CellSpan({ text, align }: { text: string; align?: "left" | "right" | "center" }) {
  return (
    <span
      className={cn(
        "block w-full truncate",
        align === "right" && "text-end",
        align === "center" && "text-center",
      )}
    >
      {/* <bdi> isolates the value's own bidi run so mixed-script data shapes correctly, without the
          box taking that run's direction — `dir="auto"` here would resolve a Latin value to `ltr`
          and re-resolve this span's `text-align: start` to the physical LEFT, stranding cell text
          on the wrong side of an RTL grid while the header mirrored correctly. */}
      <bdi>{text}</bdi>
    </span>
  );
}

import type { CellOptionsOf, CellType, CellValueOf } from "../types";
import { textCellType } from "./text";
import { numberCellType } from "./number";
import { checkboxCellType } from "./checkbox";
import { selectCellType } from "./select";
import { dateCellType } from "./date";

export { textCellType } from "./text";
export { numberCellType } from "./number";
export { checkboxCellType } from "./checkbox";
export { selectCellType } from "./select";
export { dateCellType } from "./date";

/**
 * The five built-in keys, deliberately DECOUPLED from `CellTypeKey` (which is
 * `keyof GridCellTypes` and grows with consumer augmentation). Keeping this
 * union literal means the `satisfies` below only ever checks these five
 * built-in entries — a consumer's `declare module` augmentation adds a key to
 * `GridCellTypes`/`CellTypeKey` without requiring the shipped `cellTypes`
 * object to provide an implementation for it.
 */
type BuiltinCellTypeKey = "text" | "number" | "checkbox" | "select" | "date";

/** A `CellType` for one {@link BuiltinCellTypeKey}, with its exact value/options shape. */
type CellTypeFor<K extends BuiltinCellTypeKey> = CellType<unknown, CellValueOf<K>, CellOptionsOf<K>>;

/** Built-in cell-type registry keyed by {@link BuiltinCellTypeKey}; consumers merge in custom types alongside these. */
export const cellTypes = {
  text: textCellType,
  number: numberCellType,
  checkbox: checkboxCellType,
  select: selectCellType,
  date: dateCellType,
} satisfies { [K in BuiltinCellTypeKey]: CellTypeFor<K> };

import { useEffect } from "react";
import { Checkbox } from "@/components/ui/checkbox";
import type { CellEditorProps, CellRenderProps, CellType, GridCellTypes } from "../types";
import { useCommitGuard } from "../interaction/use-commit-guard";

function CheckboxCell({ value }: CellRenderProps<unknown, boolean>) {
  // display-only: the interaction layer toggles via commitCellValue, so the control never receives events
  return (
    <span className="flex size-full items-center justify-center">
      <Checkbox checked={value} tabIndex={-1} className="pointer-events-none" />
    </span>
  );
}

/** Checkbox has no edit mode (interaction layer toggles+commits directly via `commitCellValue`); this only guards a stray `startEditing` call by bailing out immediately. */
function CheckboxEditor({ cancel }: CellEditorProps<unknown, boolean>) {
  const committed = useCommitGuard();
  useEffect(() => {
    if (!committed.tryCommit()) return;
    cancel();
    // oxlint-disable-next-line react-hooks/exhaustive-deps
  }, []);
  return null;
}

/** Truthy tokens accepted by the checkbox type's `fromText` (paste/import), case-insensitive. */
const CHECKBOX_TRUE_TOKENS = new Set(["true", "1", "yes", "x", "on"]);

/** `checkbox`: fromText accepts a small truthy-token set; clipboard round-trips as "true"/"false". */
export const checkboxCellType: CellType<unknown, boolean, GridCellTypes["checkbox"]["options"]> = {
  Cell: CheckboxCell,
  Editor: CheckboxEditor,
  toText: (value) => (value ? "true" : "false"),
  fromText: (text) => CHECKBOX_TRUE_TOKENS.has(text.trim().toLowerCase()),
  clearValue: () => false,
  isEmpty: (value) => value == null,
  compare: (a, b) => Number(a) - Number(b),
  align: "center",
};

import { useEffect, useRef, useState, type KeyboardEvent } from "react";
import { Input } from "@/components/ui/input";
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
import { Calendar } from "@/components/ui/calendar";
import type { CellEditorProps, CellRenderProps, CellType, GridCellTypes } from "../types";
import { CellSpan } from "./cell-span";
import { displayText } from "./display-text";
import { useCommitGuard } from "../interaction/use-commit-guard";
import { columnLabelText } from "../columns/column-format-helpers";

/** Normalizes any Date-parseable input to its ISO `yyyy-mm-dd` date part; null when unparseable or out of range. */
function toIsoDatePart(input: string, options?: GridCellTypes["date"]["options"]): string | null {
  const trimmed = input.trim();
  if (trimmed === "") return null;
  let isoDate: string;
  if (/^\d{4}-\d{2}-\d{2}$/.test(trimmed)) {
    isoDate = trimmed;
  } else {
    const parsed = new Date(trimmed);
    if (Number.isNaN(parsed.getTime())) return null;
    // use local getters, not toISOString(), so a locale-parsed date (local midnight) doesn't shift a day across UTC
    const year = String(parsed.getFullYear()).padStart(4, "0");
    const month = String(parsed.getMonth() + 1).padStart(2, "0");
    const day = String(parsed.getDate()).padStart(2, "0");
    isoDate = `${year}-${month}-${day}`;
  }
  if (options?.min !== undefined && isoDate < options.min) return null;
  if (options?.max !== undefined && isoDate > options.max) return null;
  return isoDate;
}

/** Parses an ISO `yyyy-mm-dd` date part as a local-midnight `Date` for the Calendar; null for anything else. */
function isoDatePartToLocalDate(isoDate: string | null): Date | undefined {
  if (isoDate == null || !/^\d{4}-\d{2}-\d{2}$/.test(isoDate)) return undefined;
  // regex above guarantees exactly 3 numeric "-"-separated parts
  const [year, month, day] = isoDate.split("-").map(Number) as [number, number, number];
  return new Date(year, month - 1, day);
}

/** Local-midnight `Date` back to its ISO `yyyy-mm-dd` part (mirrors `toIsoDatePart`'s local-getter approach). */
function localDateToIsoDatePart(date: Date): string {
  const year = String(date.getFullYear()).padStart(4, "0");
  const month = String(date.getMonth() + 1).padStart(2, "0");
  const day = String(date.getDate()).padStart(2, "0");
  return `${year}-${month}-${day}`;
}

/** Constructing an `Intl.DateTimeFormat` costs ~38us against ~0.7us to reuse one (measured) — at
 * fling speed that ran once per date cell per newly-mounted row, so formatters are cached by their
 * resolved locale + format options instead. Keyed on the serialized options rather than the options
 * object's identity: a column literal re-created each render is the common case and must still hit. */
const dateFormatterCache = new Map<string, Intl.DateTimeFormat>();

function getDateFormatter(locale: string, format: Intl.DateTimeFormatOptions): Intl.DateTimeFormat {
  const key = `${locale}|${JSON.stringify(format)}`;
  let formatter = dateFormatterCache.get(key);
  if (!formatter) {
    formatter = new Intl.DateTimeFormat(locale, format);
    dateFormatterCache.set(key, formatter);
  }
  return formatter;
}

/** Formats an ISO date part per the column's `displayFormat`/`locale`, falling back to the raw ISO text. */
function formatDateDisplay(value: string | null, options?: GridCellTypes["date"]["options"]): string {
  if (value == null) return "";
  if (!options?.displayFormat) return value;
  const date = isoDatePartToLocalDate(value);
  if (!date) return value;
  // pinned default: server and browser Intl defaults can differ -> SSR hydration mismatch
  return getDateFormatter(options.locale ?? "en-US", options.displayFormat).format(date);
}

function DateCell({ value, column }: CellRenderProps<unknown, string | null>) {
  const options = column.options as GridCellTypes["date"]["options"] | undefined;
  return <CellSpan text={displayText(dateCellType, value, options)} align="right" />;
}

/** Popover + Calendar (shadcn date-picker pattern): opens on edit start; picking a date commits and stays; a small typed-input above the calendar accepts ISO or Date.parse-able text with Enter to commit. */
function DateEditor({
  value,
  onChange,
  commit,
  cancel,
  column,
  pending,
  rejectionCount,
}: CellEditorProps<unknown, string | null>) {
  const options = column.options as GridCellTypes["date"]["options"] | undefined;
  const inputRef = useRef<HTMLInputElement>(null);
  const [text, setText] = useState(dateCellType.toText(value));
  const [open, setOpen] = useState(true);
  const committed = useCommitGuard();

  // Re-arm on each rejection, not on pending->false (that also fires on the cancel right before unmount); see CellEditorProps.rejectionCount.
  const lastRejectionCount = useRef(rejectionCount ?? 0);
  useEffect(() => {
    if ((rejectionCount ?? 0) !== lastRejectionCount.current) committed.reset();
    lastRejectionCount.current = rejectionCount ?? 0;
  }, [rejectionCount, committed]);

  useEffect(() => {
    const el = inputRef.current;
    if (!el) return;
    el.focus();
    const end = el.value.length;
    el.setSelectionRange(end, end);
  }, []);

  const commitValue = (nextValue: string | null, movement?: { dx: number; dy: number }) => {
    if (!committed.tryCommit()) return;
    onChange(nextValue);
    commit(movement);
  };

  return (
    <Popover
      open={open}
      onOpenChange={(next) => {
        setOpen(next);
        if (!next && committed.tryCommit()) cancel();
      }}
    >
      <PopoverTrigger
        nativeButton={false}
        render={<span className="block size-full truncate text-end" />}
      >
        {displayText(dateCellType, value, options)}
      </PopoverTrigger>
      <PopoverContent
        data-grid-cell-editor=""
        align="start"
        className="w-auto p-0"
        onKeyDown={(e: KeyboardEvent<HTMLDivElement>) => {
          if (e.key === "Escape") {
            if (committed.tryCommit()) cancel();
          }
        }}
      >
        <div className="p-2 pb-0">
          <Input
            ref={inputRef}
            value={text}
            // readOnly, not disabled: a disabled input can't receive focus/keyboard events at all, which
            // would silently swallow Escape while an async validation is pending — readOnly blocks typing
            // but keeps Escape/Tab/blur working.
            readOnly={pending}
            // ISO date text is direction-neutral; see the number editor for why `auto` beats the
            // grid's inherited layout direction on a value-carrying input.
            dir="auto"
            placeholder="yyyy-mm-dd"
            onChange={(e) => setText(e.target.value)}
            onKeyDown={(e: KeyboardEvent<HTMLInputElement>) => {
              if (e.key === "Enter") {
                commitValue(dateCellType.fromText(text, options), { dx: 0, dy: 1 });
              } else if (e.key === "Escape") {
                if (committed.tryCommit()) cancel();
              }
            }}
            aria-label={columnLabelText(column)}
            className="h-8 w-full border-none bg-transparent px-2 shadow-none outline-none focus-visible:ring-0"
          />
        </div>
        <Calendar
          mode="single"
          selected={isoDatePartToLocalDate(value)}
          defaultMonth={isoDatePartToLocalDate(value)}
          onSelect={(date) => {
            if (!date) return;
            commitValue(localDateToIsoDatePart(date), { dx: 0, dy: 0 });
          }}
        />
      </PopoverContent>
    </Popover>
  );
}

/** `date`: ISO `yyyy-mm-dd` storage; fromText accepts ISO or any Date.parse-able string, normalized and range-checked against min/max. */
export const dateCellType: CellType<unknown, string | null, GridCellTypes["date"]["options"]> = {
  Cell: DateCell,
  Editor: DateEditor,
  toText: (value) => value ?? "",
  toDisplayText: (value, options) => formatDateDisplay(value, options),
  fromText: (text, options) => toIsoDatePart(text, options),
  clearValue: () => null,
  isEmpty: (value) => value == null,
  compare: (a, b) => {
    if (a == null && b == null) return 0;
    if (a == null) return -1;
    if (b == null) return 1;
    return a < b ? -1 : a > b ? 1 : 0;
  },
  align: "right",
};

import type { CellType } from "../types";

/** Generic display-text resolution: any {@link CellType} may define `toDisplayText` for a formatted read view; falls back to `toText`. Clipboard/export always call `toText` directly, never this. */
export function displayText<TValue, TOptions>(
  cellType: Pick<CellType<unknown, TValue, TOptions>, "toText" | "toDisplayText">,
  value: TValue,
  options?: TOptions,
): string {
  return (cellType.toDisplayText ?? cellType.toText)(value, options);
}

/** Domain barrel — built-in cell type registry and shared editor pieces. */
export {
  cellTypes,
  textCellType,
  numberCellType,
  checkboxCellType,
  selectCellType,
  dateCellType,
} from "./cell-types";
export { displayText } from "./display-text";
export { CellSpan } from "./cell-span";

import { useEffect, useRef, useState, type KeyboardEvent } from "react";
import { Input } from "@/components/ui/input";
import type { CellEditorProps, CellRenderProps, CellType, GridCellTypes } from "../types";
import { CellSpan } from "./cell-span";
import { useSeedFocus } from "../interaction/use-seed-focus";
import { useCommitGuard } from "../interaction/use-commit-guard";
import { columnLabelText } from "../columns/column-format-helpers";

/** Normalizes a comma decimal separator to a dot so `Number()` can parse locales pasted verbatim. */
function normalizeNumberText(text: string): string {
  return text.trim().replace(",", ".");
}

/** Clamps a parsed number into the column's configured min/max, if any. */
function clampNumber(value: number, options?: GridCellTypes["number"]["options"]): number {
  let clamped = value;
  if (options?.min !== undefined) clamped = Math.max(clamped, options.min);
  if (options?.max !== undefined) clamped = Math.min(clamped, options.max);
  return clamped;
}

/** Rounds to the column's configured decimal precision, if any. */
function roundToDecimals(value: number, options?: GridCellTypes["number"]["options"]): number {
  if (options?.decimals === undefined) return value;
  const factor = 10 ** options.decimals;
  return Math.round(value * factor) / factor;
}

function NumberCell({ value, column }: CellRenderProps<unknown, number | null>) {
  const options = column.options as GridCellTypes["number"]["options"] | undefined;
  return <CellSpan text={numberCellType.toText(value, options)} align="right" />;
}

function NumberEditor({
  value,
  initialText,
  onChange,
  commit,
  cancel,
  column,
  pending,
  rejectionCount,
}: CellEditorProps<unknown, number | null>) {
  const ref = useRef<HTMLInputElement>(null);
  const [text, setText] = useState(initialText ?? numberCellType.toText(value));
  useSeedFocus(ref, initialText);
  const committed = useCommitGuard();

  // An async schema resolving with ISSUES leaves editing open — re-arm the guard so the user's
  // next Enter/blur after fixing the value isn't silently dropped. Keyed off rejectionCount
  // specifically (not "pending went from true to false", which also fires on Escape/cancel right
  // before unmount — resetting there let the unmount's own blur commit a second, stale time).
  const lastRejectionCount = useRef(rejectionCount ?? 0);
  useEffect(() => {
    if ((rejectionCount ?? 0) !== lastRejectionCount.current) committed.reset();
    lastRejectionCount.current = rejectionCount ?? 0;
  }, [rejectionCount, committed]);

  const commitText = (movement?: { dx: number; dy: number }) => {
    if (!committed.tryCommit()) return;
    onChange(numberCellType.fromText(text, column.options as GridCellTypes["number"]["options"]));
    commit(movement);
  };

  return (
    <Input
      ref={ref}
      value={text}
      // Numerals are direction-neutral, so under an inherited `dir=rtl` a leading minus sign and the
      // caret land on the wrong end. `auto` has no strong character to find here and resolves to
      // ltr — the correct reading order for a number in either layout direction.
      dir="auto"
      // readOnly, not disabled: a disabled input can't receive focus/keyboard events at all, which
      // would silently swallow Escape while an async validation is pending — readOnly blocks typing
      // but keeps Escape/Tab/blur working.
      readOnly={pending}
      onChange={(e) => setText(e.target.value)}
      onKeyDown={(e: KeyboardEvent<HTMLInputElement>) => {
        if (e.key === "Enter") {
          commitText({ dx: 0, dy: 1 });
        } else if (e.key === "Escape") {
          cancel();
        }
      }}
      onBlur={() => commitText({ dx: 0, dy: 0 })}
      aria-label={columnLabelText(column)}
      aria-busy={pending || undefined}
      className="h-full w-full border-none bg-transparent p-0 text-end shadow-none outline-none [appearance:textfield] focus-visible:ring-0 [&::-webkit-inner-spin-button]:appearance-none [&::-webkit-outer-spin-button]:appearance-none"
    />
  );
}

/** `number`: comma-decimal-tolerant parse, min/max clamp, decimals rounding, plain `String()` serialization (no locale formatting in v1). */
export const numberCellType: CellType<unknown, number | null, GridCellTypes["number"]["options"]> = {
  Cell: NumberCell,
  Editor: NumberEditor,
  toText: (value, options) => {
    if (value == null) return "";
    return String(options?.decimals !== undefined ? roundToDecimals(value, options) : value);
  },
  fromText: (text, options) => {
    const normalized = normalizeNumberText(text);
    if (normalized === "") return null;
    const parsed = Number(normalized);
    if (Number.isNaN(parsed)) return null;
    return roundToDecimals(clampNumber(parsed, options), options);
  },
  clearValue: () => null,
  isEmpty: (value) => value == null,
  compare: (a, b) => {
    if (a == null && b == null) return 0;
    if (a == null) return -1;
    if (b == null) return 1;
    return a - b;
  },
  align: "right",
};

import { useEffect, useRef, useState } from "react";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import type { CellEditorProps, CellRenderProps, CellType, GridCellTypes } from "../types";
import { CellSpan } from "./cell-span";
import { useCommitGuard } from "../interaction/use-commit-guard";
import { columnLabelText } from "../columns/column-format-helpers";

function findChoice(
  choices: readonly { value: string; label: string }[] | undefined,
  raw: string,
): { value: string; label: string } | undefined {
  if (!choices) return undefined;
  const byValue = choices.find((c) => c.value === raw);
  if (byValue) return byValue;
  const lower = raw.toLowerCase();
  return choices.find((c) => c.label.toLowerCase() === lower);
}

function SelectCell({ value, column }: CellRenderProps<unknown, string | null>) {
  const options = column.options as GridCellTypes["select"]["options"] | undefined;
  const choice = value == null ? undefined : findChoice(options?.choices, value);
  return <CellSpan text={choice?.label ?? value ?? ""} />;
}

/** Opens on mount; picking an option commits immediately (no separate confirm step). */
function SelectEditor({ value, onChange, commit, cancel, column, rejectionCount }: CellEditorProps<unknown, string | null>) {
  const options = column.options as GridCellTypes["select"]["options"] | undefined;
  const [open, setOpen] = useState(true);
  const committed = useCommitGuard();

  // Re-arm on each rejection, not on pending->false (that also fires on the cancel right before unmount); see CellEditorProps.rejectionCount.
  const lastRejectionCount = useRef(rejectionCount ?? 0);
  useEffect(() => {
    if ((rejectionCount ?? 0) !== lastRejectionCount.current) committed.reset();
    lastRejectionCount.current = rejectionCount ?? 0;
  }, [rejectionCount, committed]);

  return (
    <Select
      value={value ?? ""}
      open={open}
      onOpenChange={(next) => {
        setOpen(next);
        // picking an option also closes the select, firing this with `next: false` after commit already ran
        if (!next && committed.tryCommit()) cancel();
      }}
      onValueChange={(next) => {
        if (!committed.tryCommit()) return;
        onChange(next === "" || next == null ? null : next);
        commit({ dx: 0, dy: 0 });
      }}
    >
      <SelectTrigger aria-label={columnLabelText(column)} className="size-full justify-start rounded-none border-none p-0 text-sm shadow-none outline-none focus-visible:ring-0 [&_svg]:hidden">
        <SelectValue placeholder="" />
      </SelectTrigger>
      <SelectContent data-grid-cell-editor="">
        {options?.choices.map((choice) => (
          <SelectItem key={choice.value} value={choice.value}>
            {choice.label}
          </SelectItem>
        ))}
      </SelectContent>
    </Select>
  );
}

/** `select`: fromText resolves pasted option values first, then labels (case-insensitive) so pasted labels round-trip. */
export const selectCellType: CellType<unknown, string | null, GridCellTypes["select"]["options"]> = {
  Cell: SelectCell,
  Editor: SelectEditor,
  toText: (value, options) => {
    if (value == null) return "";
    return findChoice(options?.choices, value)?.label ?? value;
  },
  fromText: (text, options) => {
    const trimmed = text.trim();
    if (trimmed === "") return null;
    const choice = findChoice(options?.choices, trimmed);
    return choice?.value ?? null;
  },
  clearValue: () => null,
  isEmpty: (value) => value == null,
  compare: (a, b) => {
    if (a == null && b == null) return 0;
    if (a == null) return -1;
    if (b == null) return 1;
    return a.localeCompare(b);
  },
  align: "left",
};

