/** Extra horizontal padding (px) added around measured text: cell's own inline padding (px-2 = 8px each side) plus a small buffer. */
const CELL_PADDING = 20;

let sharedCanvas: HTMLCanvasElement | null = null;

/** Lazily creates (and caches) the offscreen canvas used for `measureText`; returns null when canvas is unavailable (SSR/jsdom without a 2d context). */
function getMeasureContext(): CanvasRenderingContext2D | null {
  if (typeof document === "undefined") return null;
  if (!sharedCanvas) sharedCanvas = document.createElement("canvas");
  return sharedCanvas.getContext("2d");
}

/**
 * Measures the widest of `texts` (in px) using `font` via canvas `measureText` — far cheaper than
 * a DOM layout pass per candidate string. Returns 0 when no canvas context is available (SSR).
 */
export function measureTextWidths(texts: readonly string[], font: string): number {
  const ctx = getMeasureContext();
  if (!ctx) return 0;
  ctx.font = font;
  let max = 0;
  for (const text of texts) {
    const width = ctx.measureText(text).width;
    if (width > max) max = width;
  }
  return max;
}

/**
 * Autosize measurement for a column's double-click-to-fit gesture: measures the
 * header text plus every CURRENTLY RENDERED cell's text in that column (not the whole dataset —
 * only what's actually mounted), using the grid's own computed font so the measurement matches
 * what's on screen, then clamps to `[minWidth, maxWidth]` and adds cell padding.
 */
export function measureColumnAutosizeWidth(args: {
  headerText: string;
  cellTexts: readonly string[];
  font: string;
  minWidth?: number;
  maxWidth?: number;
}): number {
  const { headerText, cellTexts, font, minWidth = 0, maxWidth = Number.POSITIVE_INFINITY } = args;
  const widest = measureTextWidths([headerText, ...cellTexts], font);
  const target = Math.ceil(widest) + CELL_PADDING;
  return Math.min(Math.max(target, minWidth), maxWidth);
}

import type { AnyColumnDef } from "../store";

/** Cumulative inset-inline-start offsets (px) for pinned-left columns, keyed by column index. */
export function pinLeftOffsets(widths: number[], pins: (AnyColumnDef["pin"] | undefined)[]): number[] {
  const offsets: number[] = [];
  let acc = 0;
  for (let i = 0; i < widths.length; i++) {
    offsets.push(acc);
    if (pins[i] === "left") acc += widths[i]!; // i < widths.length by loop condition
  }
  return offsets;
}

/** Cumulative inset-inline-end offsets (px) for pinned-right columns, keyed by column index. */
export function pinRightOffsets(widths: number[], pins: (AnyColumnDef["pin"] | undefined)[]): number[] {
  const offsets = new Array<number>(widths.length).fill(0);
  let acc = 0;
  for (let i = widths.length - 1; i >= 0; i--) {
    offsets[i] = acc;
    if (pins[i] === "right") acc += widths[i]!; // 0 <= i < widths.length by loop condition
  }
  return offsets;
}

import type { CSSProperties } from "react";
import type { AnyColumnDef } from "../store";

/** Pinned-cell inset style: position:relative works under a transformed ancestor, `position:sticky` doesn't. */
export function pinnedInsetStyle(
  pinned: AnyColumnDef["pin"] | undefined,
  index: number,
): CSSProperties {
  if (!pinned) return {};
  if (pinned === "left") {
    // Cell's flow position is trackLeft, then the ancestor canvas applies -scrollLeft; to land the
    // cell at the static offset regardless of scroll, add scrollLeft back and cancel trackLeft.
    return {
      position: "relative",
      insetInlineStart: `calc(var(--grid-scroll-left, 0px) + var(--grid-pin-left-${index}) - var(--grid-track-left-${index}))`,
    };
  }
  // Pin-right: the cell's right edge must sit `staticRightOffset` from the viewport's right edge,
  // but only floats to that edge once content actually overflows it — diceui's rule — via
  // min(viewportWidth, contentWidth), else it hugs the content's own right edge (no dead gap).
  // rendered_left = trackLeft - scrollLeft + insetInlineStart (canvas transform + this cell's own inset).
  // Solve rendered_left = min(viewportWidth, contentWidth) - staticRightOffset - cellWidth for
  // insetInlineStart, and simplify trackLeft + cellWidth = trackRight:
  //   insetInlineStart = scrollLeft + min(viewportWidth, contentWidth) - staticRightOffset - trackRight
  return {
    position: "relative",
    insetInlineStart: `calc(var(--grid-scroll-left, 0px) + min(var(--grid-viewport-width), var(--grid-content-width)) - var(--grid-pin-right-${index}) - var(--grid-track-right-${index}))`,
  };
}

import type { AnyColumnDef } from "../store";

/** Resolves a column's rendered width in px: live override, else def width, clamped by min/max. */
export function resolveColumnWidth(column: AnyColumnDef, override: number | undefined): number {
  const base = override ?? column.width ?? 150;
  const min = column.minWidth ?? 0;
  const max = column.maxWidth ?? Number.POSITIVE_INFINITY;
  return Math.min(Math.max(base, min), max);
}

/**
 * Grows `baseWidths` to fill positive leftover viewport space, proportional to `flexes`
 * (standard flexbox grow resolution: distribute leftover proportionally, clamp at maxWidth,
 * drop clamped columns from the active set and redistribute their unused share among the rest,
 * iterate until stable). Columns with no/zero flex, or every column when leftover <= 0, keep
 * their base width — a flex column never shrinks below it. Returns `baseWidths` unchanged (same
 * reference) when there's nothing to distribute, a cheap bail for the common non-flex grid.
 */
export function distributeFlexWidths(
  baseWidths: number[],
  flexes: (number | undefined)[],
  maxWidths: number[],
  available: number,
): number[] {
  const totalBase = baseWidths.reduce((a, b) => a + b, 0);
  const totalLeftover = available - totalBase;
  const flexIndices = flexes.reduce<number[]>((acc, f, i) => {
    if (f !== undefined && f > 0) acc.push(i);
    return acc;
  }, []);
  if (totalLeftover <= 0 || flexIndices.length === 0) return baseWidths;

  // exact/widths/floors/result/order below all index by i, which ranges over flexIndices/active —
  // positions derived from flexes/baseWidths, so every indexed access here is in-bounds by construction.
  const exact = baseWidths.slice(); // fractional target width per column, refined each pass
  let active = flexIndices.slice();
  let remainingLeftover = totalLeftover;
  while (active.length > 0 && remainingLeftover > 1e-9) {
    const totalFlex = active.reduce((sum, i) => sum + (flexes[i] as number), 0);
    const stillActive: number[] = [];
    let clampedAway = 0;
    for (const i of active) {
      const share = (remainingLeftover * (flexes[i] as number)) / totalFlex;
      const uncapped = exact[i]! + share;
      const capped = Math.min(uncapped, maxWidths[i]!);
      clampedAway += uncapped - capped;
      exact[i] = capped;
      if (capped < uncapped) continue; // hit its maxWidth — leaves the active set
      stillActive.push(i);
    }
    if (clampedAway <= 1e-9) break; // nothing clamped this pass — fully distributed, stop
    remainingLeftover = clampedAway;
    active = stillActive;
  }

  // Largest-remainder rounding so the sum matches `available` exactly (templates are whole px).
  const widths = baseWidths.slice();
  for (const i of flexIndices) widths[i] = exact[i]!;
  const floors = widths.map(Math.floor);
  let remainder = available - floors.reduce((a, b) => a + b, 0);
  const order = flexIndices.map((i) => ({ i, frac: widths[i]! - floors[i]! })).sort((a, b) => b.frac - a.frac);
  const result = floors.slice();
  for (const { i } of order) {
    if (remainder <= 0) break;
    result[i]! += 1;
    remainder -= 1;
  }
  return result;
}

"use client";

import { ChevronDown, ChevronUp } from "lucide-react";
import type { ReactNode } from "react";
import type { SortSpec } from "../types";

/** Props for {@link DataGridSortIndicator}. */
export type DataGridSortIndicatorProps = {
  columnId: string;
  sortState: readonly SortSpec[];
};

/**
 * Sort direction arrow (muted, size-3.5) for a header, plus its multi-sort priority number when
 * more than one sort is active. Renders nothing when the column isn't sorted.
 */
export function DataGridSortIndicator(props: DataGridSortIndicatorProps): ReactNode {
  const { columnId, sortState } = props;
  const index = sortState.findIndex((s) => s.columnId === columnId);
  if (index === -1) return null;
  const { direction } = sortState[index]!; // index !== -1 checked above, so it's a valid position
  const Icon = direction === "asc" ? ChevronUp : ChevronDown;
  return (
    <span className="ms-1 inline-flex items-center gap-0.5 text-muted-foreground" data-grid-sort-indicator={direction}>
      <Icon className="size-3.5" />
      {sortState.length > 1 && <span className="text-[10px] tabular-nums">{index + 1}</span>}
    </span>
  );
}

/** Resolves a header's `aria-sort` attribute from the active multi-sort spec. */
export function ariaSortFor(columnId: string, sortState: readonly SortSpec[]): "ascending" | "descending" | "none" {
  const entry = sortState.find((s) => s.columnId === columnId);
  if (!entry) return "none";
  return entry.direction === "asc" ? "ascending" : "descending";
}

"use client";

import { useCallback, useEffect, useRef, useState, type PointerEvent as ReactPointerEvent } from "react";

/** px of pointer movement (in the drag-start direction, off the origin header) before a header press commits to reorder-drag. */
const REORDER_THRESHOLD = 5;

/** Live reorder-drag UI state: the dragged column and where the drop indicator should render. */
export type ColumnReorderState = {
  draggingId: string;
  /** Column id the drop indicator renders next to, or null before the pointer has crossed into another header. */
  overId: string | null;
  /** Drop indicator renders before/after `overId`. */
  position: "before" | "after";
};

/** Per-header pointerdown handler + the shared drag state, one instance per `<DataGridHeader>`. */
export type ColumnReorderHandlers = {
  /** Attach to each header's label-zone pointerdown (never the resize-handle zone). */
  onHeaderDragPointerDown: (columnId: string, event: ReactPointerEvent<HTMLElement>) => void;
  dragState: ColumnReorderState | null;
};

/**
 * Drag-to-reorder columns. MUST coexist with the header multi-column select-drag
 * from the interaction layer: both start from a press on the header. The disambiguation rule
 * (documented here as the single source of truth, tested by both the reorder and the select-drag
 * suites): **a horizontal drag that leaves the origin header becomes a reorder drag** whenever
 * `enableColumnReorder` is on and the pressed column is `reorderable`; **Shift+drag is always a
 * select-drag**, regardless of movement, so shift-extending a multi-column selection never
 * accidentally reorders. A plain press+drag that never leaves the origin header (or moves before
 * `REORDER_THRESHOLD`) resolves as a click (selection/sort), matching the existing 5px-jitter rule
 * used elsewhere in the interaction layer.
 */
export function useColumnReorder(args: {
  enabled: boolean;
  isColumnReorderable: (columnId: string) => boolean;
  /** Resolves the header element at a client point to a column id + before/after half, or null off any header. */
  hitTestHeader: (clientX: number, clientY: number) => { columnId: string; position: "before" | "after" } | null;
  onReorder: (id: string, targetId: string, position: "before" | "after") => void;
  /** Called the instant a press arms into a reorder drag — the caller cancels the sibling header column-select drag that started from the same press (see the JSDoc rule above). */
  onArm?: () => void;
}): ColumnReorderHandlers {
  const { enabled, isColumnReorderable } = args;
  const argsRef = useRef(args);
  argsRef.current = args;

  const [dragState, setDragState] = useState<ColumnReorderState | null>(null);
  // mirrors dragState synchronously — the document pointermove listener closes over stale React
  // state otherwise (it's attached once per gesture, not re-subscribed on every setDragState).
  const dragStateRef = useRef<ColumnReorderState | null>(null);
  const pendingRef = useRef<{ columnId: string; startX: number; startY: number; pointerId: number } | null>(null);
  const cleanupRef = useRef<(() => void) | null>(null);

  const setDrag = useCallback((next: ColumnReorderState | null) => {
    dragStateRef.current = next;
    setDragState(next);
  }, []);

  const teardown = useCallback(() => {
    cleanupRef.current?.();
    cleanupRef.current = null;
    pendingRef.current = null;
    setDrag(null);
  }, [setDrag]);

  const onHeaderDragPointerDown = useCallback(
    (columnId: string, event: ReactPointerEvent<HTMLElement>) => {
      if (event.button !== 0) return;
      // Shift+drag is always select-drag (disambiguation rule above) — never arm the reorder path.
      if (event.shiftKey) return;
      if (!enabled || !isColumnReorderable(columnId)) return;

      pendingRef.current = { columnId, startX: event.clientX, startY: event.clientY, pointerId: event.pointerId };

      const handleMove = (e: PointerEvent) => {
        const pending = pendingRef.current;
        if (!pending || e.pointerId !== pending.pointerId) return;

        if (!dragStateRef.current) {
          // not yet armed: only commit to reorder once the horizontal move exceeds the threshold
          // AND has left the origin header (hitTest resolves to a different column).
          const dx = Math.abs(e.clientX - pending.startX);
          if (dx < REORDER_THRESHOLD) return;
          const hit = argsRef.current.hitTestHeader(e.clientX, e.clientY);
          if (!hit || hit.columnId === pending.columnId) return;
          argsRef.current.onArm?.();
          setDrag({ draggingId: pending.columnId, overId: hit.columnId, position: hit.position });
          return;
        }

        const hit = argsRef.current.hitTestHeader(e.clientX, e.clientY);
        const prev = dragStateRef.current;
        setDrag({ ...prev, overId: hit?.columnId ?? null, position: hit?.position ?? prev.position });
      };

      const handleUp = (e: PointerEvent) => {
        const pending = pendingRef.current;
        if (!pending || e.pointerId !== pending.pointerId) return;
        const finalState = dragStateRef.current;
        if (finalState && finalState.overId) {
          argsRef.current.onReorder(finalState.draggingId, finalState.overId, finalState.position);
        }
        teardown();
      };

      document.addEventListener("pointermove", handleMove);
      document.addEventListener("pointerup", handleUp);
      document.addEventListener("pointercancel", handleUp);
      cleanupRef.current = () => {
        document.removeEventListener("pointermove", handleMove);
        document.removeEventListener("pointerup", handleUp);
        document.removeEventListener("pointercancel", handleUp);
      };
    },
    [enabled, isColumnReorderable, setDrag, teardown],
  );

  useEffect(() => teardown, [teardown]);

  return { onHeaderDragPointerDown, dragState };
