  rowHeight?: number;
  /** Fired once per user gesture (edit, delete, paste, fill) with the next data array and an id-keyed delta batch. */
  onDataChange?: (next: readonly TData[], change: DataChange<TData>) => void;
  /** Row-level cross-field validation, once per touched row after a write gesture commits; `columnId -> message` into `cellErrors`, values still commit. See {@link DataGridSyncProps.validateRow}. */
  validateRow?: (row: TData, rowId: string) => Record<string, string> | null;
  /** Undo keymap action (mod+Z); the `data-grid-history` add-on plugs its `undo()` in here. */
  onUndo?: () => void;
  /** Redo keymap action (mod+Y / mod+shift+Z); the `data-grid-history` add-on plugs its `redo()` in here. */
  onRedo?: () => void;
  /**
   * Cell-type registry keyed by `ColumnDef.type`; defaults to the built-in registry. Providing a
   * registry REPLACES the built-ins, it is not merged over them: to extend the built-ins, spread
   * the exported `cellTypes` in (`cellTypes={{ ...cellTypes, myType }}`).
   */
  cellTypes?: Record<string, AnyCellType>;
  /** Overrides a cell's clipboard-copy text; falls back to the cell type's `toText`. */
  processCellForClipboard?: (value: unknown, ctx: ClipboardProcessCtx<TData>) => string;
  /** Overrides parsing pasted text into a cell value; falls back to the cell type's `fromText`. */
  processCellFromClipboard?: (text: string, ctx: ClipboardProcessCtx<TData>) => unknown;
  /** Runs on the parsed paste grid before it's applied; returning `false` vetoes the paste entirely. */
  processPaste?: (cells: string[][], target: CellCoord) => string[][] | false;
  /** Merged over `DEFAULT_KEYMAP`; per-action bindings here take precedence. */
  keymap?: Keymap;
  /** Layout direction; omitted, it follows the page's own direction. See {@link DataGridRootProps.direction}. */
  direction?: GridDirection;
  /** Disables editing and delete grid-wide, independent of any per-column `readOnly`. */
  readOnly?: boolean;
  /** Marker column mode: a pinned-left column rendered before all data columns; default 'none'. */
  rowMarkers?: RowMarkersMode;
  /**
   * Custom row-marker cell renderer: replaces the built-in row number/checkbox content inside the
   * marker column. Requires a non-`'none'` `rowMarkers` mode (the mode still drives the track width,
   * and the cell's own press/drag row-selection gesture stays on the wrapper); an interactive element
   * inside the rendered node owns its own events. See {@link MarkerCellRenderer}. Pass a stable identity.
   */
  renderMarker?: MarkerCellRenderer;
  /** Custom marker-header renderer: replaces the built-in select-all checkbox; same track and width. See {@link MarkerHeaderRenderer}. Pass a stable identity. */
  renderMarkerHeader?: MarkerHeaderRenderer;
  /** Whole-row selection channel gestures (marker click, Shift+Space); default true. */
  enableRowSelection?: boolean;
  /** Whole-column selection channel gestures (header click); default true. */
  enableColumnSelection?: boolean;
  /** Multi-cell rectangular range gestures (shift-click/drag, shift+arrow); false collapses to single-cell active only. Default true. */
  enableRangeSelection?: boolean;
  /** Ctrl/Cmd-click multi-range (rangeStack); false makes it behave as a plain click. Default true. */
  enableMultiRange?: boolean;
  /** Enables the header resize handle grid-wide; default true. Per-column `resizable: false` still wins. */
  enableColumnResize?: boolean;
  /** Enables drag-to-reorder columns grid-wide; default true. Per-column `reorderable: false` still wins. */
  enableColumnReorder?: boolean;
  /** Enables pin/unpin actions grid-wide; default true. Per-column `pinnable: false` still wins. */
  enableColumnPinning?: boolean;
  /** How a plain header click behaves; default 'select'. See {@link HeaderClickBehavior}. */
  headerClickBehavior?: HeaderClickBehavior;
  /** Partial i18n override, deep-merged over `DEFAULT_LABELS`; see {@link useDataGridLabels}. */
  labels?: DeepPartialLabels;
  /** Builds a new row for `insertRow`; absent makes `insertRow` a dev-warning no-op. */
  createRow?: (index: number) => TData;
  /**
   * Builds a duplicated row's identity for `duplicateRows`: given the source row and its new data
   * index, returns the row to insert (with a distinct id). Absent makes `duplicateRows` a
   * dev-warning no-op — mirrors `createRow`/`insertRow`.
   */
  duplicateRow?: (row: TData, index: number) => TData;
  /** Controlled multi-sort spec (server escape hatch); omit for uncontrolled (store-owned) sort state. */
  sortState?: SortSpec[];
  /** Fires whenever the sort would change, controlled or not. */
  onSortChange?: (next: SortSpec[]) => void;
  /** Controlled filter spec; same controlled/uncontrolled semantics as `sortState`. */
  filterState?: FilterSpec[];
  /** Fires whenever the filters would change, controlled or not. */
  onFilterChange?: (next: FilterSpec[]) => void;
  /** Controlled join operator combining `filterState`'s rows; same controlled/uncontrolled semantics as `sortState`. Default `"and"`. */
  joinOperator?: FilterJoinOperator;
  /** Fires whenever the join operator would change, controlled or not. */
  onJoinOperatorChange?: (next: FilterJoinOperator) => void;
  /** Controlled quick-search text; same controlled/uncontrolled semantics as `sortState`. */
  searchText?: string;
  /** Fires whenever the search text would change, controlled or not. */
  onSearchTextChange?: (next: string) => void;
  /** Overlay-plugin registration — see `DataGridSyncProps.overlayPlugins` for the full contract; `data-grid-presence` is the motivating consumer. Pass a stable array reference. */
  overlayPlugins?: readonly OverlayPlugin[];
  /** Row-bands registration — see `DataGridSyncProps.rowBands` for the full contract; `data-grid-pinned-rows`'s `useDataGridPinnedRows()` is the motivating (and so far only) producer. Pass a stable reference. */
  rowBands?: RowBandsSpec;
  /** Seeds column widths/order/pins/hidden once at mount, over the `columns` prop's own defaults; NOT controlled — later changes are ignored. Pair with `onColumnLayoutChange` to persist a user's layout. */
  defaultColumnLayout?: ColumnLayout;
  /** Fires once per committed column-layout change (resize commit, reorder drop, pin/hide/autosize) with the full current snapshot. */
  onColumnLayoutChange?: (next: ColumnLayout) => void;
  /** Fires on every live width write during a resize drag (per drag frame) — the in-progress counterpart to `onColumnLayoutChange`. */
  onColumnResizing?: (columnId: string, width: number) => void;
  /** Fires on every committed selection change (click, extend step, row/column/all selection, clear) with a lazy `details.getValues()` accessor; drag-extend fires once per step. */
  onSelectionChange?: (next: GridSelection, details: SelectionChangeDetails) => void;
  /** Fires exactly once when the selection transitions from non-empty to empty, from any clear path. */
  onSelectionCleared?: () => void;
  /** Row-height preset: compact 28 / default 36 / comfortable 44. Ignored when `rowHeight` is set. */
  density?: DensityMode;
  /** Row class hook, merged via `cn()` after the built-in row classes. Pass a stable identity. */
  getRowClassName?: GetRowClassName<TData>;
  /** Cell class hook, merged via `cn()` after the built-in cell classes. Pass a stable identity. */
  getCellClassName?: GetCellClassName<TData>;
  /** Fired on a plain click on any cell — see {@link OnCellClick}. Attached to the cell's own existing click handler, no new subscription. Pass a stable identity. */
  onCellClick?: OnCellClick<TData>;
  /** Fired alongside `onCellClick` once per click regardless of column — see {@link OnRowClick}. */
  onRowClick?: OnRowClick<TData>;
  /** Rendered centered in place of the body when there are zero rows in view. Never shown while `loading` is true. */
  emptyState?: ReactNode;
  /** Presentational loading flag: zero rows renders a viewport-filling skeleton instead of the empty state; rows present adds a slim indeterminate bar under the header. Default `false`. See {@link DataGridRootProps.loading}. */
  loading?: boolean;
  /** Fired after a row-window commit with the rendered data-row range; see {@link DataGridRootProps.onRowWindowChange}. */
  onRowWindowChange?: (range: { start: number; end: number }) => void;
  /** Composition escape hatch; defaults to header + body when omitted. */
  children?: ReactNode;
};

/**
 * Convenience wrapper: provider + scroll root + header + body. Compose the
 * parts directly (`DataGridProvider`/`DataGridRoot`/`DataGridHeader`/`DataGridBody`)
 * for custom layouts (toolbar, overlays, context menu).
 */
export function DataGrid<TData>(props: DataGridProps<TData>): ReactNode {
  const {
    data,
    defaultData,
    columns,
    getRowId,
    className,
    rowHeight,
    onDataChange,
    validateRow,
    onUndo,
    onRedo,
    cellTypes,
    processCellForClipboard,
    processCellFromClipboard,
    processPaste,
    keymap,
    direction,
    readOnly,
    rowMarkers,
    renderMarker,
    renderMarkerHeader,
    enableRowSelection,
    enableColumnSelection,
    enableRangeSelection,
    enableMultiRange,
    enableColumnResize,
    enableColumnReorder,
    enableColumnPinning,
    headerClickBehavior,
    labels,
    createRow,
    duplicateRow,
    sortState,
    onSortChange,
    filterState,
    onFilterChange,
    joinOperator,
    onJoinOperatorChange,
    searchText,
    onSearchTextChange,
    overlayPlugins,
    rowBands,
    defaultColumnLayout,
    onColumnLayoutChange,
    onColumnResizing,
    onSelectionChange,
    onSelectionCleared,
    density,
    getRowClassName,
    getCellClassName,
    onCellClick,
    onRowClick,
    emptyState,
    loading,
    onRowWindowChange,
    children,
  } = props;

  // erasure boundary for the root-level callbacks: TData narrows to the root's unknown — safe for
  // the same reason as toInternalSyncProps (store.tsx): every row these callbacks ever receive
  // originated from this DataGrid's own TData-typed `data`.
  const erasedRowClassName = getRowClassName as GetRowClassName<unknown> | undefined;
  const erasedCellClassName = getCellClassName as GetCellClassName<unknown> | undefined;
  const erasedOnCellClick = onCellClick as OnCellClick<unknown> | undefined;
  const erasedOnRowClick = onRowClick as OnRowClick<unknown> | undefined;

  return (
    <DataGridProvider
      data={data}
      defaultData={defaultData}
      columns={columns}
      getRowId={getRowId}
      onDataChange={onDataChange}
      validateRow={validateRow}
      onUndo={onUndo}
      onRedo={onRedo}
      cellTypes={cellTypes}
      processCellForClipboard={processCellForClipboard}
      processCellFromClipboard={processCellFromClipboard}
      processPaste={processPaste}
      rowMarkers={rowMarkers}
      enableRowSelection={enableRowSelection}
      enableColumnSelection={enableColumnSelection}
      enableRangeSelection={enableRangeSelection}
      enableMultiRange={enableMultiRange}
      enableColumnResize={enableColumnResize}
      enableColumnReorder={enableColumnReorder}
      enableColumnPinning={enableColumnPinning}
      headerClickBehavior={headerClickBehavior}
      labels={labels}
      createRow={createRow}
      duplicateRow={duplicateRow}
      sortState={sortState}
      onSortChange={onSortChange}
      filterState={filterState}
      onFilterChange={onFilterChange}
      joinOperator={joinOperator}
      onJoinOperatorChange={onJoinOperatorChange}
      searchText={searchText}
      onSearchTextChange={onSearchTextChange}
      overlayPlugins={overlayPlugins}
      rowBands={rowBands}
      defaultColumnLayout={defaultColumnLayout}
      onColumnLayoutChange={onColumnLayoutChange}
      onColumnResizing={onColumnResizing}
      onSelectionChange={onSelectionChange}
      onSelectionCleared={onSelectionCleared}
    >
      <DataGridRoot
        className={className}
        rowHeight={rowHeight}
        density={density}
        keymap={keymap}
        direction={direction}
        readOnly={readOnly}
        renderMarker={renderMarker}
        renderMarkerHeader={renderMarkerHeader}
        emptyState={emptyState}
        loading={loading}
        getRowClassName={erasedRowClassName}
        getCellClassName={erasedCellClassName}
        onCellClick={erasedOnCellClick}
        onRowClick={erasedOnRowClick}
        onRowWindowChange={onRowWindowChange}
      >
        {children ?? (
          <>
            <DataGridHeader />
            <DataGridBody />
          </>
        )}
      </DataGridRoot>
    </DataGridProvider>
  );
}

"use client";

import { useCallback, useRef, type CSSProperties, type MouseEvent as ReactMouseEvent, type PointerEvent as ReactPointerEvent, type ReactNode } from "react";
import { ChevronDown } from "lucide-react";
import { cn } from "@/lib/utils";
import type { HeaderClickBehavior, SortSpec } from "./types";
import { pinnedInsetStyle } from "./columns/pinned-inset-style";
import { useColumnResize, readRenderedCellTexts } from "./columns/use-column-resize";
import { DataGridSortIndicator, ariaSortFor } from "./columns/sort-indicator";
import type { ColumnReorderState } from "./columns/use-column-reorder";
import type { HeaderMenuRenderer } from "./layout-context";
import type { GridDirection } from "./windowing/direction";
import { useDataGridLabels, type AnyColumnDef } from "./store";
import { columnLabelText as headerLabelText } from "./columns/column-format-helpers";
import { gridAttrSelector } from "./data-attributes";

/** Props for {@link DataGridHeaderCell}. */
export type DataGridHeaderCellProps = {
  column: AnyColumnDef;
  index: number;
  width: number;
  gridColOffset: number;
  headerClickBehavior: HeaderClickBehavior;
  sortState: readonly SortSpec[];
  resize: {
    enabled: boolean;
    scrollRootRef: React.RefObject<HTMLElement | null>;
    setColumnWidth: (id: string, width: number) => void;
    commitColumnWidth: (id: string, width: number) => void;
    /** Signs the drag delta so the handle always widens toward the inline end — see {@link useColumnResize}. */
    direction: GridDirection;
  };
  reorder: {
    enabled: boolean;
    state: ColumnReorderState | null;
    onPointerDown: (columnId: string, event: ReactPointerEvent<HTMLElement>) => void;
  };
  onSelect: (index: number, event: ReactPointerEvent<HTMLElement>) => void;
  onSort: (columnId: string, additive: boolean) => void;
  /** Optional per-column header menu slot (root `renderHeaderMenu` prop) — renders a ghost chevron trigger when provided. */
  renderHeaderMenu?: HeaderMenuRenderer;
};

/**
 * One header cell: label + sort indicator, a resize handle at the inline-end edge, and the
 * drag-to-reorder press zone over the label. See {@link import("./use-column-reorder").useColumnReorder}
 * for the full select-vs-reorder disambiguation rule this cell's two pointerdown handlers resolve.
 */
export function DataGridHeaderCell(props: DataGridHeaderCellProps): ReactNode {
  const {
    column,
    index,
    width,
    gridColOffset,
    headerClickBehavior,
    sortState,
    resize: resizeProps,
    reorder,
    onSelect,
    onSort,
    renderHeaderMenu,
  } = props;

  const labels = useDataGridLabels();
  const pinned = column.pin;
  const cellRef = useRef<HTMLDivElement | null>(null);
  const columnResizable = resizeProps.enabled && (column.resizable ?? true);

  const getRenderedCellTexts = useCallback(
    (columnId: string) => readRenderedCellTexts(resizeProps.scrollRootRef.current, columnId),
    [resizeProps.scrollRootRef],
  );
  const resize = useColumnResize({
    column,
    currentWidth: width,
    setColumnWidth: resizeProps.setColumnWidth,
    commitColumnWidth: resizeProps.commitColumnWidth,
    getRenderedCellTexts,
    fontSourceRef: cellRef,
    direction: resizeProps.direction,
  });

  const style: CSSProperties = {
    gridRowStart: 1,
    gridColumnStart: index + gridColOffset,
    zIndex: pinned ? 3 : 2,
    ...pinnedInsetStyle(pinned, index),
  };

  const isDragging = reorder.state?.draggingId === column.id;

  const handleLabelPointerDown = useCallback(
    (event: ReactPointerEvent<HTMLElement>) => {
      // the header menu's popup is a React portal: its events still bubble through the REACT tree
      // (not the DOM tree) up to this handler, so a click on e.g. "Hide column" would otherwise also
      // fire the column-select gesture here — bail out for any event actually targeting the popup.
      if ((event.target as HTMLElement).closest(gridAttrSelector("headerMenuPopup"))) return;
      // 'sort' mode reassigns the plain click to sorting (handleClick below); the column-select
      // gesture (and its press+drag range-select) only applies in the default 'select' mode.
      if (headerClickBehavior === "select") onSelect(index, event);
      if (reorder.enabled) reorder.onPointerDown(column.id, event);
    },
    [headerClickBehavior, onSelect, index, reorder, column.id],
  );

  const handleClick = useCallback(
    (event: ReactMouseEvent<HTMLElement>) => {
      if ((event.target as HTMLElement).closest(gridAttrSelector("headerMenuPopup"))) return;
      if (headerClickBehavior !== "sort" || column.sortable === false) return;
      onSort(column.id, event.shiftKey);
    },
    [headerClickBehavior, column.sortable, onSort, column.id],
  );

  return (
    <div
      ref={cellRef}
      role="columnheader"
      aria-colindex={index + 1}
      aria-sort={headerClickBehavior === "sort" && column.sortable !== false ? ariaSortFor(column.id, sortState) : undefined}
      data-column-id={column.id}
      data-pinned={pinned || undefined}
      data-dragging={isDragging || undefined}
      className={cn(
        "group relative flex items-center border-b border-border bg-muted px-2 font-medium select-none",
        isDragging && "opacity-50",
        column.headerClassName,
      )}
      style={style}
      onPointerDown={handleLabelPointerDown}
      onClick={handleClick}
      onDoubleClick={(event) => event.stopPropagation()}
    >
      {typeof column.header === "string" ? <span className="truncate">{column.header}</span> : column.header}
      {/* A custom (ReactNode) header owns its display, so the built-in arrow is only appended for string headers;
          embed DataGridSortIndicator inside a custom header when you still want it. */}
      {headerClickBehavior === "sort" && column.sortable !== false && typeof column.header === "string" && (
        <DataGridSortIndicator columnId={column.id} sortState={sortState} />
      )}
      {renderHeaderMenu &&
        renderHeaderMenu({
          column,
          index,
          trigger: (
            <button
              type="button"
              data-grid-header-menu-trigger=""
              aria-label={labels.contextMenu.columnMenuAriaLabel(headerLabelText(column))}
              className="ms-auto shrink-0 rounded p-0.5 text-muted-foreground opacity-0 outline-none transition-opacity hover:bg-accent hover:text-accent-foreground focus:opacity-100 group-hover:opacity-100"
              onPointerDown={(event) => event.stopPropagation()}
              onClick={(event) => event.stopPropagation()}
            >
              <ChevronDown className="size-3.5" />
            </button>
          ),
        })}
      {columnResizable && (
        <div
          data-grid-resize-handle=""
          data-resizing={resize.isResizing || undefined}
          role="presentation"
          className="absolute end-0 top-0 z-10 h-full w-2 cursor-col-resize touch-none after:absolute after:inset-y-1.5 after:end-[2px] after:w-[3px] after:rounded-full after:bg-primary after:opacity-0 after:transition-opacity hover:after:opacity-60 data-[resizing]:after:opacity-100"
          style={{ touchAction: "none" }}
          onPointerDown={resize.onPointerDown}
          onDoubleClick={resize.onDoubleClick}
          onClick={(event) => event.stopPropagation()}
        />
      )}
    </div>
  );
}

"use client";

import { useCallback, useMemo, type CSSProperties, type ReactNode } from "react";
import { useDataGridRootContext } from "./layout-context";
import {
  useDataGridActions,
  useDataGridColumnFeatureFlags,
  useDataGridHeaderClickBehavior,
  useDataGridRowMarkers,
  useDataGridSortState,
} from "./store";
import { DataGridMarkerHeader } from "./rows/marker-header";
import { DataGridHeaderCell } from "./header-cell";
import { useColumnReorder } from "./columns/use-column-reorder";
import { pinnedInsetStyle } from "./columns/pinned-inset-style";
import { GRID_LAYER } from "./layers";
import { isInlineStartHalf } from "./windowing/direction";

/**
 * Header layer: absolutely positioned inside the sticky Viewport, counter-translated
 * horizontally by the live scroll var so it tracks the canvas 1:1 without ever moving via native
 * scroll. Renders only the windowed column set (same window the body consumes).
 *
 * Data-column grid placement is `index + markerColOffset` (1-based `gridColumnStart`): the marker
 * column (when present) occupies track 1, so every data column shifts one track right. `index`
 * itself, `aria-colindex`, and `aria-colcount` (set on the grid root) are all untouched by this —
 * the marker carries no `aria-colindex` at all and sits outside the data header's a11y column
 * count (chosen over shifting every data cell's aria-colindex by one).
 */
export function DataGridHeader(): ReactNode {
  const { scrollRef, windowedColumns, template, layout, headerHeight, interaction, direction, renderHeaderMenu } = useDataGridRootContext();
  const rowMarkers = useDataGridRowMarkers();
  const actions = useDataGridActions();
  const sortState = useDataGridSortState();
  const headerClickBehavior = useDataGridHeaderClickBehavior();
  const { enableColumnResize, enableColumnReorder } = useDataGridColumnFeatureFlags();
  const markerColOffset = layout.markerWidth > 0 ? 2 : 1;

  /** Resolves the header cell (and before/after half) under a client point, for the reorder drag's live drop target. */
  const hitTestHeader = useCallback(
    (clientX: number, clientY: number) => {
      const el = document.elementFromPoint(clientX, clientY)?.closest<HTMLElement>("[role='columnheader'][data-column-id]");
      if (!el) return null;
      const rect = el.getBoundingClientRect();
      // guaranteed present: the closest() selector above only matches elements with [data-column-id]
      const columnId = el.dataset["columnId"]!;
      // "before"/"after" stay logical (reading order): the inline-START half is "before" in both
      // directions, which under RTL is the header's physical RIGHT half.
      const position: "before" | "after" = isInlineStartHalf(clientX, rect, direction) ? "before" : "after";
      return { columnId, position };
    },
    [direction],
  );

  const isColumnReorderable = useCallback(
    (columnId: string) => windowedColumns.some(({ column }) => column.id === columnId && column.reorderable !== false),
    [windowedColumns],
  );

  const { onHeaderDragPointerDown, dragState } = useColumnReorder({
    enabled: enableColumnReorder,
    isColumnReorderable,
    hitTestHeader,
    onReorder: actions.setColumnOrder,
    onArm: interaction.cancelColumnSelectDrag,
  });

  /**
   * Single drop-indicator line at the reorder drag's current boundary. Grid-placed on the boundary
   * column's own track: an unpinned column gets raw track coords (the header layer already
   * translates by -scrollLeft), a pinned boundary column reuses the exact pinned-cell offset,
   * so the line lands at the cell's rendered edge either way.
   */
  const dropIndicator = useMemo<{ index: number; style: CSSProperties } | null>(() => {
    if (!dragState?.overId) return null;
    const over = windowedColumns.find(({ column }) => column.id === dragState.overId);
    if (!over) return null;
    const { column, index } = over;
    const width = layout.widths[index];
    const pinStyle = pinnedInsetStyle(column.pin, index);
    // unpinned: the div is grid-placed on the boundary column's own track (raw track coords, like
    // any other header cell), so its local left edge is 0 — "after" just adds the column's width.
    // pinned: pinnedInsetStyle's insetInlineStart already lands this div at the pinned cell's own
    // rendered left edge (same track, same formula) — "after" shifts that by the column's width too.
    const insetInlineStart =
      dragState.position === "before"
        ? (pinStyle.insetInlineStart ?? 0)
        : pinStyle.insetInlineStart
          ? `calc(${pinStyle.insetInlineStart} + ${width}px)`
          : width;
    const style: CSSProperties = {
      gridRowStart: 1,
      gridColumnStart: index + markerColOffset,
      position: "relative",
      insetBlockStart: 0,
      insetInlineStart,
      height: "100%",
      width: 2,
      zIndex: GRID_LAYER.header,
      pointerEvents: "none",
      backgroundColor: "var(--color-primary)",
    };
    return { index, style };
  }, [dragState, windowedColumns, layout.widths, markerColOffset]);

  const layerStyle: CSSProperties = {
    position: "absolute",
    insetBlockStart: 0,
    insetInlineStart: 0,
    display: "grid",
    gridTemplateColumns: template,
    gridAutoRows: headerHeight,
    // stacking context (transform) painted after the rows canvas in DOM order; without an explicit
    // z-index the canvas's own stacking context wins paint order and buries the header on scroll.
    zIndex: GRID_LAYER.pinnedHeader,
    // header never moves vertically — only the canvas does — so only the horizontal term applies here.
    // --grid-dir signs it for RTL (see body.tsx's canvas transform for the full reasoning).
    transform: "translate3d(calc(var(--grid-dir, -1) * var(--grid-scroll-left, 0px)), 0, 0)",
  };
  return (
    <div role="row" style={layerStyle} data-grid-header-layer="">
      {layout.markerWidth > 0 && <DataGridMarkerHeader mode={rowMarkers} headerHeight={headerHeight} />}
      {windowedColumns.map(({ column, index }) => (
        <DataGridHeaderCell
          key={column.id}
          column={column}
          index={index}
          width={layout.widths[index]!} // index is a real index into columns; layout.widths is columns.map(...), same length
          gridColOffset={markerColOffset}
          headerClickBehavior={headerClickBehavior}
          sortState={sortState}
          resize={{
            enabled: enableColumnResize,
            scrollRootRef: scrollRef,
            setColumnWidth: actions.setColumnWidth,
            commitColumnWidth: actions.commitColumnWidth,
            direction,
          }}
          reorder={{
            enabled: enableColumnReorder,
            state: dragState,
            onPointerDown: onHeaderDragPointerDown,
          }}
          onSelect={interaction.onHeaderPointerDown}
          onSort={actions.toggleSort}
          renderHeaderMenu={renderHeaderMenu}
        />
      ))}
      {dragState && dropIndicator && <div data-grid-drop-indicator="" aria-hidden="true" style={dropIndicator.style} />}
    </div>
  );
}

import type { DataChange, DataOp } from "../types";

/** Inverts a single op: update swaps row/prev, insert becomes delete, delete becomes insert. */
function invertOp<TData>(op: DataOp<TData>): DataOp<TData> {
  switch (op.type) {
    case "update":
      return {
        type: "update",
        rowId: op.rowId,
        row: op.prev,
        prev: op.row,
        cells: op.cells?.map((cell) => ({
          columnId: cell.columnId,
          value: cell.prev,
          prev: cell.value,
        })),
      };
    case "insert":
      return { type: "delete", rowId: op.rowId, row: op.row, index: op.index };
    case "delete":
      return { type: "insert", rowId: op.rowId, row: op.row, index: op.index };
  }
}

/**
 * Produces the change that undoes `change`: each op is inverted and the op
 * order is reversed (so a batch unwinds in the correct dependency order).
 */
export function invertChange<TData>(change: DataChange<TData>): DataChange<TData> {
  return {
    ops: [...change.ops].reverse().map(invertOp),
    source: "history",
    label: change.label,
  };
}

/**
 * Applies a change to `data` immutably in O(n + k log(n + k)), returning a new array.
 * Rows are located by id (never by the op's stored index, which is only a
 * hint for where an insert should land). If an id referenced by an
 * update/delete op is no longer present (row was deleted by a later change),
 * that op is skipped silently rather than throwing.
 *
 * `index` convention: op indices are snapshot positions — each op's index
 * is that row's position in the array as it stood before the whole batch
 * was applied (the natural output of a delete-range/insert-range emitter),
 * not a running "log-time" position updated op-by-op. update/delete ops
 * are id-keyed so their index is informational only; insert ops (including
 * ones produced by inverting a delete batch) are therefore applied in
 * ascending-index order regardless of the order they appear in `ops`, so a
 * multi-row batch round-trips through invertChange correctly.
 */
export function applyChange<TData>(
  data: readonly TData[],
  change: DataChange<TData>,
  getRowId: (row: TData, index: number) => string,
): TData[] {
  const indexById = new Map<string, number>();
  const idByIndex = new Array<string>(data.length);
  let hasDuplicateId = false;
  for (let i = 0; i < data.length; i++) {
    const id = getRowId(data[i]!, i);
    idByIndex[i] = id;
    if (indexById.has(id)) hasDuplicateId = true;
    else indexById.set(id, i);
  }

  const deleteIndices = new Set<number>();
  const inserts: Extract<DataOp<TData>, { type: "insert" }>[] = [];
  let postDelete: TData[];

  if (!hasDuplicateId) {
    const updateById = new Map<string, TData>();
    for (const op of change.ops) {
      if (op.type === "insert") {
        inserts.push(op);
        continue;
      }
      const idx = indexById.get(op.rowId);
      if (idx === undefined) continue;
      if (op.type === "update") updateById.set(op.rowId, op.row);
      else deleteIndices.add(idx);
    }

    postDelete = [];
    for (let i = 0; i < data.length; i++) {
      if (deleteIndices.has(i)) continue;
      const id = idByIndex[i]!;
      const updated = updateById.get(id);
      postDelete.push(updated !== undefined ? updated : data[i]!);
    }
  } else {
    // Duplicate row ids are invalid, but this path preserves the legacy first-occurrence scan.
    const indicesById = new Map<string, number[]>();
    for (let i = 0; i < data.length; i++) {
      const id = idByIndex[i]!;
      const indices = indicesById.get(id);
      if (indices) indices.push(i);
      else indicesById.set(id, [i]);
    }

    const opsById = new Map<string, DataOp<TData>[]>();
    for (const op of change.ops) {
      if (op.type === "insert") {
        inserts.push(op);
        continue;
      }
      const ops = opsById.get(op.rowId);
      if (ops) ops.push(op);
      else opsById.set(op.rowId, [op]);
    }

    const updateByIndex = new Map<number, TData>();
    for (const idOps of opsById.values()) {
      const indices = indicesById.get(idOps[0]!.rowId);
      if (!indices) continue;
      let next = 0;
      for (const op of idOps) {
        if (next >= indices.length) break;
        const target = indices[next]!;
        if (op.type === "update") {
          updateByIndex.set(target, op.row);
        } else {
          deleteIndices.add(target);
          next++;
        }
      }
    }

    postDelete = [];
    for (let i = 0; i < data.length; i++) {
      if (deleteIndices.has(i)) continue;
      postDelete.push(updateByIndex.get(i) ?? data[i]!);
    }
  }

  const sorted = [...inserts].sort((a, b) => a.index - b.index);
  const total = postDelete.length + sorted.length;
  if (total === 0) return [];

  // Fenwick slot placement reproduces the legacy clamped insert order.
  const bit = new Int32Array(total + 1);
  for (let i = 1; i <= total; i++) bit[i] = i & -i;
  const insertAt = new Int32Array(total).fill(-1);
  const addFree = (pos: number) => {
    for (let i = pos + 1; i <= total; i += i & -i) bit[i]!--;
  };
  const findFreeSlot = (rank: number): number => {
    let idx = 0;
    let target = rank;
    let mask = 1 << Math.floor(Math.log2(total));
    while (mask !== 0) {
      const next = idx + mask;
      if (next <= total && bit[next]! < target) {
        idx = next;
        target -= bit[next]!;
      }
      mask >>= 1;
    }
    return idx;
  };

  for (let q = sorted.length - 1; q >= 0; q--) {
    const at = Math.min(sorted[q]!.index, postDelete.length + q);
    const pos = findFreeSlot(at + 1);
    insertAt[pos] = q;
    addFree(pos);
  }

  const out = new Array<TData>(total);
  let original = 0;
  for (let pos = 0; pos < total; pos++) {
    const q = insertAt[pos]!;
    out[pos] = q === -1 ? postDelete[original++]! : sorted[q]!.row;
  }
  return out;
}

/** Options for {@link createHistory}. */
export type HistoryOptions = {
  /** Maximum number of entries kept on the undo stack; oldest entries are dropped past this. */
  capacity?: number;
};

/**
 * Op-based undo/redo stack, UI-free. Consumers call `push` after each
 * applied gesture, and `undo`/`redo` to get the change to apply back to data.
 */
export type History<TData> = {
  /** Records a change; discards any redo branch. Changes with source "history" are ignored. */
  push(change: DataChange<TData>): void;
  /** Returns the inverted top-of-undo-stack change to apply, or null if nothing to undo. */
  undo(): DataChange<TData> | null;
  /** Returns the original change, re-tagged source "history", to re-apply; or null if nothing to redo. */
  redo(): DataChange<TData> | null;
  /** Whether `undo()` would return a change. */
  readonly canUndo: boolean;
  /** Whether `redo()` would return a change. */
  readonly canRedo: boolean;
  /** Clears both stacks. */
  clear(): void;
  /** Number of entries on the undo stack. */
  readonly size: number;
};

/** Creates an id-keyed undo/redo history. */
export function createHistory<TData>(opts: HistoryOptions = {}): History<TData> {
  const capacity = opts.capacity ?? 100;
  let undoStack: DataChange<TData>[] = [];
  let redoStack: DataChange<TData>[] = [];

  return {
    push(change) {
      if (change.source === "history") return;
      undoStack.push(change);
      if (undoStack.length > capacity) undoStack.shift();
      redoStack = [];
    },
    undo() {
      const change = undoStack.pop();
      if (!change) return null;
      redoStack.push(change);
      return invertChange(change);
    },
    redo() {
      const change = redoStack.pop();
      if (!change) return null;
      undoStack.push(change);
      return { ...change, source: "history" };
    },
    get canUndo() {
      return undoStack.length > 0;
    },
    get canRedo() {
      return redoStack.length > 0;
    },
    clear() {
      undoStack = [];
      redoStack = [];
    },
    get size() {
      return undoStack.length;
    },
  };
}

