import { markerWidth } from "./rows/marker-width";
import type { GridInteractionHandlers } from "./interaction/use-grid-interaction";
import type { GridDirection } from "./windowing/direction";

/** Cumulative left edge (px) of each column's track within the full grid template. */
function trackLefts(widths: number[]): number[] {
  const lefts: number[] = [];
  let acc = 0;
  for (let i = 0; i < widths.length; i++) {
    lefts.push(acc);
    acc += widths[i]!; // i < widths.length by loop condition
  }
  return lefts;
}

/** Cumulative right edge (px) of each column's track within the full grid template. */
function trackRights(widths: number[], lefts: number[]): number[] {
  // lefts is trackLefts(widths)'s output: same length as widths by construction
  return widths.map((w, i) => lefts[i]! + w);
}

/**
 * Shared per-column layout used by header cells, data cells, and the grid template.
 * The marker column (when `markerWidth > 0`) is grid-template-column 1, BEFORE every data
 * column and before any pinned-left data column — data columns render at
 * `gridColumnStart: index + (markerWidth > 0 ? 2 : 1)`. `trackLefts`/`trackRights`/`leftOffsets`
 * are already shifted by `markerWidth` so callers never add it themselves; `CellCoord.col` and
 * this array's own `index` stay pure data-column indices throughout (the marker lives
 * outside the data index space).
 */
export type ColumnLayout = {
  template: string;
  leftOffsets: number[];
  rightOffsets: number[];
  trackLefts: number[];
  trackRights: number[];
  widths: number[];
  pins: (AnyColumnDef["pin"] | undefined)[];
  totalWidth: number;
  /** 0 when `rowMarkers` is 'none' — no marker track is added. */
  markerWidth: number;
};

/**
 * Computes shared column layout (widths, pin offsets, grid-template string) from live width
 * overrides. `availableWidth` is the viewport's clientWidth (excludes the scrollbar) used to
 * distribute `flex` leftover space; 0 on first render/SSR before measurement, which correctly
 * bails flex distribution to base widths until the real measurement lands.
 */
export function useColumnLayout(columns: readonly AnyColumnDef[], availableWidth = 0): ColumnLayout {
  const ids = useMemo(() => columns.map((c) => c.id), [columns]);
  const overrides = useDataGridColumnWidths(ids);
  const rowMarkers = useDataGridRowMarkers();
  return useMemo(() => {
    const mWidth = markerWidth(rowMarkers);
    const baseWidths = columns.map((column, i) => resolveColumnWidth(column, overrides[i]));
    // Manual resize (a live override) fixes the column and removes it from flex distribution.
    const flexes = columns.map((column, i) => (overrides[i] === undefined ? column.flex : undefined));
    const maxWidths = columns.map((column) => column.maxWidth ?? Number.POSITIVE_INFINITY);
    const widths = distributeFlexWidths(baseWidths, flexes, maxWidths, Math.max(0, availableWidth - mWidth));
    const pins = columns.map((c) => c.pin);
    const lefts = trackLefts(widths).map((l) => l + mWidth);
    const dataTemplate = encodeTemplate(widths);
    return {
      template: mWidth > 0 ? `${mWidth}px ${dataTemplate}` : dataTemplate,
      // the marker column is always pinned-left before any pinned data column, so every
      // pin-left offset shifts by its width; pin-right is unaffected (marker never pins right).
      leftOffsets: pinLeftOffsets(widths, pins).map((o) => o + mWidth),
      rightOffsets: pinRightOffsets(widths, pins),
      trackLefts: lefts,
      trackRights: trackRights(widths, lefts),
      widths,
      pins,
      totalWidth: widths.reduce((a, b) => a + b, 0) + mWidth,
      markerWidth: mWidth,
    };
  }, [columns, overrides, rowMarkers, availableWidth]);
}

/** A visible column paired with its real (unwindowed) index, used for grid placement + pin var lookup. */
export type WindowedColumn = { column: AnyColumnDef; index: number };

/**
 * Context passed to {@link RowBandsSpec.renderBand} for one band — exactly what root.tsx computes
 * for the band's render. `ariaRowIndexBase` is root's own aria index-layout math (header=1, top
 * band next, then data rows, bottom band last), so the add-on never has to know rowCount or the
 * other band's length.
 */
export type RowBandRenderCtx = {
  position: "top" | "bottom";
  rows: readonly unknown[];
  windowedColumns: readonly WindowedColumn[];
  layout: ColumnLayout;
  rowHeight: number;
  template: string;
  /** The sticky header track's own height (not including either band). */
  headerHeight: number;
  ariaRowIndexBase: number;
};

/**
 * Provider-level row-bands seam: unlike `overlayPlugins` (pure paint, no layout impact), bands
 * affect band heights and `aria-rowcount`, which root.tsx must know SYNCHRONOUSLY at first render
 * (SSR + no one-frame layout shift) — so this is a spec object, not a mount-effect registration
 * like `fillHandlers`. Core only reads `topRows.length`/`bottomRows.length` for its own arithmetic
 * and calls `renderBand`; it never inspects the row contents. `data-grid-pinned-rows`'s
 * `useDataGridPinnedRows` is the motivating (and so far only) producer.
 */
export type RowBandsSpec = {
  topRows: readonly unknown[];
  bottomRows: readonly unknown[];
  renderBand: (ctx: RowBandRenderCtx) => ReactNode;
};

/**
 * Render-prop for the per-column header menu slot: the primary pin/sort surface. `trigger` is the
 * core's own ghost-chevron button element — the renderer wraps it as its dropdown's trigger
 * (e.g. `<DropdownMenuTrigger render={trigger} />`) so core keeps sole ownership of the trigger's
 * visuals/aria-label while the add-on owns the popover + menu items.
 * A concrete `ReactElement` (not the broader `ReactNode`): Base UI's `render` prop requires one.
 */
export type HeaderMenuRenderer = (ctx: { column: AnyColumnDef; index: number; trigger: ReactElement }) => ReactNode;

/** Context passed to {@link MarkerCellRenderer} for one row's marker cell. */
export type MarkerCellRenderCtx = {
  /** 0-based view row index (the marker column's own numbering space, minus one). */
  viewRowIndex: number;
  /** The ROWS channel only: this row is selected as a whole (marker press/drag, Shift+Space). Cell or column selection never flips it — mirrors `useDataGridIsRowChannelSelected`. */
  isRowChannelSelected: boolean;
  /** The CELL or COLUMN channel covers at least one cell of this row. Independent of `isRowChannelSelected`, so a renderer can tell "this row is selected" apart from "cells in this row are selected" — mirrors `useDataGridIsRowCellSelected`. */
  isCellSelected: boolean;
};

/** Context passed to {@link MarkerHeaderRenderer} for the marker column's header cell. */
export type MarkerHeaderRenderCtx = {
  /** The select-all state the built-in header checkbox shows. */
  allSelected: "checked" | "indeterminate" | "unchecked";
};

/**
 * Custom row-marker cell renderer: replaces the built-in row number/checkbox CONTENT inside the
 * marker column (requires a non-`'none'` `rowMarkers` mode; the mode still drives the track width,
 * and the cell's own press/drag row-selection gesture stays on the wrapper). Pass a stable identity.
 */
export type MarkerCellRenderer = (ctx: MarkerCellRenderCtx) => ReactNode;

/** Custom marker-header renderer: replaces the built-in select-all checkbox; same track and width. Pass a stable identity. */
export type MarkerHeaderRenderer = (ctx: MarkerHeaderRenderCtx) => ReactNode;

/** Layout context shared by header/body so they don't recompute widths independently and never desync on row height, and so both consume the SAME column window (no drift between two independent subscriptions). */
export type DataGridRootContextValue = {
  scrollRef: RefObject<HTMLDivElement | null>;
  viewportRef: RefObject<HTMLDivElement | null>;
  columns: readonly AnyColumnDef[];
  /** Columns in the current column window, in display order, each tagged with its real index. */
  windowedColumns: readonly WindowedColumn[];
  layout: ColumnLayout;
  rowHeight: number;
  /** The sticky header track's own height — header.tsx's literal row height, NOT including any pinned band. Consumers computing "where data row 0 starts" need `headerHeight + pinnedTopHeight`; body.tsx does this itself for `useRowWindow`/the canvas transform. */
  headerHeight: number;
  /** Pinned-top row band height (px); 0 when `rowBands` is unset or its `topRows` is empty. */
  pinnedTopHeight: number;
  /** Pinned-bottom row band height (px); 0 when `rowBands` is unset or its `bottomRows` is empty. */
  pinnedBottomHeight: number;
  /** `rowBands.topRows.length` — body.tsx's `ariaRowIndexOffset` needs only the count, never the row contents (core doesn't own pinned-row semantics). */
  pinnedTopCount: number;
  /** Full RLE grid-template-columns string — the alignment source of truth for both layers. */
  template: string;
  interaction: GridInteractionHandlers;
  /** Resolved layout direction for this grid — the single value every direction-aware seam inside the root reads (header reorder half-test, resize delta, pin-shadow measurement). */
  direction: GridDirection;
  readOnly?: boolean;
  /** Optional per-column header menu slot (ghost chevron trigger); undefined renders nothing. */
  renderHeaderMenu?: HeaderMenuRenderer;
  /** Optional custom row-marker cell renderer; undefined renders the built-in number/checkbox. */
  renderMarker?: MarkerCellRenderer;
  /** Optional custom marker-header renderer; undefined renders the built-in select-all checkbox. */
  renderMarkerHeader?: MarkerHeaderRenderer;
  /**
   * Programmatic row/cell class hooks, routed through this context rather than a
   * per-row/per-cell prop. `DataGridRoot` DOES re-render on active-cell moves (the activeColumn
   * subscription, root.tsx) as well as scroll/window-shift ticks, but its context value is
   * `useMemo`'d on real deps (root.tsx) — a render that doesn't change any field here (e.g. an
   * active-cell move within the same column window) hands out the identical value reference, so
   * `cell.tsx`'s direct `useDataGridRootContext()` read doesn't re-render either, keeping this off
   * the memoized `DataGridRow`/`DataGridCell` hot path the wasted-render regression test guards.
   */
  getRowClassName?: GetRowClassName<unknown>;
  getCellClassName?: GetCellClassName<unknown>;
  /** Forwarded to each cell's click handler; see {@link DataGridRootProps.onCellClick} in root.tsx. */
  onCellClick?: OnCellClick<unknown>;
  /** Forwarded alongside `onCellClick`; see {@link DataGridRootProps.onRowClick} in root.tsx. */
  onRowClick?: OnRowClick<unknown>;
  /** Fired by `DataGridBody` after a row-window commit; see {@link DataGridRootProps.onRowWindowChange} in root.tsx. */
  onRowWindowChange?: (range: { start: number; end: number }) => void;
};

export const DataGridRootContext = createContext<DataGridRootContextValue | null>(null);

/** Resolves the shared root layout context; throws outside a `<DataGridRoot>`. */
export function useDataGridRootContext(): DataGridRootContextValue {
  const ctx = use(DataGridRootContext);
  if (!ctx) throw new Error("gridcn: DataGridHeader/DataGridBody must be used inside a <DataGridRoot>.");
  return ctx;
}

"use client";

import { Fragment, type CSSProperties, type ReactNode } from "react";
import { cn } from "@/lib/utils";
import { GRID_LAYER } from "./layers";
import type { CellCoord, CompactSelectionLike, GridRect } from "./types";
import { intersectRect } from "./selection";
import { pinnedInsetStyle } from "./columns/pinned-inset-style";
import {
  useDataGridActiveCell,
  useDataGridOverlayPlugins,
  useDataGridSelection,
  type AnyColumnDef,
} from "./store";

/** Per-real-column-index pin/track data an overlay segment needs to reproduce a pinned cell's own offset. */
export type PinTrackData = {
  pins: readonly (AnyColumnDef["pin"] | undefined)[];
  trackLefts: readonly number[];
  trackRights: readonly number[];
  /** Real-index bounds `[start, end)` of the currently rendered UNPINNED column window — pinned zones always render in full (pinned columns are never virtualized out), so only the unpinned middle segment needs this clamp. */
  renderedUnpinnedRange: { start: number; end: number };
};

/**
 * Clamps a data-space rect to the given `[rowStart, rowEnd)` row window and `[0, colCount)`, or
 * null if fully outside it — column clamping to the actually-RENDERED window happens per pin-zone
 * in {@link splitRectByPinZones} when `pinTrack` is supplied. Exported for {@link OverlayPluginCtx}:
 * an overlay plugin (e.g. `data-grid-presence`) needs the same window-clamp math core's own
 * built-in layers use, rather than reimplementing it.
 */
export function clampRectToWindow(
  rect: GridRect,
  rowStart: number,
  rowEnd: number,
  colCount: number,
): GridRect | null {
  return intersectRect(rect, { x: 0, y: rowStart, width: colCount, height: rowEnd - rowStart });
}

/** Contiguous membership runs of `set` within `[start, end)` — O(end - start), window-bounded. */
function membershipRuns(set: CompactSelectionLike, start: number, end: number): Array<{ start: number; length: number }> {
  const runs: Array<{ start: number; length: number }> = [];
  let runStart = -1;
  for (let i = start; i < end; i++) {
    if (set.hasIndex(i)) {
      if (runStart === -1) runStart = i;
    } else if (runStart !== -1) {
      runs.push({ start: runStart, length: i - runStart });
      runStart = -1;
    }
  }
  if (runStart !== -1) runs.push({ start: runStart, length: end - runStart });
  return runs;
}

/** One pin zone's contiguous index range plus (for pinned zones) the offset shared by the whole segment. */
export type RectSegment = {
  rect: GridRect;
  /** Undefined for the unpinned middle segment — no counter-offset, no elevated z-index. */
  pin?: AnyColumnDef["pin"];
  pinStyle?: CSSProperties;
};

/**
  * Splits a data-space rect into up to 3 contiguous sub-rects — pinned-left / unpinned / pinned-right —
  * so each zone can be rendered at its own screen position: overlays live in the rows canvas, which
  * translates by -scrollLeft, so a segment spanning a pinned column would otherwise
 * paint at that column's TRACK position instead of its counter-offset pinned position. Pinned
 * columns are contiguous within their zone (store guarantee, `computeVisibleColumns`), so the
 * whole segment reuses the single offset of its first column.
 */
export function splitRectByPinZones(rect: GridRect, track: PinTrackData): RectSegment[] {
  const { pins, renderedUnpinnedRange } = track;
  let leftEnd = 0;
  while (leftEnd < pins.length && pins[leftEnd] === "left") leftEnd++;
  let rightStart = pins.length;
  while (rightStart > leftEnd && pins[rightStart - 1] === "right") rightStart--;

  const zones: Array<{ start: number; end: number; pin?: AnyColumnDef["pin"] }> = [
    { start: 0, end: leftEnd, pin: "left" },
    // clamped to the rendered unpinned column window: unlike pinned zones (always fully rendered),
    // the unpinned middle is virtualized, so an unclamped segment would place its far edge at an
    // off-screen track position, breaking the "no gaps" visual tiling with the pinned segments.
    { start: Math.max(leftEnd, renderedUnpinnedRange.start), end: Math.min(rightStart, renderedUnpinnedRange.end), pin: undefined },
    { start: rightStart, end: pins.length, pin: "right" },
  ];

  const segments: RectSegment[] = [];
  for (const zone of zones) {
    if (zone.end <= zone.start) continue;
    const clamped = intersectRect(rect, { x: zone.start, y: rect.y, width: zone.end - zone.start, height: rect.height });
    if (!clamped) continue;
    if (!zone.pin) {
      segments.push({ rect: clamped });
      continue;
    }
    const firstCol = clamped.x;
    segments.push({
      rect: clamped,
      pin: zone.pin,
      pinStyle: pinnedInsetStyle(zone.pin, firstCol),
    });
  }
  return segments;
}

/** One selection-range fill overlay, grid-line placed, window-relative; pinned segments add their zone's counter-offset + elevated z-index (above pinned cells). */
function RangeOverlay({ rect, windowStart, colOffset, pinStyle }: { rect: GridRect; windowStart: number; colOffset: number; pinStyle?: CSSProperties }) {
  return (
    <div
      data-grid-selection-overlay=""
      data-pinned={pinStyle ? "" : undefined}
      aria-hidden="true"
      className="pointer-events-none border border-primary/40 bg-primary/10"
      style={{
        // positioned: cells are position:relative, so a static overlay would paint below them
        position: "relative",
        gridColumnStart: rect.x + colOffset,
        gridColumnEnd: rect.x + rect.width + colOffset,
        gridRowStart: rect.y - windowStart + 1,
        gridRowEnd: rect.y + rect.height - windowStart + 1,
        ...pinStyle,
        ...(pinStyle ? { zIndex: GRID_LAYER.pinnedOverlaySegment } : {}),
      }}
    />
  );
}

/** Props for {@link DataGridOverlays}. */
export type DataGridOverlaysProps = {
  /** First rendered (data-space) row index — overlays place window-relative like the rows canvas. May sit below `clampRowStart` when an off-window active row pulls it down (see body.tsx effectiveStart). */
  windowStart: number;
  /** Number of rows currently in view (post sort/filter). May include a disjoint off-window active row appended past the contiguous span — NOT a safe range-overlay clamp bound on its own, see `clampRowStart`/`clampRowEnd`. */
  rowCount: number;
  /**
   * True contiguous `[start, end)` rendered row span for clamping range/band overlays — distinct
   * from `windowStart`/`rowCount` because body.tsx appends a single off-window active row outside
   * the contiguous window, which would otherwise make `[windowStart, windowStart+rowCount)` either
   * overshoot or undershoot the real rendered bottom. Defaults to `[windowStart, windowStart+rowCount)`
   * when omitted (no disjoint window in play).
   */
  clampRowStart?: number;
  clampRowEnd?: number;
  /** Total number of visible columns (real index space) — NOT the rendered column-window size, so pin-zone segmentation can reach a pinned-right zone far outside the current window. */
  colCount: number;
  /** 1-based grid-column offset added to every data-space rect.x; 2 when a marker column occupies track 1, else 1 (default). */
  colOffset?: number;
  /** Per-column pin + track data (real column-index space) for pin-aware overlay segmentation; omitted (e.g. no pinned columns) skips segmentation entirely. */
  pinTrack?: PinTrackData;
};

/**
 * Context passed to every registered {@link OverlayPlugin}: the window-clamp + pin-zone
 * segmentation helpers and layout vars a plugin needs to reproduce the built-in layers'
 * "clamp to rendered window, split by pin zone, place by grid line" pipeline.
 */
export type OverlayPluginCtx = {
  windowStart: number;
  clampRowStart: number;
  clampRowEnd: number;
  colCount: number;
  colOffset: number;
  pinTrack?: PinTrackData;
  splitRectByPinZones: typeof splitRectByPinZones;
  clampRectToWindow: typeof clampRectToWindow;
};

/**
 * One overlay-plugin slot: registered via `overlayPlugins` on `DataGridProvider`, rendered by
 * {@link DataGridOverlays} after the range/band layers but BEFORE the local active-cell ring —
 * plugin content (e.g. a fill drag preview, multiplayer presence) loses visually to local focus.
 * The only new core surface for add-ons that paint into the overlay layer: core supplies
 * geometry, the plugin supplies content.
 */
export type OverlayPlugin = (ctx: OverlayPluginCtx) => ReactNode;

/** True when any column is pinned — segmentation is a no-op (and skippable) otherwise. */
function hasAnyPin(pinTrack: PinTrackData | undefined): pinTrack is PinTrackData {
  return Boolean(pinTrack && pinTrack.pins.some((p) => p === "left" || p === "right"));
}

/**
 * Selection-range fill + active-cell ring, rendered inside the rows canvas so they translate with
 * scroll content. Placed purely by grid lines (no pixel math), `pointer-events: none` throughout.
 * Subscribes to selection/active-cell via atomic selectors: a change re-renders only this
 * component (never rows). When any column is pinned, every rect splits into pinned-left/unpinned/
 * pinned-right segments so pinned segments paint at their cell's actual screen position, above
 * pinned cells' own z-index. Registered `overlayPlugins` render after the built-in layers but
 * BEFORE the active-cell ring, so local focus always wins visually over plugin content.
 */
export function DataGridOverlays(props: DataGridOverlaysProps): ReactNode {
  const { windowStart, rowCount, clampRowStart = windowStart, clampRowEnd = windowStart + rowCount, colCount, colOffset = 1, pinTrack } = props;
  const selection = useDataGridSelection();
  const activeCell = useDataGridActiveCell();
  const overlayPlugins = useDataGridOverlayPlugins();
  const pinned = hasAnyPin(pinTrack) ? pinTrack : undefined;

  /** Splits into pin-zone segments when the grid has pinned columns, else the rect as a single "segment". */
  const segment = (rect: GridRect): RectSegment[] => (pinned ? splitRectByPinZones(rect, pinned) : [{ rect }]);

  const rangeRects: GridRect[] = [];
  if (selection.current) {
    rangeRects.push(selection.current.range);
    for (const rect of selection.current.rangeStack) rangeRects.push(rect);
  }

  // rows/columns channels (header/marker selection) render as full-band highlights — Excel-style
  // visible feedback (user QA 2026-07-03); runs computed only inside the contiguous rendered span
  // (clampRowStart/End, not windowStart/rowCount) so a disjoint off-window active row can't stretch
  // or shift these bands past the real rendered bottom.
  const columnBands: GridRect[] = membershipRuns(selection.columns, 0, colCount).map((run) => ({
    x: run.start,
    y: clampRowStart,
    width: run.length,
    height: clampRowEnd - clampRowStart,
  }));
  const rowBands: GridRect[] = membershipRuns(selection.rows, clampRowStart, clampRowEnd).map((run) => ({
    x: 0,
    y: run.start,
    width: colCount,
    height: run.length,
  }));

  const activeInWindow: CellCoord | null =
    activeCell && activeCell.row >= windowStart && activeCell.row < windowStart + rowCount ? activeCell : null;
  const activePinStyle = activeInWindow && pinned ? pinned.pins[activeInWindow.col] && pinnedInsetStyle(
    pinned.pins[activeInWindow.col],
    activeInWindow.col,
  ) : undefined;

  return (
    <>
      {rangeRects.map((rect, i) => {
        const clamped = clampRectToWindow(rect, clampRowStart, clampRowEnd, colCount);
        if (!clamped) return null;
        return segment(clamped).map((seg, j) => (
          <RangeOverlay key={`${i}-${j}`} rect={seg.rect} windowStart={windowStart} colOffset={colOffset} pinStyle={seg.pinStyle} />
        ));
      })}
      {columnBands.map((rect, i) =>
        segment(rect).map((seg, j) => (
          <RangeOverlay key={`col-band-${i}-${j}`} rect={seg.rect} windowStart={windowStart} colOffset={colOffset} pinStyle={seg.pinStyle} />
        )),
      )}
      {rowBands.map((rect, i) =>
        segment(rect).map((seg, j) => (
          <RangeOverlay key={`row-band-${i}-${j}`} rect={seg.rect} windowStart={windowStart} colOffset={colOffset} pinStyle={seg.pinStyle} />
        )),
      )}
      {overlayPlugins.length > 0 &&
        overlayPlugins.map((plugin, i) => (
          // rendered here (after range/band layers, BEFORE the active-cell ring) so a plugin like
          // data-grid-fill's fill-preview/handle or presence keeps painting below local focus —
          // the ring must always win visually.
          <Fragment key={i}>
            {plugin({ windowStart, clampRowStart, clampRowEnd, colCount, colOffset, pinTrack, splitRectByPinZones, clampRectToWindow })}
          </Fragment>
        ))}
      {activeInWindow && (
        <div
          data-grid-active-cell-overlay=""
          data-pinned={activePinStyle ? "" : undefined}
          aria-hidden="true"
          className={cn("pointer-events-none z-10 ring-2 ring-inset ring-primary")}
          style={{
            gridColumnStart: activeInWindow.col + colOffset,
            gridColumnEnd: activeInWindow.col + colOffset + 1,
            gridRowStart: activeInWindow.row - windowStart + 1,
            gridRowEnd: activeInWindow.row - windowStart + 2,
            ...activePinStyle,
          }}
        />
      )}
    </>
  );
}

