 * side is empty — {@link buildViewIndex}'s own rule, replicated here rather than shared, because the
 * rebuild stays the untouched reference implementation. `custom` is the column's resolved
 * `accessor.compare` when it has one; otherwise the text keys drive `defaultCompareText`.
 */
function compareOnColumn(
  accessor: CellAccessor,
  columnId: string,
  dir: 1 | -1,
  custom: ((a: number, b: number) => number) | undefined,
  a: number,
  b: number,
): number {
  if (custom) {
    const emptyA = isEmptyCell(accessor, a, columnId);
    const emptyB = isEmptyCell(accessor, b, columnId);
    if (emptyA && emptyB) return 0;
    if (emptyA) return 1;
    if (emptyB) return -1;
    return dir * custom(a, b);
  }
  const textA = accessor.getText(a, columnId);
  const textB = accessor.getText(b, columnId);
  if (textA === "" || textB === "") return defaultCompareText(textA, textB);
  return dir * defaultCompareText(textA, textB);
}

/**
 * The comparator chain {@link buildViewIndex} sorts by, expressed over data indices.
 *
 * Tiebreak equivalence: the rebuild decorates each row with its POSITION in the filtered index array
 * and breaks ties on that position. `indices` starts as `[0..n)` and every filter pass preserves
 * relative order, so position is strictly increasing in data index — `positionA - positionB` and
 * `a - b` always agree in sign. Comparing data indices directly is therefore the identical tiebreak,
 * and it makes the order TOTAL (no two rows ever compare equal), which is what lets a binary search
 * find one uniquely-correct insertion point.
 */
export function makeViewComparator(accessor: CellAccessor, sorts: readonly SortSpec[]): (a: number, b: number) => number {
  // Resolved ONCE per column here, not per comparison — mirrors the rebuild's per-sort resolution.
  const columns = sorts.map((sort) => ({
    columnId: sort.columnId,
    dir: (sort.direction === "asc" ? 1 : -1) as 1 | -1,
    custom: accessor.compare?.(sort.columnId),
  }));
  return (a, b) => {
    for (const { columnId, dir, custom } of columns) {
      const result = compareOnColumn(accessor, columnId, dir, custom, a, b);
      if (result !== 0) return result;
    }
    return a - b;
  };
}

/** Whether `row` survives the active filters — the same matchers, join semantics, and text source the rebuild uses. */
export function makeFilterPredicate(
  accessor: CellAccessor,
  filters: readonly FilterSpec[],
  joinOperator: FilterJoinOperator | undefined,
): (row: number) => boolean {
  if (filters.length === 0) return () => true;
  const matchers = filters.map((filter) => ({ columnId: filter.columnId, test: createFilterMatcher(filter) }));
  if (joinOperator === "or") return (row) => matchers.some((m) => m.test(accessor.getText(row, m.columnId)));
  return (row) => matchers.every((m) => m.test(accessor.getText(row, m.columnId)));
}

/** Index in `view` where `row` belongs under `compare`; `view` must already be sorted by it. */
export function lowerBound(view: readonly number[], row: number, compare: (a: number, b: number) => number): number {
  let lo = 0;
  let hi = view.length;
  while (lo < hi) {
    const mid = (lo + hi) >>> 1;
    if (compare(view[mid]!, row) < 0) lo = mid + 1;
    else hi = mid;
  }
  return lo;
}

/**
 * Rebuilds `prevViewIndex` for a value patch that touched `touchedRows` (data indices), instead of
 * re-sorting all `n` rows. Per touched row: remove it from the order, re-test filter membership
 * against the NEW values, and binary-search it back in under the identical comparator chain — so a
 * value change may also add a row to, or drop it from, the filtered set.
 *
 * `touchedRows` must name EVERY row whose values changed since `prevViewIndex` was built (a caller
 * holding deferred batches has to pass their rows too) — every other row's key is assumed unchanged,
 * which is what makes the remaining order a valid binary-search invariant.
 *
 * Returns `{viewIndex: null, bail}` whenever the incremental path cannot prove it reproduces
 * {@link buildViewIndex} exactly; the caller must then run the full rebuild. Correctness beats
 * cleverness: every valve below is a case where equivalence is not provable, not a case where it is
 * merely slower.
 *
 * A column with an `accessor.compare` needs NO valve: both paths now resolve the same comparator
 * under the same empty-last rule, and the accessor contract makes it a deterministic function of the
 * two rows' values — so an untouched row's key is unchanged and the remaining order stays a valid
 * binary-search invariant, exactly as for the default text comparator.
 */
export function updateViewIndex(
  prevViewIndex: readonly number[],
  touchedRows: readonly number[],
  accessor: CellAccessor,
  opts: ViewIndexOptions,
): IncrementalViewIndexResult {
  if (touchedRows.length > INCREMENTAL_PATCH_LIMIT) return { viewIndex: null, bail: "too-many-rows" };
  // buildViewIndex narrows by `search` before sorting; this path only knows sort + filter membership.
  if (opts.search?.trim() && opts.searchColumnIds) return { viewIndex: null, bail: "search-active" };
  const touched = new Set(touchedRows);
  const survives = makeFilterPredicate(accessor, opts.filters, opts.joinOperator);
  // With no sort columns the comparator degenerates to the data-index tiebreak alone, which is
  // exactly the order the rebuild leaves an unsorted filtered view in.
  const compare = makeViewComparator(accessor, opts.sorts);

  // `indexOf` and `splice` are native memmoves over the index array, so 2k of them stay far cheaper
  // than any JS-level pass over all n. Measured at 100k rows / one sort column: this path costs
  // 0.47 / 0.91 / 1.57 ms at k = 5 / 20 / 50, against a uniform 3.7-4.1 ms for a single
  // filter-and-merge pass — the JS-loop alternative loses at every k, so there is only one path.
  const next = prevViewIndex.slice();
  for (const row of touched) {
    const position = next.indexOf(row);
    if (position !== -1) next.splice(position, 1);
  }
  for (const row of touched) {
    if (!survives(row)) continue;
    next.splice(lowerBound(next, row, compare), 0, row);
  }
  return { viewIndex: next, bail: null };
}

/** Module-default collator, used when a call site doesn't supply its own (e.g. to amortize one instance across a whole sort). */
const defaultCollator = new Intl.Collator(undefined, { numeric: true, sensitivity: "base" });

/**
 * Default text comparator: numeric-aware localeCompare, case-insensitive.
 * Empty strings always sort last, regardless of direction (callers must not
 * negate this result wholesale — see the empty-aware wrapper in buildViewIndex).
 * `collator` lets a hot loop (buildViewIndex) reuse one Intl.Collator instead of
 * this function constructing a fresh one per call.
 */
export function defaultCompareText(a: string, b: string, collator: Intl.Collator = defaultCollator): number {
  const aEmpty = a === "";
  const bEmpty = b === "";
  if (aEmpty && bEmpty) return 0;
  if (aEmpty) return 1;
  if (bEmpty) return -1;
  return collator.compare(a, b);
}

import type { CellAccessor } from "./build-view-index";

/** One search hit, in row-major order, for highlight and next/prev navigation. */
export type SearchMatch = { row: number; columnId: string };

/**
 * Finds every cell matching `search` (case-insensitive substring) across
 * `columnIds`, in row-major order — the order next/prev navigation and
 * highlight rendering expect. `maxMatches`, when given, early-exits the scan
 * the moment that many hits are collected (bounds worst-case work
 * at 100k+ rows for a common search term; omitted keeps the full scan).
 */
export function findSearchMatches(
  rowCount: number,
  accessor: CellAccessor,
  search: string,
  columnIds: string[],
  maxMatches?: number,
): SearchMatch[] {
  const needle = search.trim().toLowerCase();
  if (needle === "") return [];

  const matches: SearchMatch[] = [];
  for (let row = 0; row < rowCount; row++) {
    for (const columnId of columnIds) {
      if (accessor.getText(row, columnId).toLowerCase().includes(needle)) {
        matches.push({ row, columnId });
        if (maxMatches !== undefined && matches.length >= maxMatches) return matches;
      }
    }
  }
  return matches;
}

/** Domain barrel — sort/filter/search: compare fns, filter matching, view-index, search matches. */
export { defaultCompareText } from "./default-compare-text";
export { matchesFilter, createFilterMatcher } from "./matches-filter";
export { buildViewIndex, isEmptyCell, type CellAccessor, type ViewIndexOptions } from "./build-view-index";
export { findSearchMatches, type SearchMatch } from "./find-search-matches";
export {
  updateViewIndex,
  makeViewComparator,
  makeFilterPredicate,
  lowerBound,
  INCREMENTAL_PATCH_LIMIT,
  type IncrementalBailReason,
  type IncrementalViewIndexResult,
} from "./incremental-view-index";

import type { FilterOperator, FilterSpec } from "../types";
import { defaultCompareText } from "./default-compare-text";

function parseNumber(text: string): number | null {
  if (text.trim() === "") return null;
  const n = Number(text);
  return Number.isNaN(n) ? null : n;
}

/** Compares `text` against `bound` numerically when both parse as numbers, else via `defaultCompareText`. */
function compareTextTo(text: string, bound: string): number {
  const a = parseNumber(text);
  const b = parseNumber(bound);
  if (a !== null && b !== null) return a - b;
  return defaultCompareText(text, bound);
}

/**
 * Evaluates a single {@link FilterSpec} against a cell's text value.
 * `gt`/`gte`/`lt`/`lte` compare numerically when both sides parse as
 * numbers, else fall back to `defaultCompareText`; blank cell text never
 * satisfies these comparisons. `empty`/`notEmpty` ignore `filter.value`.
 * `isBetween` is inclusive on both ends; an empty bound (`""`) leaves that
 * side open (e.g. `["", "10"]` means "<= 10"). `isAnyOf` matches when the cell
 * text equals any entry of its `string[]`, compared case-insensitively like `equals`.
 *
 * This is the correctness reference (re-parses `filter.value` on every call) — {@link createFilterMatcher}
 * is the same semantics with the bound(s) parsed once, for a hot per-row loop over many rows.
 */
export function matchesFilter(text: string, filter: FilterSpec): boolean {
  const op: FilterOperator = filter.operator;
  if (op === "empty") return text === "";
  if (op === "notEmpty") return text !== "";

  if (op === "isAnyOf") {
    // an empty choice list matches nothing, so a half-built filter row hides every row rather than being a no-op
    const choices = Array.isArray(filter.value) ? filter.value : [];
    const textLower = text.toLowerCase();
    return choices.some((choice) => choice.toLowerCase() === textLower);
  }

  if (op === "isBetween") {
    // Excel/AG Grid semantics: blank cells never satisfy a comparison filter.
    if (text === "") return false;
    const [min = "", max = ""] = Array.isArray(filter.value) ? filter.value : ["", ""];
    if (min !== "" && compareTextTo(text, min) < 0) return false;
    if (max !== "" && compareTextTo(text, max) > 0) return false;
    return true;
  }

  const value = typeof filter.value === "string" ? filter.value : "";
  const textLower = text.toLowerCase();
  const valueLower = value.toLowerCase();

  switch (op) {
    case "contains":
      return textLower.includes(valueLower);
    case "notContains":
      return !textLower.includes(valueLower);
    case "equals":
      return textLower === valueLower;
    case "notEquals":
      return textLower !== valueLower;
    case "startsWith":
      return textLower.startsWith(valueLower);
    case "endsWith":
      return textLower.endsWith(valueLower);
    case "gt":
    case "gte":
    case "lt":
    case "lte": {
      // Excel/AG Grid semantics: blank cells never satisfy a comparison filter.
      if (text === "") return false;
      const cmp = compareTextTo(text, value);
      if (op === "gt") return cmp > 0;
      if (op === "gte") return cmp >= 0;
      if (op === "lt") return cmp < 0;
      return cmp <= 0;
    }
    default: {
      const exhaustive: never = op;
      return exhaustive;
    }
  }
}

/** A bound pre-parsed once (outside the per-row loop) plus its original text for the string fallback path. */
type ParsedBound = { raw: string; num: number | null };

function parseBound(raw: string): ParsedBound {
  return { raw, num: parseNumber(raw) };
}

/** Compares `text` against a {@link ParsedBound}: numeric if `text` also parses, else falls back to `defaultCompareText`. */
function compareTextToParsedBound(text: string, bound: ParsedBound): number {
  if (bound.num !== null) {
    const a = parseNumber(text);
    if (a !== null) return a - bound.num;
  }
  return defaultCompareText(text, bound.raw);
}

/**
 * Builds a per-row matcher for `filter` with any numeric bound(s) in `filter.value` parsed exactly
 * once, instead of on every {@link matchesFilter} call — `gt`/`gte`/`lt`/`lte`/`isBetween` bounds are
 * the same string across every row of a `buildViewIndex` pass, so re-parsing them per row (as a
 * direct `matchesFilter` call in a `.filter()` predicate does) is O(n) redundant work. Same
 * semantics as `matchesFilter`, verified by build-view-index's own tests; kept in sync manually
 * since duplicating a switch this small behind a shared abstraction would obscure both.
 */
export function createFilterMatcher(filter: FilterSpec): (text: string) => boolean {
  const op: FilterOperator = filter.operator;
  if (op === "empty") return (text) => text === "";
  if (op === "notEmpty") return (text) => text !== "";

  if (op === "isAnyOf") {
    const choices = (Array.isArray(filter.value) ? filter.value : []).map((choice) => choice.toLowerCase());
    const set = new Set(choices);
    return (text) => set.has(text.toLowerCase());
  }

  if (op === "isBetween") {
    const [minRaw = "", maxRaw = ""] = Array.isArray(filter.value) ? filter.value : ["", ""];
    const min = minRaw !== "" ? parseBound(minRaw) : null;
    const max = maxRaw !== "" ? parseBound(maxRaw) : null;
    return (text) => {
      if (text === "") return false;
      if (min && compareTextToParsedBound(text, min) < 0) return false;
      if (max && compareTextToParsedBound(text, max) > 0) return false;
      return true;
    };
  }

  const value = typeof filter.value === "string" ? filter.value : "";

  switch (op) {
    case "contains": {
      const needle = value.toLowerCase();
      return (text) => text.toLowerCase().includes(needle);
    }
    case "notContains": {
      const needle = value.toLowerCase();
      return (text) => !text.toLowerCase().includes(needle);
    }
    case "equals": {
      const needle = value.toLowerCase();
      return (text) => text.toLowerCase() === needle;
    }
    case "notEquals": {
      const needle = value.toLowerCase();
      return (text) => text.toLowerCase() !== needle;
    }
    case "startsWith": {
      const needle = value.toLowerCase();
      return (text) => text.toLowerCase().startsWith(needle);
    }
    case "endsWith": {
      const needle = value.toLowerCase();
      return (text) => text.toLowerCase().endsWith(needle);
    }
    case "gt":
    case "gte":
    case "lt":
    case "lte": {
      const bound = parseBound(value);
      return (text) => {
        if (text === "") return false;
        const cmp = compareTextToParsedBound(text, bound);
        if (op === "gt") return cmp > 0;
        if (op === "gte") return cmp >= 0;
        if (op === "lt") return cmp < 0;
        return cmp <= 0;
      };
    }
    default: {
      const exhaustive: never = op;
      return exhaustive;
    }
  }
}

import type { CellCoord, CellType, DataChange, DataOp } from "../types";
import type { OverlayPlugin } from "../overlays";
import type { RowBandsSpec } from "../layout-context";
import { getCellValue, setCellValue } from "../columns/column-helpers";
import { isDev } from "../is-dev";
import { isStandardSchema, runValidateSync, type ValidateResult } from "../validation/validate-cell";
import { runValidateBatch, type ValidateBatchItem } from "../validation/validate-batch";
import { isColumnReadOnly } from "./compute";
import { cellTypes as defaultCellTypes } from "../cell-types/cell-types";
import type { AnyColumnDef, CellPatch, CommitResult, DataGridStoreState, InternalSyncProps, RowEdit } from "./types";

export function warnDev(message: string): void {
  if (isDev()) console.warn(`[data-grid] ${message}`);
}

/**
 * Warns once per instance (per passed Set) for every column whose `type` resolves to nothing in
 * the effective cellTypes registry (the passed registry, or the built-ins when none was passed) —
 * a typo silently degrades the column to text rendering, and its edit/paste/delete paths go dead
 * (see `resolveEditTarget`). The single warn site for the cellTypes replace-semantics footgun
 * (a custom registry omitting a used type); do not add a second one.
 */
export function checkUnresolvableColumnTypes(
  columns: readonly AnyColumnDef[],
  cellTypes: Readonly<Record<string, unknown>> | undefined,
  warned: Set<string>,
): void {
  if (!isDev()) return;
  const registry: Record<string, unknown> = cellTypes ?? defaultCellTypes;
  for (const column of columns) {
    if (column.type === undefined || registry[column.type] !== undefined) continue;
    const key = `${column.id}:${column.type}`;
    if (warned.has(key)) continue;
    warned.add(key);
    warnDev(`column "${column.id}" has type "${column.type}" which resolves to nothing in the cellTypes registry (typo or a custom registry without it); it renders as text and its edits, pastes, and deletes are dropped`);
  }
}

/** Fires `warnDev` at most once per session — for guardrails whose cause (a mistaken prop combo) doesn't change across re-renders, so repeating it every render would just be noise. */
let warnedBothDataProps = false;

/** `data` + `defaultData` are mutually exclusive (React value/defaultValue semantics); `data` wins. */
export function warnBothDataPropsOnce(): void {
  if (warnedBothDataProps || !isDev()) return;
  warnedBothDataProps = true;
  warnDev("both `data` and `defaultData` were provided; `data` wins (controlled) and `defaultData` is ignored");
}

/** Dev-only guardrails: duplicate column ids, missing getRowId, unstable columns/data/overlayPlugins/rowBands identity across renders. */
export function checkDevGuardrails(
  props: InternalSyncProps,
  prevColumns: readonly AnyColumnDef[] | undefined,
  prevData: readonly unknown[] | undefined,
  prevOverlayPlugins: readonly OverlayPlugin[] | undefined,
  prevRowBands: RowBandsSpec | undefined,
): void {
  if (!isDev()) return;

  const seen = new Set<string>();
  for (const column of props.columns) {
    if (seen.has(column.id)) warnDev(`duplicate column id "${column.id}"`);
    seen.add(column.id);
  }

  if (typeof props.getRowId !== "function") {
    warnDev("getRowId is required and must be a function");
  }

  if (props.data !== undefined && props.defaultData !== undefined) {
    warnBothDataPropsOnce();
  }

  if (prevColumns !== undefined && prevColumns !== props.columns) {
    warnDev(
      "columns array identity changed since the last render; pass a stable reference (e.g. useMemo) or every row re-renders",
    );
  }
  if (prevOverlayPlugins !== undefined && prevOverlayPlugins !== props.overlayPlugins) {
    warnDev(
      "overlayPlugins array identity changed since the last render; pass a stable reference (module scope or useMemo) or DataGridOverlays re-renders every tick",
    );
  }
  if (prevRowBands !== undefined && prevRowBands !== props.rowBands) {
    warnDev(
      "rowBands identity changed since the last render; pass a stable reference (the add-on's hook already returns one) or every render recomputes band heights/aria-rowcount",
    );
  }
  // Controlled mode only: in uncontrolled mode props.data is undefined (data lives in the store),
  // and the store's own array legitimately gets a new reference on every mutation — not a bug.
  if (props.data !== undefined && prevData !== undefined && prevData !== props.data && prevData.length === props.data.length) {
    // Only identity churn with zero row changes is the anti-pattern (array rebuilt per render);
    // a legitimate immutable edit swaps ≥1 row reference — the early exit keeps this cheap for it.
    const data = props.data;
    let anyRowChanged = false;
    for (let i = 0; i < prevData.length; i++) {
      if (prevData[i] !== data[i]) {
        anyRowChanged = true;
        break;
      }
    }
    if (!anyRowChanged) {
      warnDev("data array identity changed with no row changes; pass a stable reference (rebuilding it every render defeats row memoization)");
    }
  }
}

/**
 * Shared value-write path for both `commitCellEdit` (editing session) and `commitCellValue` (direct
 * write, e.g. checkbox toggle). `value` may already be schema-validated+transformed (the async
 * editor-commit layer passes `result.value`, having awaited the schema itself) — this still
 * re-runs `validate` (cheap, idempotent for a well-behaved schema) so the sync/function-form path
 * is unchanged and a direct `commitCellValue` call always gets checked.
 */
export function computeCommit(s: DataGridStoreState, coord: CellCoord, value: unknown): CommitResult {
  const target = resolveEditTarget(s, coord);
  if (!target) return { noop: true };
  const { column, dataRowIndex, row } = target;
  const validated = runValidateSync(column.validate, value, row);
  if ("error" in validated) return { error: validated.error };
  const nextValue = validated.value;
  const prevValue = getCellValue(row, column);
  if (Object.is(prevValue, nextValue)) return { noop: true };

  const nextRow = setCellValue(row, column, nextValue);
  const nextData = s.data.slice();
  nextData[dataRowIndex] = nextRow;
  const rowId = s.getRowId(nextRow, dataRowIndex);
  const change: DataChange<unknown> = {
    source: "edit",
    ops: [
      {
        type: "update",
        rowId,
        row: nextRow,
        prev: row,
        cells: [{ columnId: column.id, value: nextValue, prev: prevValue }],
      },
    ],
  };
  return { data: nextData, change };
}

/** Looks up the column, data row, and cell type at a view coord; null when any part is unresolvable. */
export function resolveEditTarget(
  s: DataGridStoreState,
  coord: CellCoord,
