        s.onColumnLayoutChange?.(computeColumnLayout(nextColumns, s.columnOrder, s.columnWidths, s.hiddenColumns));
      },
      setColumnHidden(id, hidden) {
        const s = get();
        const current = new Set(s.hiddenColumns);
        if (hidden) current.add(id);
        else current.delete(id);
        const nextHidden = Array.from(current);
        const nextVisibleColumns = computeVisibleColumns(s.columns, s.columnOrder, nextHidden);
        const viewIndex = computeViewIndex(s.data, s.columns, s.sortState, s.filterState, s.joinOperator, s.viewIndex, s.cellTypes);
        resetDeferredRows();
        set({
          hiddenColumns: nextHidden,
          visibleColumns: nextVisibleColumns,
          viewIndex,
          viewStale: false,
          ...computeSearchMatches(s.data, s.columns, viewIndex, nextVisibleColumns, s.searchText),
        });
        s.onColumnLayoutChange?.(computeColumnLayout(s.columns, s.columnOrder, s.columnWidths, nextHidden));
      },
      toggleSort(columnId, additive) {
        const s = get();
        const existing = s.sortState.find((sort) => sort.columnId === columnId);
        const direction = nextDirection(existing?.direction);
        const sorts = additive
          ? toggleSortAdditive(s.sortState, columnId, direction)
          : direction === null
            ? []
            : [{ columnId, direction }];
        s.onSortChange?.(sorts);
        // controlled: `sortState` prop is the source of truth — _syncProps writes it once the
        // consumer's prop actually changes; a callback-ignoring consumer's grid stays fixed.
        if (s.sortControlled) return;
        set((s2) => {
          const viewIndex = computeViewIndex(s2.data, s2.columns, sorts, s2.filterState, s2.joinOperator, s2.viewIndex, s2.cellTypes);
          resetDeferredRows();
          return {
            sortState: sorts,
            viewIndex,
            viewStale: false,
            ...computeSearchMatches(s2.data, s2.columns, viewIndex, s2.visibleColumns, s2.searchText),
          };
        });
      },
      setSorts(sorts) {
        const s = get();
        s.onSortChange?.(sorts);
        if (s.sortControlled) return;
        set((s2) => {
          const viewIndex = computeViewIndex(s2.data, s2.columns, sorts, s2.filterState, s2.joinOperator, s2.viewIndex, s2.cellTypes);
          resetDeferredRows();
          return {
            sortState: sorts,
            viewIndex,
            viewStale: false,
            ...computeSearchMatches(s2.data, s2.columns, viewIndex, s2.visibleColumns, s2.searchText),
          };
        });
      },
      setFilters(filters) {
        const s = get();
        // backfills a filterId for any row the caller added without one (e.g. hand-built controlled updates).
        const withIds = withFilterIds(filters);
        s.onFilterChange?.(withIds);
        if (s.filterControlled) return;
        set((s2) => {
          const viewIndex = computeViewIndex(s2.data, s2.columns, s2.sortState, withIds, s2.joinOperator, s2.viewIndex, s2.cellTypes);
          resetDeferredRows();
          return {
            filterState: withIds,
            viewIndex,
            viewStale: false,
            ...computeSearchMatches(s2.data, s2.columns, viewIndex, s2.visibleColumns, s2.searchText),
          };
        });
      },
      setJoinOperator(joinOperator) {
        const s = get();
        s.onJoinOperatorChange?.(joinOperator);
        if (s.joinOperatorControlled) return;
        set((s2) => {
          const viewIndex = computeViewIndex(s2.data, s2.columns, s2.sortState, s2.filterState, joinOperator, s2.viewIndex, s2.cellTypes);
          resetDeferredRows();
          return {
            joinOperator,
            viewIndex,
            viewStale: false,
            ...computeSearchMatches(s2.data, s2.columns, viewIndex, s2.visibleColumns, s2.searchText),
          };
        });
      },
      setSearch(text) {
        const s = get();
        s.onSearchTextChange?.(text);
        if (s.searchControlled) return;
        // viewIndex is untouched: quick-search highlights + navigates, it never filters.
        set((s2) => ({ searchText: text, ...computeSearchMatches(s2.data, s2.columns, s2.viewIndex, s2.visibleColumns, text) }));
      },
      startEditing(coord, initialText) {
        const s = get();
        const target = resolveEditTarget(s, coord);
        if (!target || isColumnReadOnly(target.column, target.row)) return;
        set({ editing: { coord, initialText }, editingError: null, editingRejectionCount: 0, activeCell: coord });
      },
      cancelEditing() {
        set({ editing: null, editingError: null });
      },
      commitCellEdit(value, movement) {
        const s = get();
        const editing = s.editing;
        if (!editing) return;
        const maxRow = Math.max(0, s.viewIndex.length - 1);
        const maxCol = Math.max(0, s.visibleColumns.length - 1);
        const nextActiveCell = movement
          ? {
              col: clampIndex(editing.coord.col + movement.dx, maxCol),
              row: clampIndex(editing.coord.row + movement.dy, maxRow),
            }
          : editing.coord;

        const result = computeCommit(s, editing.coord, value);
        if ("error" in result) {
          set({ editingError: result.error, editingRejectionCount: s.editingRejectionCount + 1 });
          return;
        }
        if ("noop" in result) {
          set({
            editing: null,
            editingError: null,
            activeCell: nextActiveCell,
            selection: selectCellPure(nextActiveCell),
          });
          return;
        }
        rowIndexCache.rebase(result.data);
        forgetDeferredRows();
        lastEmittedData = result.data;
        s.onDataChange?.(result.data, result.change);
        set({
          data: result.data,
          editing: null,
          editingError: null,
          cellErrors: applyRowValidation(s, clearErrorsForOps(s.cellErrors, result.change.ops), result.data, result.change.ops),
          activeCell: nextActiveCell,
          selection: selectCellPure(nextActiveCell),
          ...reconcileAfterWrite(s, result.data, result.change.ops),
        });
      },
      commitCellValue(coord, value) {
        const s = get();
        const result = computeCommit(s, coord, value);
        if ("error" in result || "noop" in result) return;
        rowIndexCache.rebase(result.data);
        forgetDeferredRows();
        lastEmittedData = result.data;
        s.onDataChange?.(result.data, result.change);
        set({
          data: result.data,
          cellErrors: applyRowValidation(s, clearErrorsForOps(s.cellErrors, result.change.ops), result.data, result.change.ops),
          ...reconcileAfterWrite(s, result.data, result.change.ops),
        });
      },
      setEditingError(message) {
        const s = get();
        if (!s.editing) return;
        set({ editingError: message, editingRejectionCount: s.editingRejectionCount + 1 });
      },
      setCellErrors(errors) {
        if (errors.length === 0) return;
        const s = get();
        const next = new Map(s.cellErrors);
        for (const entry of errors) next.set(cellErrorKey(entry.rowId, entry.columnId), entry.message);
        set({ cellErrors: next });
      },
      clearCellErrors(targets) {
        const s = get();
        if (s.cellErrors.size === 0) return;
        if (!targets) {
          set({ cellErrors: EMPTY_CELL_ERRORS });
          return;
        }
        if (targets.length === 0) return;
        const next = new Map(s.cellErrors);
        let changed = false;
        for (const target of targets) {
          if (next.delete(cellErrorKey(target.rowId, target.columnId))) changed = true;
        }
        if (changed) set({ cellErrors: next });
      },
      deleteSelection() {
        const s = get();
        if (s.readOnly) return;
        const rects = selectionRects(s.selection, s.viewIndex.length, s.visibleColumns.length);
        if (rects.length === 0) return;

        const resolvedCols = s.visibleColumns.map((column) => {
          const cellType = s.cellTypes[column.type ?? "text"];
          return cellType ? { columnId: column.id, value: cellType.clearValue(column.options) } : null;
        });
        const writes: { viewRow: number; columnId: string; value: unknown }[] = [];
        for (const rect of rects) {
          for (let viewRow = rect.y; viewRow < rect.y + rect.height; viewRow++) {
            for (let col = rect.x; col < rect.x + rect.width; col++) {
              const resolved = resolvedCols[col];
              if (!resolved) continue;
              writes.push({ viewRow, columnId: resolved.columnId, value: resolved.value });
            }
          }
        }

        const batch = computeRowEditsBatch(s, writes);
        if (!batch) return;
        rowIndexCache.rebase(batch.nextData);
        forgetDeferredRows();
        lastEmittedData = batch.nextData;
        s.onDataChange?.(batch.nextData, { source: "delete", ops: batch.ops });
        set({
          data: batch.nextData,
          cellErrors: applyRowValidation(s, clearErrorsForOps(s.cellErrors, batch.ops), batch.nextData, batch.ops),
          ...reconcileAfterWrite(s, batch.nextData, batch.ops),
        });
      },
      applyCellUpdates(updates, source) {
        const s = get();
        if (s.readOnly || updates.length === 0) return;
        const batch = computeRowEditsBatch(s, updates);
        if (!batch) return;
        rowIndexCache.rebase(batch.nextData);
        forgetDeferredRows();
        lastEmittedData = batch.nextData;
        s.onDataChange?.(batch.nextData, { source, ops: batch.ops });
        const cellErrors = applyRowValidation(s, clearErrorsForOps(s.cellErrors, batch.ops), batch.nextData, batch.ops);

        // move selection to cover the touched view rect (paste's anchored-expand result).
        let minRow = Infinity, maxRow = -Infinity, minCol = Infinity, maxCol = -Infinity;
        const idByCol = new Map(s.visibleColumns.map((c, i) => [c.id, i] as const));
        for (const u of updates) {
          const col = idByCol.get(u.columnId);
          if (col === undefined) continue;
          minRow = Math.min(minRow, u.viewRow);
          maxRow = Math.max(maxRow, u.viewRow);
          minCol = Math.min(minCol, col);
          maxCol = Math.max(maxCol, col);
        }
        if (minRow === Infinity) {
          set({ data: batch.nextData, cellErrors, ...reconcileAfterWrite(s, batch.nextData, batch.ops) });
          return;
        }
        const range = rectFromCorners({ col: minCol, row: minRow }, { col: maxCol, row: maxRow });
        set({
          data: batch.nextData,
          cellErrors,
          selection: { ...emptySelection(), current: { cell: { col: minCol, row: minRow }, range, rangeStack: [] } },
          activeCell: { col: minCol, row: minRow },
          ...reconcileAfterWrite(s, batch.nextData, batch.ops),
        });
      },
      updateCells(patches, options) {
        const s = get();
        if (s.readOnly || patches.length === 0) return;
        const skipValidation = options?.skipValidation ?? false;

        // Re-enters with skipValidation once accepted, so the incremental view path only ever sees validated values.
        if (!skipValidation && patchesNeedAsyncCheck(s, patches)) {
          const rowIndex = rowIndexCache.resolve(s.data, s.getRowId);
          const validated = prevalidatePatches(s, patches, rowIndex);
          const apply = (accepted: CellPatch[]) => {
            if (accepted.length === 0) return;
            get().actions.updateCells(accepted, { ...options, skipValidation: true });
          };
          if (validated instanceof Promise) {
            const token = ++streamGeneration;
            void validated.then((accepted) => {
              // A newer updateCells, or any path that moved rows, supersedes this batch silently.
              if (streamGeneration !== token) return;
              apply(accepted);
            });
          } else {
            apply(validated);
          }
          return;
        }

        const rowIndex = rowIndexCache.resolve(s.data, s.getRowId);
        const batch = computeCellPatchBatch(s, patches, rowIndex, skipValidation);
        if (!batch) return;

        const reorder = resolveReorder(options?.reorder, patches, s.sortState, s.filterState);
        rowIndexCache.rebase(batch.nextData);
        lastEmittedData = batch.nextData;
        s.onDataChange?.(batch.nextData, { source: options?.source ?? "stream", ops: batch.ops });
        // clearErrorsForOps returns the SAME map identity when `s.cellErrors` is empty (the common
        // streaming case), so this costs nothing extra on the hot path this action exists for.
        const cellErrors = applyRowValidation(s, clearErrorsForOps(s.cellErrors, batch.ops), batch.nextData, batch.ops);

        // The fast path, and the whole point of the action: one set() writing `data` alone. Row
        // identities changed only for touched rows, so their per-row subscriptions re-render and
        // every other row's memo holds. viewIndex/searchMatches/visibleColumns keep their identity,
        // so no comparator downstream of them re-runs.
        if (reorder !== "immediate") {
          // Recorded for `"never"` too: that mode is a caller ASSERTION that no touched column feeds
          // the view, and a later reconcile has to stay correct even when the assertion was wrong.
          rememberDeferredRows(batch.touchedRows);
          set(
            reorder === "defer" && !s.viewStale
              ? { data: batch.nextData, viewStale: true, cellErrors }
              : { data: batch.nextData, cellErrors },
          );
          return;
        }
        // Incremental maintenance: a full rebuild re-sorts all n rows every tick, and a patch of a
        // few rows can only move those rows. Rows an earlier non-reordering batch left unreconciled
        // move in this pass too, since the rest of the order is what the binary search trusts.
        const viewIndex = resolveViewIndex(s, batch.nextData, pendingRows(batch.touchedRows));
        resetDeferredRows();
        set({
          data: batch.nextData,
          cellErrors,
          viewIndex,
          viewStale: false,
          ...computeSearchMatches(batch.nextData, s.columns, viewIndex, s.visibleColumns, s.searchText),
        });
      },
      updateRows(updates, options) {
        if (updates.length === 0) return;
        const patches: CellPatch[] = [];
        for (const update of updates) {
          for (const columnId of Object.keys(update.changes)) {
            patches.push({ rowId: update.rowId, columnId, value: update.changes[columnId] });
          }
        }
        get().actions.updateCells(patches, options);
      },
      reconcileView() {
        const s = get();
        if (!s.viewStale) return;
        // Same incremental path an `"immediate"` batch takes, over whatever the deferred batches touched.
        const viewIndex = resolveViewIndex(s, s.data, pendingRows([]));
        resetDeferredRows();
        set({
          viewIndex,
          viewStale: false,
          ...computeSearchMatches(s.data, s.columns, viewIndex, s.visibleColumns, s.searchText),
        });
      },
      insertRow(viewRowIndex, position) {
        // single implementation path: the 1-row case of the batch action (same one undo step).
        get().actions.insertRows(viewRowIndex, 1, position);
      },
      insertRows(viewRowIndex, count, position = "below") {
        const s = get();
        if (s.readOnly) return;
        if (!s.createRow) {
          warnDev("row insertion is a no-op because no `createRow` prop was provided");
          return;
        }
        if (count <= 0 || !Number.isInteger(count)) {
          if (count > 0) warnDev(`insertRows: count must be an integer (got ${count})`);
          return;
        }
        const dataRowIndex = clampIndex(
          position === "above" ? (s.viewIndex[viewRowIndex] ?? s.data.length) : (s.viewIndex[viewRowIndex] ?? s.data.length - 1) + 1,
          s.data.length,
        );
        const rows: unknown[] = [];
        for (let i = 0; i < count; i++) rows.push(s.createRow(dataRowIndex + i));
        const batch = computeInsertRowsBatch(s, dataRowIndex, rows);
        rowIndexCache.invalidate();
        forgetDeferredRows();
        lastEmittedData = batch.nextData;
        s.onDataChange?.(batch.nextData, { source: "row-op", ops: batch.ops });
        // the new rows land at this view index (absent a resort); shift selection/activeCell to follow them.
        const viewInsertAt = position === "above" ? viewRowIndex : viewRowIndex + 1;
        set({
          data: batch.nextData,
          cellErrors: pruneCellErrors(s.cellErrors, batch.nextData, s.getRowId),
          selection: offsetSelectionForRows(s.selection, viewInsertAt, count),
          activeCell: s.activeCell && s.activeCell.row >= viewInsertAt
            ? { ...s.activeCell, row: s.activeCell.row + count }
            : s.activeCell,
        });
      },
      deleteRows(viewRowIndexes) {
        const s = get();
        if (s.readOnly) return;
        const dataRowIndexes = viewRowIndexes.map((viewRow) => s.viewIndex[viewRow]).filter((i): i is number => i !== undefined);
        const batch = computeDeleteBatch(s, dataRowIndexes);
        if (!batch) return;
        rowIndexCache.invalidate();
        forgetDeferredRows();
        lastEmittedData = batch.nextData;
        s.onDataChange?.(batch.nextData, { source: "row-op", ops: batch.ops });
        set({
          data: batch.nextData,
          cellErrors: pruneCellErrors(s.cellErrors, batch.nextData, s.getRowId),
          selection: emptySelection(),
          activeCell: null,
        });
      },
      duplicateRows(viewRowIndexes) {
        const s = get();
        if (s.readOnly) return;
        if (!s.duplicateRow) {
          warnDev("duplicateRows is a no-op because no `duplicateRow` prop was provided");
          return;
        }
        const dataRowIndexes = viewRowIndexes.map((viewRow) => s.viewIndex[viewRow]).filter((i): i is number => i !== undefined);
        const batch = computeDuplicateBatch(s, dataRowIndexes);
        if (!batch) return;
        rowIndexCache.invalidate();
        forgetDeferredRows();
        lastEmittedData = batch.nextData;
        s.onDataChange?.(batch.nextData, { source: "row-op", ops: batch.ops });
        // each duplicate lands directly after its source view row (absent a resort); fold one
        // offset per source, ascending, so earlier insertions shift later sources' view indices too.
        const uniqueAscendingViewRows = Array.from(new Set(viewRowIndexes)).sort((a, b) => a - b);
        let selection = s.selection;
        let activeCell = s.activeCell;
        uniqueAscendingViewRows.forEach((viewRow, i) => {
          const insertAt = viewRow + 1 + i;
          selection = offsetSelectionForRows(selection, insertAt, 1);
          if (activeCell && activeCell.row >= insertAt) activeCell = { ...activeCell, row: activeCell.row + 1 };
        });
        set({ data: batch.nextData, cellErrors: pruneCellErrors(s.cellErrors, batch.nextData, s.getRowId), selection, activeCell });
      },
      _moveActiveCell(d, opts) {
        const s = get();
        const active = s.activeCell ?? { col: 0, row: 0 };
        const maxRow = Math.max(0, s.viewIndex.length - 1);
        const maxCol = Math.max(0, s.visibleColumns.length - 1);
        if (opts?.extend && s.enableRangeSelection) {
          // Grow from the anchor's far edge (Excel-correct contraction), never re-deriving
          // `next` from activeCell — the anchor stays put for the whole extend gesture.
          const direction: ExtendDirection = d.dy < 0 ? "up" : d.dy > 0 ? "down" : d.dx < 0 ? "left" : "right";
          const selection = extendSelection(s.selection.current ? s.selection : selectCellPure(active), direction, {
            rowCount: s.viewIndex.length,
            colCount: s.visibleColumns.length,
          });
          const edge = selection.current?.range;
          set({
            selection,
            lastHighlightedRow: edge ? (d.dy < 0 ? edge.y : edge.y + edge.height - 1) : active.row,
            lastHighlightedCol: edge ? (d.dx < 0 ? edge.x : edge.x + edge.width - 1) : active.col,
          });
        } else {
          const next = { col: clampIndex(active.col + d.dx, maxCol), row: clampIndex(active.row + d.dy, maxRow) };
          if (opts?.retain) {
            set({ activeCell: next, lastHighlightedRow: next.row, lastHighlightedCol: next.col });
          } else {
            set({ activeCell: next, selection: selectCellPure(next), lastHighlightedRow: next.row, lastHighlightedCol: next.col });
          }
        }
      },
      _syncProps(props) {
        set((s) => {
          // controlled sort/filter/join/search: the prop (when defined) is the source of truth this
          // sync writes into the store; uncontrolled: keep whatever the store's own actions last set.
          const nextSortState = props.sortState ?? s.sortState;
          // backfill: a controlled filterState prop may omit filterId (backward-compat input boundary).
          const nextFilterState = props.filterState ? withFilterIds(props.filterState) : s.filterState;
          const nextJoinOperator = props.joinOperator ?? s.joinOperator;
          const nextSearchText = props.searchText ?? s.searchText;
          // data: controlled (props.data defined) mirrors the prop every sync, byte-identical to
          // pre-defaultData behavior; uncontrolled keeps the store's own array — every commit action
          // (edit/paste/fill/delete/row-ops) already wrote it there directly, and `defaultData` itself
          // is init-only (never re-read past store creation, matching `<input defaultValue>`).
          const nextData = s.dataControlled && props.data !== undefined ? props.data : s.data;
          // Echo detection: a controlled consumer that stores what onDataChange handed it and
          // re-renders feeds that exact array back here. `data` then differs from the last sync by
          // identity, so syncInputsEqual fails and computeViewIndex runs — the ~56 ms cliff at 100k
          // rows with a sort active. Recognizing our own array skips it, which is what makes
          // updateCells fast for controlled consumers too (design spec §3.3). A consumer who maps,
          // filters, or otherwise rebuilds the array before storing it falls back to the slow path.
          const isEcho = nextData === lastEmittedData;
          // A `data` array we did not produce reordered or replaced rows as far as this store knows,
          // so the id map must be rebuilt. Our own echo never moved a row (updateCells patches
          // values in place), so it keeps the map — rebuilding it per tick is the O(n) cost the API
          // exists to remove.
          // A genuine consumer-driven replacement (not our own echo) may have dropped rows (e.g. an
          // import replacing the whole array) — prune any cellErrors entry whose rowId no longer
          // exists, same discipline as the rowId-index cache invalidation right below.
          const nextCellErrors =
            nextData !== s.data && !isEcho ? pruneCellErrors(s.cellErrors, nextData, s.getRowId) : s.cellErrors;
          if (nextData !== s.data && !isEcho) {
            rowIndexCache.invalidate();
            forgetDeferredRows();
          }
          // A genuine consumer-driven `columns` prop change replaces `s.columns` outright; syncing
          // again with the SAME prop reference (any unrelated re-render) keeps `s.columns` as-is so
          // runtime column-pin mutations (setColumnPin / the initial-layout seed) survive it.
          const propsColumnsChanged = props.columns !== lastPropsColumns;
          lastPropsColumns = props.columns;
          const nextColumns = propsColumnsChanged ? props.columns : s.columns;
          // same registry-widening cast as createDataGridStore's init — see that comment.
          const nextCellTypes =
            (props.cellTypes as unknown as Record<string, CellType> | undefined) ?? (defaultCellTypes as unknown as Record<string, CellType>);
          const nextSyncInputs: SyncInputs = {
            data: nextData,
            cellTypes: nextCellTypes,
            columns: nextColumns,
            sortState: nextSortState,
            filterState: nextFilterState,
            joinOperator: nextJoinOperator,
            searchText: nextSearchText,
            columnOrder: s.columnOrder,
            hiddenColumns: s.hiddenColumns,
          };
          // An echo only licenses skipping the recompute when `data` is the ONLY input that moved —
          // a sync that also changed sort/filter/search/columns still has to rebuild for those.
          const echoOnly =
            isEcho && syncInputsEqual({ ...nextSyncInputs, data: lastSyncInputs.data }, lastSyncInputs);
          const unchanged = syncInputsEqual(nextSyncInputs, lastSyncInputs) || echoOnly;
          lastSyncInputs = nextSyncInputs;

          const nextVisibleColumns = unchanged ? s.visibleColumns : computeVisibleColumns(nextColumns, s.columnOrder, s.hiddenColumns);
          const nextViewIndex = unchanged
            ? s.viewIndex
            : computeViewIndex(nextData, nextColumns, nextSortState, nextFilterState, nextJoinOperator, s.viewIndex, nextCellTypes);
          // A full rebuild leaves nothing pending for the incremental path to replay.
          if (!unchanged) resetDeferredRows();
          // If viewIndex is unchanged (same reference either from the guard above or from
          // computeViewIndex's own content-equality reuse), no row fell out of view, so this
          // clamp is a no-op — filtering against nextViewIndex.length still runs but keeps every row.
          const rows = s.selection.rows.length === 0
            ? s.selection.rows
            : CompactSelection.fromArray(s.selection.rows.toArray().filter((row) => row < nextViewIndex.length));
          return {
            ...props,
            ...resolveSelectionConfig(props),
            data: nextData,
            cellErrors: nextCellErrors,
            columns: nextColumns,
            cellTypes: nextCellTypes,
            labels: mergeLabels(props.labels),
            overlayPlugins: props.overlayPlugins ?? EMPTY_OVERLAY_PLUGINS,
            rowBands: props.rowBands ?? EMPTY_ROW_BANDS,
            visibleColumns: nextVisibleColumns,
            sortState: nextSortState,
            filterState: nextFilterState,
            joinOperator: nextJoinOperator,
            searchText: nextSearchText,
            sortControlled: props.sortState !== undefined,
            filterControlled: props.filterState !== undefined,
            joinOperatorControlled: props.joinOperator !== undefined,
            searchControlled: props.searchText !== undefined,
            viewIndex: nextViewIndex,
            // A real recompute reconciles whatever a deferred updateCells left stale; an echo or an
            // unchanged sync recomputed nothing, so the flag has to survive it.
            viewStale: unchanged ? s.viewStale : false,
            ...(unchanged
              ? { searchMatches: s.searchMatches, searchMatchSet: s.searchMatchSet, searchMatchRows: s.searchMatchRows, searchMatchesCapped: s.searchMatchesCapped }
              : computeSearchMatches(nextData, nextColumns, nextViewIndex, nextVisibleColumns, nextSearchText)),
            selection: rows === s.selection.rows ? s.selection : { ...s.selection, rows },
          };
        });
      },
      _registerScrollToCell(impl) {
        set({ scrollToCellImpl: impl });
      },
      _registerReadOnly(readOnly) {
        set({ readOnly });
      },
      _registerKeymap(keymap) {
        set({ keymap });
      },
      _registerFillHandlers(handlers) {
        set({ fillHandlers: handlers });
      },
    },
  }));
}

import { useCallback, useMemo, useRef } from "react";
import { useShallow } from "zustand/react/shallow";
import type {
  CellCoord,
  CellType,
  FilterJoinOperator,
  FilterSpec,
  GridSelection,
  HeaderClickBehavior,
  Keymap,
  RowMarkersMode,
  SortSpec,
} from "../types";
import type { OverlayPlugin } from "../overlays";
import type { RowBandsSpec } from "../layout-context";
import type { DataGridLabels } from "../labels";
import type { SearchMatch } from "../sort-filter";
import { isSelectionEmpty, selectionContainsCell } from "../selection";
import { colRangesEqual, selectedColRangesForRow, type ColRange } from "../selection/selected-col-ranges-for-row";
import { cellErrorKey, getRangeValues, searchMatchKey } from "./compute";
import { useDataGridStore, useDataGridStoreApi } from "./provider";
import type { AnyColumnDef, ColumnDefOf, DataGridActions, DataGridCellState, DataGridRowCellState, DataGridStoreState } from "./types";

/** The stable actions object for the current grid; never changes identity, so this hook never re-renders. */
export function useDataGridActions(): DataGridActions {
  return useDataGridStore((s) => s.actions);
}

/**
 * The resolved cell-type registry (the consumer's `cellTypes` prop, or the built-ins) — the same
 * registry `cell.tsx` and the store's own edit/clipboard/fill resolution read, so tooling that
 * needs to resolve a column's `Cell`/`Editor` never has to guess whether a custom registry is in
 * play. Reference is stable after init, so subscribing costs no re-renders.
 */
export function useDataGridCellTypes(): Record<string, CellType> {
  return useDataGridStore((s) => s.cellTypes);
}

/**
 * Imperative scroll-into-view for a view-space cell coord, honoring pinned bands — the same
 * mechanism keyboard nav uses internally, exposed as a public extension point for add-ons that
 * move the active cell from outside `DataGridRoot`'s subtree (e.g. `data-grid-toolbar`'s
 * search next/prev). No-op before `DataGridRoot` mounts or after it unmounts.
 */
export function useDataGridScrollToCell(): (coord: CellCoord) => void {
  const storeApi = useDataGridStoreApi();
  return useCallback((coord: CellCoord) => storeApi.getState().scrollToCellImpl?.(coord), [storeApi]);
}

/**
 * Fill-handle keymap handlers registered by the `data-grid-fill` add-on's tracker component (see
 * `fillHandlers`'s doc comment) — read by `DataGridRoot` itself on every render and forwarded to
 * `useGridInteraction`'s optional `fillDown`/`fillRight`/`cancelFillDrag` params. `null` before the
 * add-on's tracker mounts (or when it's absent entirely), matching every other registration slot's
  * no-op-by-default contract. Not part of the public API; consumers should not import it.
  * @internal
  */
export function useDataGridFillHandlers(): DataGridStoreState["fillHandlers"] {
  return useDataGridStore((s) => s.fillHandlers);
}

/**
 * Mirrors the mounted `DataGridRoot`'s `readOnly` prop — for add-on
 * mutation surfaces outside the root's subtree (e.g. the context-menu add-on) that need to hide or
 * disable their own actions on a read-only grid. `false` before mount/after unmount.
 */
export function useDataGridReadOnly(): boolean {
  return useDataGridStore((s) => s.readOnly);
}

/**
 * The mounted `DataGridRoot`'s effective keymap — `DEFAULT_KEYMAP` merged over with its `keymap`
 * prop — the single source of truth for every bound action (backs the `data-grid-keybindings`
 * add-on's dialog so it never hardcodes a shortcut list). `DEFAULT_KEYMAP`
 * before mount/after unmount.
 */
export function useDataGridKeymap(): Keymap {
  return useDataGridStore((s) => s.keymap);
}

/**
 * The current grid's effective i18n labels — {@link DEFAULT_LABELS} deep-merged with the
 * `DataGridProvider`'s `labels` prop — the single source of truth
 * every core + add-on component reads its user-facing strings from. Stable identity across renders
 * that don't change the `labels` prop's reference (see `memoizedMergeLabels`).
 */
export function useDataGridLabels(): DataGridLabels {
  return useDataGridStore((s) => s.labels);
}

/** The currently active (focused) cell, or null when nothing is active. */
export function useDataGridActiveCell(): CellCoord | null {
  return useDataGridStore((s) => s.activeCell);
}

/**
 * Whether ANY cell is currently active — a primitive boolean, unlike {@link useDataGridActiveCell}'s
 * `CellCoord | null`, so it only re-renders its subscriber on the null <-> non-null transition (once,
 * on first activation), never on every subsequent row/column move. `DataGridRoot` uses this for its
 * roving-tabindex bootstrap (tabIndex 0 before any cell is active, -1 after): subscribing to the full
 * `activeCell` there instead would re-render the root (and thus every context consumer, since its
 * context value is a fresh object literal every render) on every single cell move, defeating the
 * "only windowedColumns/activeColumn changes re-render the tree" invariant the perf suite checks.
 */
export function useDataGridHasActiveCell(): boolean {
  return useDataGridStore((s) => s.activeCell !== null);
}

/**
 * The cell that should be scrolled into view for the current interaction: the far corner of the
 * selection range opposite the anchor while a range-extend is in progress, else `activeCell`.
 * Derived fresh from `selection.current` every call (never cached) so it can't go stale the way a
 * separately-written field could — `extendTo` (shift-click/drag) never touched `lastHighlightedRow/Col`,
 * only `_moveActiveCell`'s keyboard extend branch did, which silently broke every non-keyboard
 * extend gesture's scroll-follow. Anchor-inside-range is a store invariant (types.ts), so the far
 * corner is always well-defined as "whichever edge the anchor isn't on". Internal focus query —
 * not part of the public API; consumers should not import it.
 * @internal
 */
export function getFocusCell(state: DataGridStoreState): CellCoord | null {
  const current = state.selection.current;
  if (!current) return state.activeCell;
  const { cell, range } = current;
  const isSingleCell = range.width === 1 && range.height === 1;
  if (isSingleCell) return state.activeCell;
  const row = cell.row === range.y ? range.y + range.height - 1 : range.y;
  const col = cell.col === range.x ? range.x + range.width - 1 : range.x;
  return { col, row };
}

/**
 * The active cell's COLUMN only (primitive selector) — for tooling and subscribers that don't care
 * about row moves; vertical arrow navigation never re-renders them.
 */
export function useDataGridActiveColumn(): number | null {
  return useDataGridStore((s) => s.activeCell?.col ?? null);
}

/** The current selection model. */
export function useDataGridSelection(): GridSelection {
  return useDataGridStore((s) => s.selection);
}

/**
 * Standalone escape hatch for reading a grid's current selection values OUTSIDE an
 * `onSelectionChange` fire — e.g. a toolbar "copy as JSON" button that needs the live values on
 * click, not from the last change notification. Returns a stable callback (identical across
 * renders); calling it reads the store fresh each time, same lazy-per-call, primary-range-only
 * semantics as `onSelectionChange`'s `details.getValues()` (see {@link SelectionChangeDetails}) —
 * this hook exists so a consumer who only needs values imperatively never has to subscribe to
 * `useDataGridSelection()` (and re-render on every selection change) just to read them on click.
 */
export function useDataGridGetSelectionValues(): () => unknown[][] {
  const storeApi = useDataGridStoreApi();
  return useCallback(() => {
    const s = storeApi.getState();
    const range = s.selection.current?.range;
    return range ? getRangeValues(s, range) : [];
  }, [storeApi]);
}

/**
 * Registered overlay plugins; consumed ONLY by {@link DataGridOverlays} — never by row/cell
 * subscriptions. Not part of the public API; consumers should not import it.
 * @internal
 */
export function useDataGridOverlayPlugins(): readonly OverlayPlugin[] {
  return useDataGridStore(useShallow((s) => s.overlayPlugins));
}

/**
 * Registered row-bands spec; consumed ONLY by {@link DataGridRoot} — reads `topRows`/`bottomRows.length`
 * for its own height/aria-rowcount math and calls `renderBand`. Not part of the public API;
 * consumers should not import it.
 * @internal
 */
export function useDataGridRowBands(): RowBandsSpec {
  return useDataGridStore((s) => s.rowBands);
}

/** The in-progress cell edit, or null when no cell is being edited. */
export function useDataGridEditing(): { coord: CellCoord; initialText?: string } | null {
  return useDataGridStore((s) => s.editing);
}

/** The transient rejection message from the last failed commitCellEdit, or null. */
export function useDataGridEditingError(): string | null {
  return useDataGridStore((s) => s.editingError);
}

/**
 * Post-commit server-error map, keyed `"rowId:columnId"` — see `cellErrors`' doc
 * comment for the full auto-clear/history/zero-render contract. Reach for this to build a
 * consumer-side summary (an error count badge, a "N cells need attention" banner); a rendering
 * cell itself should use {@link useDataGridCellState}/{@link useDataGridRowCellState} instead,
 * which read the SAME map but scoped to one cell/row so an unrelated error never re-renders them.
 */
export function useDataGridCellErrors(): ReadonlyMap<string, string> {
  return useDataGridStore((s) => s.cellErrors);
}

/**
 * Whether `rowId` has ANY cell error, for a row-level indicator (e.g. a row-marker badge) that
 * doesn't need atomic per-cell scoping. Probes one exact key per column rather than prefix-matching
 * the map: both ids may contain colons, so `"a"` prefix-matches row `"a:b"`'s keys (see #85).
 */
export function useDataGridRowHasError(rowId: string | undefined): boolean {
  return useDataGridStore((s) => {
    if (rowId === undefined || s.cellErrors.size === 0) return false;
    for (const column of s.columns) {
      if (s.cellErrors.has(cellErrorKey(rowId, column.id))) return true;
    }
    return false;
  });
}

/** The sorted/filtered/searched row-index view, in display order. */
export function useDataGridViewIndex(): number[] {
  return useDataGridStore(useShallow((s) => s.viewIndex));
}

/**
 * True when a deferred `updateCells` batch changed a value the active sort or filter reads, so the
 * displayed order no longer matches the data. Show a "re-sort" control on this and call
 * `actions.reconcileView()` from it. Stays `false` for a stream that touches no sort or filter
 * column — that case downgrades to `"never"` automatically. See {@link UpdateCellsOptions}.
 */
export function useDataGridViewStale(): boolean {
  return useDataGridStore((s) => s.viewStale);
}

/**
 * Visible columns in display order: pinned-left, then unpinned, then pinned-right. Callable directly
 * (`accessorFn`/`setValue`/function-form `readOnly` accept an `unknown` row with no cast) since the
 * default `TData = unknown` matches the store's own internal row type; pass your own row type
 * (`useDataGridVisibleColumns<Employee>()`) to get back `ColumnDef<Employee, unknown>[]` instead —
 * sound because these columns always originated from the same consumer-typed `columns` prop.
 */
export function useDataGridVisibleColumns<TData = unknown>(): readonly ColumnDefOf<TData>[] {
  return useDataGridStore(useShallow((s) => s.visibleColumns)) as readonly ColumnDefOf<TData>[];
}

/**
 * Every column (including currently-hidden ones), in `columnOrder` order (definition order when
 * unset) — the columns-visibility/pin menu's full inventory, unlike {@link useDataGridVisibleColumns}
 * which excludes hidden columns. Same optional `TData` typed-narrowing as `useDataGridVisibleColumns`.
 */
export function useDataGridAllColumns<TData = unknown>(): readonly ColumnDefOf<TData>[] {
  return useDataGridStore(
    useShallow((s) => {
      const orderedIds = s.columnOrder ?? s.columns.map((c) => c.id);
      const byId = new Map(s.columns.map((c) => [c.id, c] as const));
      return orderedIds.map((id) => byId.get(id)).filter((c): c is AnyColumnDef => c != null);
    }),
  ) as readonly ColumnDefOf<TData>[];
}

/** Whether a column id is currently hidden via `setColumnHidden` (independent of its def-level `hidden`, which seeds this set). */
export function useDataGridIsColumnHidden(columnId: string): boolean {
  return useDataGridStore((s) => s.hiddenColumns.includes(columnId));
}

/** A single column's current width in px, or undefined when unset (falls back to the column def). */
export function useDataGridColumnWidth(columnId: string): number | undefined {
  return useDataGridStore((s) => s.columnWidths[columnId]);
}

/** Live width overrides for a set of column ids, in the same order — one subscription, safe under a changing column count. */
export function useDataGridColumnWidths(columnIds: readonly string[]): (number | undefined)[] {
  return useDataGridStore(useShallow((s) => columnIds.map((id) => s.columnWidths[id])));
}

/** The active multi-column sort spec. */
export function useDataGridSortState(): SortSpec[] {
  return useDataGridStore(useShallow((s) => s.sortState));
}

/** How a plain header click behaves; see {@link HeaderClickBehavior}. */
export function useDataGridHeaderClickBehavior(): HeaderClickBehavior {
  return useDataGridStore((s) => s.headerClickBehavior);
}

/** The resolved (defaulted) column-feature flags: resize/reorder/pin enablement grid-wide. */
export function useDataGridColumnFeatureFlags(): {
  enableColumnResize: boolean;
  enableColumnReorder: boolean;
  enableColumnPinning: boolean;
} {
  return useDataGridStore(
    useShallow((s) => ({
      enableColumnResize: s.enableColumnResize,
      enableColumnReorder: s.enableColumnReorder,
      enableColumnPinning: s.enableColumnPinning,
    })),
  );
}

/** The active per-column filter specs. */
export function useDataGridFilterState(): FilterSpec[] {
  return useDataGridStore(useShallow((s) => s.filterState));
}

/** How `filterState`'s rows combine; default `"and"`. See {@link FilterJoinOperator}. */
export function useDataGridJoinOperator(): FilterJoinOperator {
  return useDataGridStore((s) => s.joinOperator);
}

/** The current quick-search text. */
export function useDataGridSearchText(): string {
  return useDataGridStore((s) => s.searchText);
}

/**
 * Every cell matching the current `searchText`, in view-space row-major order, capped at 1000 hits.
 * Reads the store's precomputed slice — `setSearch`/`setSorts`/`setFilters`/`_syncProps` are the
 * only places that (re)run `findSearchMatches`, exactly once each, never per-subscriber.
 */
export function useDataGridSearchMatches(): SearchMatch[] {
  return useDataGridStore(useShallow((s) => s.searchMatches));
}

/** True when `searchMatches` hit the 1000-match cap — drives the toolbar's "1000+" badge. */
export function useDataGridSearchCapped(): boolean {
  return useDataGridStore((s) => s.searchMatchesCapped);
}

/** Whether `coord` (view-space) is a search-match highlight target — an O(1) Set lookup, never a per-cell scan ({@link DataGridCell}'s `data-search-match`). */
export function useDataGridIsSearchMatch(coord: CellCoord): boolean {
  const column = useDataGridStore((s) => s.visibleColumns[coord.col]);
  return useDataGridStore((s) => (column ? s.searchMatchSet.has(searchMatchKey(coord.row, column.id)) : false));
}

/** The data row at a given view (display) row index; re-renders only when that row's identity changes. */
export function useDataGridRow(viewRowIndex: number): unknown {
  return useDataGridStore((s) => {
    const dataRowIndex = s.viewIndex[viewRowIndex];
    return dataRowIndex === undefined ? undefined : s.data[dataRowIndex];
  });
}

/** Stable `getRowId` result for the row at a given view row index; used as the React key so rows survive sort/filter/insert/delete. */
export function useDataGridRowId(viewRowIndex: number): string | undefined {
  return useDataGridStore((s) => {
    const dataRowIndex = s.viewIndex[viewRowIndex];
    if (dataRowIndex === undefined) return undefined;
    const row = s.data[dataRowIndex];
    return row === undefined ? undefined : s.getRowId(row, dataRowIndex);
  });
}

/** `getRowId` results for a set of view row indices, in the same order — one subscription, safe under a changing window size. */
export function useDataGridRowIds(viewRowIndices: readonly number[]): (string | undefined)[] {
  return useDataGridStore(
    useShallow((s) =>
      viewRowIndices.map((viewRowIndex) => {
        const dataRowIndex = s.viewIndex[viewRowIndex];
        if (dataRowIndex === undefined) return undefined;
        const row = s.data[dataRowIndex];
        return row === undefined ? undefined : s.getRowId(row, dataRowIndex);
      }),
    ),
  );
}

/**
 * Full `rowId -> view row index` map for the current view (2026-08-02 optimization audit,
 * "rowId-native presence adapter" — confirmed medium: the docs' DIY mapping built this with
 * `useDataGridRowIds` under `useShallow`, which re-runs its full-array `.map()` PLUS an n-element
 * `shallow()` compare on every store write, not just view changes). Subscribes to `viewIndex`,
 * `data`, and `getRowId` identity ONLY — three atomic primitive-reference reads, cheap on every
 * store change — and builds the Map lazily in `useMemo` keyed on those identities, so the O(n)
 * build cost is paid once per actual view change (sort/filter/insert/delete) or `getRowId` swap,
 * never per keystroke, selection step, or streaming tick. `data` is in the memo key (not just
 * `viewIndex`) because `getRowId` reads row objects out of it; a `data` replacement with the same
 * `viewIndex` (e.g. a value-only edit) must still rebuild since row identities may have changed.
 * Consumers needing view -> rowId (the other direction) already have
 * {@link useDataGridRowId}/{@link useDataGridRowIds}.
 */
export function useDataGridRowIdToViewRow(): ReadonlyMap<string, number> {
  const viewIndex = useDataGridStore((s) => s.viewIndex);
  const data = useDataGridStore((s) => s.data);
  const getRowId = useDataGridStore((s) => s.getRowId);
  return useMemo(() => {
    const map = new Map<string, number>();
    for (let viewRow = 0; viewRow < viewIndex.length; viewRow++) {
      const dataRowIndex = viewIndex[viewRow];
      if (dataRowIndex === undefined) continue;
      const row = data[dataRowIndex];
      if (row === undefined) continue;
      map.set(getRowId(row, dataRowIndex), viewRow);
    }
    return map;
  }, [viewIndex, data, getRowId]);
}

/** Total number of rows currently in view (after filter/search). */
export function useDataGridRowCount(): number {
  return useDataGridStore((s) => s.viewIndex.length);
}

/** Shared range-membership predicate: true when `viewRowIndex` falls inside the active range or any stacked range. */
function isRowInRangeChannel(selection: GridSelection, viewRowIndex: number): boolean {
  if (!selection.current) return false;
  const { range, rangeStack } = selection.current;
  const inRect = (r: { x: number; y: number; width: number; height: number }) => viewRowIndex >= r.y && viewRowIndex < r.y + r.height;
  return inRect(range) || rangeStack.some(inRect);
}

/** Whether the row at a given view row index is selected via any selection channel (selection state is view-space, so no viewIndex mapping here). */
export function useDataGridIsRowSelected(viewRowIndex: number): boolean {
  return useDataGridStore((s) => s.selection.rows.hasIndex(viewRowIndex) || isRowInRangeChannel(s.selection, viewRowIndex));
}

/** The ROWS channel only: this row is selected as a whole (marker press/drag, Shift+Space). Deliberately excludes the cell/column channels — the marker renderer's `isSelected` must flip on row selection alone, never on a cell click (see {@link MarkerCellRenderCtx}). */
export function useDataGridIsRowChannelSelected(viewRowIndex: number): boolean {
  return useDataGridStore((s) => s.selection.rows.hasIndex(viewRowIndex));
}

/** Whether the cell channel (active range/range stack) or the column channel covers at least one cell of this view row. The rows-channel-free half of the marker renderer's `isRowChannelSelected`/`isCellSelected` pair. */
export function useDataGridIsRowCellSelected(viewRowIndex: number): boolean {
  return useDataGridStore((s) => s.selection.columns.length > 0 || isRowInRangeChannel(s.selection, viewRowIndex));
}

/** Whether `coord` is the active (focused) cell — an atomic per-cell subscription so an active-cell move re-renders only the two affected cells, never every cell or any row. */
export function useDataGridIsCellActive(coord: CellCoord): boolean {
  return useDataGridStore((s) => s.activeCell !== null && s.activeCell.col === coord.col && s.activeCell.row === coord.row);
}

/** Whether `coord` is the cell currently being edited — same atomic-subscription rationale as {@link useDataGridIsCellActive}. */
export function useDataGridIsCellEditing(coord: CellCoord): boolean {
  return useDataGridStore((s) => s.editing !== null && s.editing.coord.col === coord.col && s.editing.coord.row === coord.row);
}

/** The initial-text seed for `coord`'s edit session (type-to-replace), or undefined; null when `coord` isn't the editing cell. Atomic per-cell, like {@link useDataGridIsCellEditing}. */
export function useDataGridCellInitialText(coord: CellCoord): string | undefined {
  return useDataGridStore((s) =>
    s.editing !== null && s.editing.coord.col === coord.col && s.editing.coord.row === coord.row
      ? s.editing.initialText
      : undefined,
  );
}

/**
 * `editingError` scoped to whether `coord` is the currently-editing cell — null for every other
 * cell. Deliberately NOT a plain `useDataGridEditingError()` read inside `DataGridCell`: that would
 * select the same raw string for every mounted cell, so a rejection would re-render the whole
 * visible window instead of only the editing cell — same atomic-subscription rationale as
 * {@link useDataGridIsCellEditing}/{@link useDataGridCellInitialText}.
 */
export function useDataGridCellEditingError(coord: CellCoord): string | null {
  return useDataGridStore((s) =>
    s.editing !== null && s.editing.coord.col === coord.col && s.editing.coord.row === coord.row ? s.editingError : null,
  );
}

/**
 * `editingRejectionCount` scoped to whether `coord` is the currently-editing cell (0 for every
 * other cell) — the commit-guard re-arm nonce {@link DataGridCell} forwards to its `Editor`. Same
 * atomic-subscription rationale as {@link useDataGridCellEditingError}: a rejection re-renders the
 * editing cell only, never the whole visible window.
 */
export function useDataGridCellRejectionCount(coord: CellCoord): number {
  return useDataGridStore((s) =>
    s.editing !== null && s.editing.coord.col === coord.col && s.editing.coord.row === coord.row
      ? s.editingRejectionCount
      : 0,
  );
}

/**
 * Consolidated per-cell state: one `useShallow` subscription instead of the ~6 separate store reads
 * the individual cell hooks cost together — 7.4→2.7 store.subscribe registrations per mounted cell.
 * The 5-tuple object is genuinely fresh per relevant state change, so `useShallow` is the correct
 * tool here: it still bails when none of the 5 values changed.
 */
export function useDataGridCellState(coord: CellCoord): DataGridCellState {
  return useDataGridStore(
    useShallow((s) => {
      const isActive = s.activeCell !== null && s.activeCell.col === coord.col && s.activeCell.row === coord.row;
      const isSelected = isActive || selectionContainsCell(s.selection, coord, s.viewIndex.length, s.visibleColumns.length);
      const editing = s.editing;
      const editingHere = editing !== null && editing.coord.col === coord.col && editing.coord.row === coord.row;
      const column = s.visibleColumns[coord.col];
      const isSearchMatch = column ? s.searchMatchSet.has(searchMatchKey(coord.row, column.id)) : false;
      const cellError = column ? (s.cellErrors.size === 0 ? null : (cellErrorAt(s, coord.row, column.id) ?? null)) : null;
      return {
        isActive,
        isSelected,
        isEditing: editingHere,
        initialText: editingHere ? editing.initialText : undefined,
        isSearchMatch,
        cellError,
      };
    }),
  );
}

/** Resolves `cellErrors`' message for a view coord's row + a known column id, or undefined when none. */
function cellErrorAt(s: DataGridStoreState, viewRow: number, columnId: string): string | undefined {
  const dataRowIndex = s.viewIndex[viewRow];
  if (dataRowIndex === undefined) return undefined;
  const row = s.data[dataRowIndex];
  if (row === undefined) return undefined;
  const rowId = s.getRowId(row, dataRowIndex);
  return s.cellErrors.get(cellErrorKey(rowId, columnId));
}

const EMPTY_COL_RANGES: readonly ColRange[] = [];

/**
 * This row's errored columns (view-col index -> message), or null when none — mirrors
 * `searchMatchRows`' null-not-empty-Set convention. Unlike search matches (precomputed once per
 * search-text change, since a hit set can be huge over 100k rows), `cellErrors` is expected to stay
 * small — a handful of post-commit server rejections, not a per-row scan target — so this resolves
 * the row's id once and does a plain `${rowId}:${columnId}` Map.get per visible column, gated
 * entirely behind the `cellErrors.size === 0` fast path that costs nothing when no error is active.
 */
function rowErrorCols(s: DataGridStoreState, viewRow: number): ReadonlyMap<number, string> | null {
  if (s.cellErrors.size === 0) return null;
  const dataRowIndex = s.viewIndex[viewRow];
  if (dataRowIndex === undefined) return null;
  const row = s.data[dataRowIndex];
  if (row === undefined) return null;
  const rowId = s.getRowId(row, dataRowIndex);
  let errorCols: Map<number, string> | null = null;
  for (let col = 0; col < s.visibleColumns.length; col++) {
    const column = s.visibleColumns[col];
    if (!column) continue;
    const message = s.cellErrors.get(cellErrorKey(rowId, column.id));
    if (message === undefined) continue;
    if (!errorCols) errorCols = new Map();
    errorCols.set(col, message);
  }
  return errorCols;
}

function computeRowCellState(s: DataGridStoreState, viewRow: number): DataGridRowCellState {
  const activeCol = s.activeCell !== null && s.activeCell.row === viewRow ? s.activeCell.col : null;
  const editing = s.editing;
  const editingHere = editing !== null && editing.coord.row === viewRow;
  const editingCol = editingHere ? editing.coord.col : null;
  const editingInitialText = editingHere ? editing.initialText : undefined;

  // O(1) map lookup instead of an O(visibleColumns) scan + string-key Set.has per column (perf
  // audit 2026-07-17: measured 29x faster at 100k rows/8 cols — see searchMatchRows' doc comment).
  const searchMatchCols: ReadonlySet<number> | null = s.searchMatchRows.get(viewRow) ?? null;

  const errorCols = rowErrorCols(s, viewRow);

  const selectionEmpty = isSelectionEmpty(s.selection);
  const selectedColRanges = selectionEmpty
    ? EMPTY_COL_RANGES
    : selectedColRangesForRow(s.selection, viewRow, s.visibleColumns.length);

  return { activeCol, editingCol, editingInitialText, searchMatchCols, errorCols, selectedColRanges };
}

/** Content equality for two nullable `Set<number>`s — {@link computeRowCellState} allocates a fresh Set per call, so `searchMatchCols` needs content (not reference) comparison to stay referentially stable across unrelated store updates. */
function searchMatchColsEqual(a: ReadonlySet<number> | null, b: ReadonlySet<number> | null): boolean {
  if (a === b) return true;
  if (a === null || b === null || a.size !== b.size) return false;
  for (const col of a) if (!b.has(col)) return false;
  return true;
}

/** Content equality for two nullable `Map<number, string>`s — same rationale as {@link searchMatchColsEqual}, for `errorCols` (a fresh Map per `computeRowCellState` call). */
function errorColsEqual(a: ReadonlyMap<number, string> | null, b: ReadonlyMap<number, string> | null): boolean {
  if (a === b) return true;
  if (a === null || b === null || a.size !== b.size) return false;
  for (const [col, message] of a) if (b.get(col) !== message) return false;
  return true;
}

/** Content equality for {@link DataGridRowCellState} — the comparator `useDataGridRowCellState` uses to keep its selector output referentially stable when nothing in the row actually changed. */
function rowCellStateEqual(a: DataGridRowCellState, b: DataGridRowCellState): boolean {
  if (a === b) return true;
  return (
    a.activeCol === b.activeCol &&
    a.editingCol === b.editingCol &&
    a.editingInitialText === b.editingInitialText &&
    searchMatchColsEqual(a.searchMatchCols, b.searchMatchCols) &&
    errorColsEqual(a.errorCols, b.errorCols) &&
    colRangesEqual(a.selectedColRanges, b.selectedColRanges)
  );
}

/**
 * One subscription per ROW instead of one per CELL: a max-velocity full-window swap mounts ~544
 * cells, and per-cell subscriptions are 544 subscribe/unsubscribe cycles per tick; this is one
 * per row. Mirrors `useShallow`'s ref-memo pattern with {@link rowCellStateEqual} — the shape
 * needs custom comparison (a `Set` by reference, a tuple array by content) that `shallow` cannot
 * express. A selection change recomputes every row's selector, but only the affected row's
 * comparator sees new content — only that row re-renders. Selection membership flips are the one
 * sanctioned cell re-render (aria-selected).
 */
export function useDataGridRowCellState(viewRow: number): DataGridRowCellState {
  const prev = useRef<DataGridRowCellState | undefined>(undefined);
  return useDataGridStore((s) => {
    const next = computeRowCellState(s, viewRow);
    if (prev.current !== undefined && rowCellStateEqual(prev.current, next)) return prev.current;
    return (prev.current = next);
  });
}

/** The resolved (defaulted) marker-column mode; see {@link RowMarkersMode}. */
export function useDataGridRowMarkers(): RowMarkersMode {
  return useDataGridStore((s) => s.rowMarkers);
}

/** The resolved (defaulted) selection-gesture config; see {@link SelectionConfig}. */
export function useDataGridSelectionConfig(): {
  enableRowSelection: boolean;
  enableColumnSelection: boolean;
  enableRangeSelection: boolean;
  enableMultiRange: boolean;
} {
  return useDataGridStore(
    useShallow((s) => ({
      enableRowSelection: s.enableRowSelection,
      enableColumnSelection: s.enableColumnSelection,
      enableRangeSelection: s.enableRangeSelection,
      enableMultiRange: s.enableMultiRange,
    })),
  );
}

/** Half-open row range `[start, end)`. */
type RowRange = readonly [start: number, end: number];

/** Inserts `[start, end)` into `ranges` (sorted, non-overlapping), merging any overlap/adjacency — same algorithm as `mergeRange` in selected-col-ranges-for-row.ts, on the row axis instead of columns. */
function mergeRowRange(ranges: RowRange[], start: number, end: number): void {
  if (start >= end) return;
  let i = 0;
  while (i < ranges.length && ranges[i]![1] < start) i++;
  let mergedStart = start;
  let mergedEnd = end;
  while (i < ranges.length && ranges[i]![0] <= mergedEnd) {
    mergedStart = Math.min(mergedStart, ranges[i]![0]);
    mergedEnd = Math.max(mergedEnd, ranges[i]![1]);
    ranges.splice(i, 1);
  }
  ranges.splice(i, 0, [mergedStart, mergedEnd]);
}

/**
 * Select-all header-marker checkbox tri-state: 'checked' (every view row selected), 'indeterminate'
 * (some), 'unchecked' (none). Empty grid reads 'unchecked'.
 *
 * O(rangeStack) instead of O(rowCount): the old implementation looped every view row calling
 * `hasIndex`/range-membership per row — a six-figure loop at the 100k-row floor, on every store
 * write, in any grid with marker columns (2026-08-02 optimization audit, confirmed high). Coverage
 * is derived from the range channel's rectangles (merged into row intervals, same technique
 * `selectedColRangesForRow` uses on the column axis) unioned against the rows channel, which answers
 * "is this whole span selected" via `CompactSelection.hasAll` in O(its own run count) rather than by
 * scanning every row.
 */
export function useDataGridAllRowsSelected(): "checked" | "indeterminate" | "unchecked" {
  return useDataGridStore((s) => {
    const rowCount = s.viewIndex.length;
    if (rowCount === 0) return "unchecked";
    const { selection } = s;
    const rowsChannelEmpty = selection.rows.length === 0;
    if (rowsChannelEmpty && !selection.current) return "unchecked";
    if (selection.rows.hasAll([0, rowCount])) return "checked";

    const rangeCoverage: RowRange[] = [];
    if (selection.current) {
      const { range, rangeStack } = selection.current;
      mergeRowRange(rangeCoverage, Math.max(0, range.y), Math.min(rowCount, range.y + range.height));
      for (const rect of rangeStack) {
        mergeRowRange(rangeCoverage, Math.max(0, rect.y), Math.min(rowCount, rect.y + rect.height));
      }
    }

    // Gaps left by the range channel must each be fully covered by the rows channel for the union
    // to reach every row — anything less is indeterminate (some selected, not all).
    let cursor = 0;
    let fullyCovered = true;
    for (const [start, end] of rangeCoverage) {
      if (start > cursor && !selection.rows.hasAll([cursor, start])) {
        fullyCovered = false;
        break;
      }
      cursor = Math.max(cursor, end);
    }
    if (fullyCovered && cursor < rowCount && !selection.rows.hasAll([cursor, rowCount])) fullyCovered = false;
    if (fullyCovered) return "checked";

    if (!rowsChannelEmpty || rangeCoverage.length > 0) return "indeterminate";
    return "unchecked";
  });
}

import type { CellPatch, UpdateCellsOptions } from "./types";
import type { FilterSpec, SortSpec } from "../types";

/**
 * Lazily-built, incrementally-maintained `rowId -> dataIndex` map for {@link DataGridActions.updateCells}.
 *
 * Building it costs O(n) (measured 10.1 ms at 100k rows), so a per-call rebuild would reintroduce
 * exactly the per-tick O(n) cost the direct-update API exists to remove. Instead every store path
 * that changes which row sits at which data index calls {@link RowIndexCache.invalidate}, and the
 * next `updateCells` rebuilds once. A pure value patch never moves a row, so the common streaming
 * tick keeps the cache warm forever.
 *
 * The cache is deliberately keyed on the `data` array identity it was built from: any path that
 * replaces `data` without invalidating (a bug, or a future action) is caught on the next lookup
 * instead of silently writing to the wrong row.
 */
export type RowIndexCache = {
  /** `rowId -> dataIndex` for `data`, rebuilding when stale. */
  resolve(data: readonly unknown[], getRowId: (row: unknown, index: number) => string): ReadonlyMap<string, number>;
  /** Drops the cached map. Call from every path that inserts, deletes, reorders, or replaces rows. */
  invalidate(): void;
  /**
   * Carries the cached map across a value-only edit that rebuilt the `data` array without moving any
   * row (every cell-write path: `commitCellEdit`, `commitCellValue`, `deleteSelection`,
   * `applyCellUpdates`, `updateCells`). Without this a single user edit between two streaming ticks
   * would force a full O(n) rebuild on the next patch. No-op when the cache is already cold.
   */
  rebase(nextData: readonly unknown[]): void;
};

export function createRowIndexCache(): RowIndexCache {
  let cachedData: readonly unknown[] | null = null;
  let cachedMap: ReadonlyMap<string, number> | null = null;
  return {
    resolve(data, getRowId) {
      if (cachedMap && cachedData === data) return cachedMap;
      const map = new Map<string, number>();
      for (let i = 0; i < data.length; i++) map.set(getRowId(data[i], i), i);
      cachedData = data;
      cachedMap = map;
      return map;
    },
    invalidate() {
      cachedData = null;
      cachedMap = null;
    },
    rebase(nextData) {
      if (cachedMap) cachedData = nextData;
    },
  };
}

/**
 * Rebuilds the map from scratch and compares it against `cached`, returning the mismatching row ids.
 * Dev-only assertion surface for the invalidation invariant: a missed invalidation lands patches
 * on the wrong rows, a silent data-corruption class of bug.
 */
export function diffRowIndex(
  cached: ReadonlyMap<string, number>,
  data: readonly unknown[],
  getRowId: (row: unknown, index: number) => string,
): string[] {
  const mismatches: string[] = [];
  const seen = new Set<string>();
  for (let i = 0; i < data.length; i++) {
    const rowId = getRowId(data[i], i);
    seen.add(rowId);
    if (cached.get(rowId) !== i) mismatches.push(rowId);
  }
  for (const rowId of cached.keys()) {
    if (!seen.has(rowId)) mismatches.push(rowId);
  }
  return mismatches;
}

/**
 * Resolves `reorder` to what the store must actually do this tick. `"defer"` downgrades to `"never"`
 * when no touched column feeds the active sort or filter, so a ticker streaming into a
 * non-sort column never flips `viewStale` and never needs a reconcile (design spec §3.4).
 */
export function resolveReorder(
  requested: UpdateCellsOptions["reorder"],
  patches: readonly CellPatch[],
  sortState: readonly SortSpec[],
  filterState: readonly FilterSpec[],
): "defer" | "immediate" | "never" {
  const mode = requested ?? "defer";
  if (mode !== "defer") return mode;
  return touchesViewInputs(patches, sortState, filterState) ? "defer" : "never";
}

/** True when any patch writes a column that the active sort or filter reads. */
export function touchesViewInputs(
  patches: readonly CellPatch[],
  sortState: readonly SortSpec[],
  filterState: readonly FilterSpec[],
): boolean {
  if (sortState.length === 0 && filterState.length === 0) return false;
  const viewColumns = new Set<string>();
  for (const sort of sortState) viewColumns.add(sort.columnId);
  for (const filter of filterState) viewColumns.add(filter.columnId);
  for (const patch of patches) {
    if (viewColumns.has(patch.columnId)) return true;
  }
  return false;
}

"use client";

import { createContext, use, useEffect, useRef, useState, type ReactNode } from "react";
import type { StoreApi } from "zustand/vanilla";
import { useStore } from "zustand";
import type { OverlayPlugin } from "../overlays";
import type { RowBandsSpec } from "../layout-context";
import { checkDevGuardrails, checkUnresolvableColumnTypes } from "./commit";
import { makeSelectionChangeDetails } from "./compute";
import { createDataGridStore } from "./create-store";
import { toInternalSyncProps } from "./types";
import type { AnyColumnDef, DataGridProviderProps, DataGridStoreState } from "./types";
import { isSelectionEmpty } from "../selection";

/**
 * Wires `onSelectionChange`: one `storeApi.subscribe` on `state.selection`'s identity, not a
 * per-action callback insertion — `selection` is replaced by ~15 different call sites (click,
 * extend, row/col select, edits shifting rows, `_syncProps` clamping out-of-view rows, etc.), and a
 * single subscription covers all of them without threading the callback through every one, and
 * without adding a React subscription in row/cell components (this runs entirely outside React).
 * Reads `onSelectionChange` fresh off the store on each fire so `_syncProps` updates to it apply
 * immediately, same as every other sync-prop callback. Returns the unsubscribe.
 */
function subscribeSelectionChange(store: StoreApi<DataGridStoreState>): () => void {
  return store.subscribe((state, prevState) => {
    if (state.selection === prevState.selection) return;
    // getValues() closes over store.getState (not this fire's `state`) so a call from inside the
    // handler always sees the current selection even if something re-entrantly changed it first.
    state.onSelectionChange?.(state.selection, makeSelectionChangeDetails(store.getState));
  });
}

function subscribeSelectionCleared(store: StoreApi<DataGridStoreState>): () => void {
  let wasEmpty = isSelectionEmpty(store.getState().selection);
  return store.subscribe((state, prevState) => {
    if (state.selection === prevState.selection) return;
    const empty = isSelectionEmpty(state.selection);
    if (empty && !wasEmpty) state.onSelectionCleared?.();
    wasEmpty = empty;
  });
}

const DataGridStoreContext = createContext<StoreApi<DataGridStoreState> | null>(null);

/**
 * Mounts one store instance per grid (multiple grids per page each get their
 * own instance) and keeps it in sync with the consumer's live props.
 *
 * Generic over the consumer's row type `TData` — pass real `ColumnDef<TData, TValue>[]`
 * and a real `getRowId` without an unsafe cast; the internal store stays row-agnostic.
 */
export function DataGridProvider<TData>(props: DataGridProviderProps<TData>): ReactNode {
  const {
    data,
    defaultData,
    columns,
    getRowId,
    onDataChange,
    validateRow,
    onUndo,
    onRedo,
    cellTypes,
    processCellForClipboard,
    processCellFromClipboard,
    processPaste,
    rowMarkers,
    enableRowSelection,
    enableColumnSelection,
    enableRangeSelection,
    enableMultiRange,
    enableColumnResize,
    enableColumnReorder,
    enableColumnPinning,
    headerClickBehavior,
    labels,
    createRow,
    duplicateRow,
    sortState,
    onSortChange,
    filterState,
    onFilterChange,
    joinOperator,
    onJoinOperatorChange,
    searchText,
    onSearchTextChange,
    overlayPlugins,
    rowBands,
    defaultColumnLayout,
    onColumnLayoutChange,
    onColumnResizing,
    onSelectionChange,
    onSelectionCleared,
    children,
  } = props;
  const internalInit = toInternalSyncProps({
    data,
    defaultData,
    columns,
    getRowId,
    onDataChange,
    validateRow,
    onUndo,
    onRedo,
    cellTypes,
    processCellForClipboard,
    processCellFromClipboard,
    processPaste,
    rowMarkers,
    enableRowSelection,
    enableColumnSelection,
    enableRangeSelection,
    enableMultiRange,
    enableColumnResize,
    enableColumnReorder,
    enableColumnPinning,
    headerClickBehavior,
    labels,
    createRow,
    duplicateRow,
    sortState,
    onSortChange,
    filterState,
    onFilterChange,
    joinOperator,
    onJoinOperatorChange,
    searchText,
    onSearchTextChange,
    overlayPlugins,
    rowBands,
    defaultColumnLayout,
    onColumnLayoutChange,
    onColumnResizing,
    onSelectionChange,
    onSelectionCleared,
  });
  const [store] = useState(() => createDataGridStore(internalInit));
  const prevColumns = useRef<readonly AnyColumnDef[] | undefined>(undefined);
  const prevData = useRef<readonly unknown[] | undefined>(undefined);
  const prevOverlayPlugins = useRef<readonly OverlayPlugin[] | undefined>(undefined);
  const prevRowBands = useRef<RowBandsSpec | undefined>(undefined);
  const warnedColumnTypes = useRef<Set<string>>(new Set());

  // One subscription per store instance, outside React's render path (see subscribeSelectionChange).
  useEffect(() => subscribeSelectionChange(store), [store]);
  useEffect(() => subscribeSelectionCleared(store), [store]);

  useEffect(() => {
    checkDevGuardrails(internalInit, prevColumns.current, prevData.current, prevOverlayPlugins.current, prevRowBands.current);
    checkUnresolvableColumnTypes(internalInit.columns, internalInit.cellTypes, warnedColumnTypes.current);
    prevColumns.current = internalInit.columns;
    prevData.current = internalInit.data;
    prevOverlayPlugins.current = internalInit.overlayPlugins;
    prevRowBands.current = internalInit.rowBands;
    store.getState().actions._syncProps(internalInit);
    // internalInit is a fresh cast object each render; depend on the raw props instead.
    // oxlint-disable-next-line react-hooks/exhaustive-deps
  }, [
    store,
    data,
    columns,
    getRowId,
    onDataChange,
    validateRow,
    onUndo,
    onRedo,
    cellTypes,
    processCellForClipboard,
    processCellFromClipboard,
    processPaste,
    rowMarkers,
    enableRowSelection,
    enableColumnSelection,
    enableRangeSelection,
    enableMultiRange,
    enableColumnResize,
    enableColumnReorder,
    enableColumnPinning,
    headerClickBehavior,
    labels,
    createRow,
    duplicateRow,
    sortState,
    onSortChange,
    filterState,
    onFilterChange,
    joinOperator,
    onJoinOperatorChange,
    searchText,
    onSearchTextChange,
    overlayPlugins,
    rowBands,
    onColumnLayoutChange,
    onColumnResizing,
    onSelectionChange,
    onSelectionCleared,
  ]);

  return <DataGridStoreContext.Provider value={store}>{children}</DataGridStoreContext.Provider>;
}

/** Resolves the current grid's store, throwing with a clear message outside the provider. */
function useDataGridStoreApiInternal(): StoreApi<DataGridStoreState> {
  const store = use(DataGridStoreContext);
  if (!store) {
    throw new Error("gridcn: this hook must be used inside a <DataGridProvider>.");
  }
  return store;
}

export function useDataGridStore<T>(selector: (state: DataGridStoreState) => T): T {
  return useStore(useDataGridStoreApiInternal(), selector);
}

/**
 * Escape hatch for internal engine components that need imperative `getState()`
 * access in event handlers. Not for consumer use.
 * @internal
 */
export function useDataGridStoreApi(): StoreApi<DataGridStoreState> {
  return useDataGridStoreApiInternal();
}

import type { ReactNode } from "react";
import type {
  CellCoord,
  CellType,
  ColumnDef,
  ColumnLayout,
  DataChange,
  FilterJoinOperator,
  FilterSpec,
  GridSelection,
  HeaderClickBehavior,
  Keymap,
  RowMarkersMode,
  SortSpec,
} from "../types";
import type { OverlayPlugin } from "../overlays";
import type { RowBandsSpec } from "../layout-context";
import type { DataGridLabels, DeepPartialLabels } from "../labels";
import type { SearchMatch } from "../sort-filter";
import type { ExtendDirection, SelectLineOptions } from "../selection";
import type { ColRange } from "../selection/selected-col-ranges-for-row";

/** Live props synced from the consumer's render into the store on every change, typed over the consumer's row shape. */
export type DataGridSyncProps<TData = unknown> = {
  /**
   * Controlled row array (React `value` semantics): the app owns it, and every mutation
   * (edit/paste/fill/delete/row-ops) only ever reaches it through `onDataChange` — the grid's own
   * display doesn't change until the next render supplies a new `data`. Mutually exclusive with
   * `defaultData`; when both are given, `data` wins (dev-mode warns once). Omit `data` and pass
   * `defaultData` instead for the uncontrolled mode.
   */
  data?: readonly TData[];
  /**
   * Uncontrolled row array (React `defaultValue` semantics): seeds the store ONCE at creation and
   * the store then OWNS it — every mutation applies internally with no app-side state required;
   * `onDataChange` still fires as an optional notification. Changing this prop on a later render is
   * ignored (uncontrolled, matching `<input defaultValue>`). Mutually exclusive with `data` — see
   * that prop's doc for precedence.
   */
  defaultData?: readonly TData[];
  // ColumnDef's 3rd param (TValidate) erases to `any`, not `unknown` — see AnyColumnDef's doc in
  // this file: `validate`'s function-or-schema union can't stay bivariant as a plain property, so
  // a defineColumns literal's narrow-TValue `validate` needs this documented widening to fit here.
  columns: readonly ColumnDefOf<TData>[];
  getRowId: (row: TData, index: number) => string;
  /** Fired once per user gesture with the next data array and an id-keyed delta batch. */
  onDataChange?: (next: readonly TData[], change: DataChange<TData>) => void;
  /**
   * Row-level cross-field validation, run once per touched row after a write gesture commits
   * (edit, paste, fill, delete-contents, updateCells/updateRows) — the row already has ALL of the
   * gesture's cells applied, so the verdict is independent of column order inside a paste. Return
   * `columnId -> message` to surface errors (they land in `cellErrors`, same display as server
   * errors), `null` when the row is fine. Values still commit either way. Not run on row
   * insert/duplicate/delete or on consumer `data` replacement. Sync only.
   */
  validateRow?: (row: TData, rowId: string) => Record<string, string> | null;
  /** Undo keymap action (mod+Z); the `data-grid-history` add-on plugs its `undo()` in here. */
  onUndo?: () => void;
  /** Redo keymap action (mod+Y / mod+shift+Z); the `data-grid-history` add-on plugs its `redo()` in here. */
  onRedo?: () => void;
  /**
   * Cell-type registry keyed by `ColumnDef.type`; defaults to the built-in registry. Providing a
   * registry REPLACES the built-ins, it is not merged over them: to extend the built-ins, spread
   * the exported `cellTypes` in (`cellTypes={{ ...cellTypes, myType }}`).
   */
  cellTypes?: Record<string, AnyCellType>;
  /** Overrides a cell's clipboard-copy text; falls back to the cell type's `toText`. */
  processCellForClipboard?: (value: unknown, ctx: ClipboardProcessCtx<TData>) => string;
  /** Overrides parsing pasted text into a cell value; falls back to the cell type's `fromText`. */
  processCellFromClipboard?: (text: string, ctx: ClipboardProcessCtx<TData>) => unknown;
  /** Runs on the parsed paste grid before it's applied; returning `false` vetoes the paste entirely. */
  processPaste?: (cells: string[][], target: CellCoord) => string[][] | false;
  /** Marker column mode; default 'none'. See {@link RowMarkersMode}. */
  rowMarkers?: RowMarkersMode;
  /** Whole-row selection channel gestures (marker click, Shift+Space); default true. */
  enableRowSelection?: boolean;
  /** Whole-column selection channel gestures (header click); default true. */
  enableColumnSelection?: boolean;
  /** Multi-cell rectangular range gestures (shift-click/drag, shift+arrow); false collapses to single-cell active only. Default true. */
  enableRangeSelection?: boolean;
  /** Ctrl/Cmd-click multi-range (rangeStack); false makes it behave as a plain click. Default true. */
  enableMultiRange?: boolean;
  /** Enables the header resize handle grid-wide; default true. Per-column `resizable: false` still wins. */
  enableColumnResize?: boolean;
  /** Enables drag-to-reorder columns grid-wide; default true. Per-column `reorderable: false` still wins. */
  enableColumnReorder?: boolean;
  /** Enables pin/unpin actions grid-wide; default true. Per-column `pinnable: false` still wins. */
  enableColumnPinning?: boolean;
  /** How a plain header click behaves; default 'select'. See {@link HeaderClickBehavior}. */
  headerClickBehavior?: HeaderClickBehavior;
  /** Partial i18n override, deep-merged over {@link DEFAULT_LABELS}; see {@link useDataGridLabels}. */
  labels?: DeepPartialLabels;
  /** Builds a new row for `insertRow`; absent makes `insertRow` a dev-warning no-op (duplicateRows/deleteRows don't need it). */
  createRow?: (index: number) => TData;
  /**
   * Builds a duplicated row's identity for `duplicateRows`: given the
   * source row and its new data index, returns the row to insert (with a distinct id, e.g. a fresh
   * UUID, so the copy's `getRowId()` never collides with its source's React key). Absent makes
   * `duplicateRows` a dev-warning no-op — mirrors `createRow`/`insertRow`.
   */
  duplicateRow?: (row: TData, index: number) => TData;
  /**
   * Controlled multi-sort spec. Standard controlled-input
   * semantics: omitted (undefined) keeps today's uncontrolled behavior — the store owns
   * `sortState`. Provided (even `[]`) makes this prop the source of truth every `_syncProps` sync
   * writes into the store; `onSortChange` still fires on every user-driven change (header click,
   * `setSorts`) either way, but in controlled mode the displayed order only moves once the prop
   * itself changes — a controlled grid whose consumer ignores the callback stays visually fixed.
   */
  sortState?: SortSpec[];
  /** Fires whenever the user (or `actions.toggleSort`/`setSorts`) would change the sort, controlled or not; see `sortState`. */
  onSortChange?: (next: SortSpec[]) => void;
  /** Controlled filter spec; same controlled/uncontrolled semantics as `sortState`. */
  filterState?: FilterSpec[];
  /** Fires whenever the user (or `actions.setFilters`) would change the filters, controlled or not; see `filterState`. */
  onFilterChange?: (next: FilterSpec[]) => void;
  /** Controlled join operator combining `filterState`'s rows; same controlled/uncontrolled semantics as `sortState`. Default `"and"`. */
  joinOperator?: FilterJoinOperator;
  /** Fires whenever the user (or `actions.setJoinOperator`) would change the join operator, controlled or not; see `joinOperator`. */
  onJoinOperatorChange?: (next: FilterJoinOperator) => void;
  /** Controlled quick-search text; same controlled/uncontrolled semantics as `sortState`. */
  searchText?: string;
  /** Fires whenever the user (or `actions.setSearch`) would change the search text, controlled or not; see `searchText`. */
  onSearchTextChange?: (next: string) => void;
  /**
   * Overlay-plugin registration: each plugin renders into the overlay layer
   * after the fill preview but before the local active-cell ring, receiving `OverlayPluginCtx`
   * (window-clamp + pin-zone helpers, layout vars). The `data-grid-presence` add-on is the
   * motivating consumer. Pass a stable array reference (e.g. module scope or `useMemo`) — same
   * dev-mode guardrail as `columns`/`getRowClassName`: an unstable identity here re-renders
   * `DataGridOverlays` every tick for nothing.
   */
  overlayPlugins?: readonly OverlayPlugin[];
  /**
   * Row-bands registration: a spec object so root.tsx can compute band heights/`aria-rowcount`
   * SYNCHRONOUSLY at first render (no SSR/first-paint layout shift) while the actual pinned-row
   * semantics live in the `data-grid-pinned-rows` add-on's `useDataGridPinnedRows()`. Same
   * dev-mode identity guardrail as `overlayPlugins` — pass a stable reference (the hook already
   * returns one).
   */
  rowBands?: RowBandsSpec;
  /**
   * Seeds `columnWidths`/`columnOrder`/`hiddenColumns`/per-column `pin` ONCE at store creation,
   * over the `columns` prop's own def defaults (`resolveColumnWidth` precedence: layout beats def).
   * Deliberately NOT a controlled prop — later changes to this value are ignored (uncontrolled-
   * with-events, PLAN events-state gap fix 1); pair it with `onColumnLayoutChange` to save/restore
   * a user's layout (e.g. to localStorage) without a fully-controlled overlay fighting the defs.
   */
  defaultColumnLayout?: ColumnLayout;
  /**
   * Fires once per committed column-layout change (resize drag release/autosize, reorder drop,
   * pin/unpin, show/hide) with the full current `ColumnLayout` snapshot — never per drag frame.
   * Fired from the store actions layer, no React-render dependency. See `defaultColumnLayout` for
   * the matching restore path.
   */
  onColumnLayoutChange?: (next: ColumnLayout) => void;
  /**
   * Fires on every committed selection change (click, extend step, range push, row/column/all
   * selection, clear) with the current `GridSelection` plus a lazy `details.getValues()` accessor.
   * A drag-extend gesture fires once per step (intended — the presence/broadcast use case wants
   * live updates, not just the final drop) — `getValues()` is a function, not a materialized array,
   * specifically so that hot path never pays for building a value matrix on steps nobody reads.
   */
  onSelectionChange?: (next: GridSelection, details: SelectionChangeDetails) => void;
  /**
   * Fired exactly once when the selection transitions from non-empty to empty, from ANY path
   * (outside-click, clearSelection, a cleared range, etc.). `onSelectionChange` also fires on that
   * transition (with an empty selection) — this is the dedicated signal for UI resets. Does not
   * fire when the selection is already empty.
   */
  onSelectionCleared?: () => void;
  /**
   * Fires on every live width write during a resize drag (`actions.setColumnWidth`, per drag
   * frame) — the in-progress counterpart to `onColumnLayoutChange`'s once-per-commit snapshot.
   * Fired from the store actions layer, no React-render dependency. Not called for the commit
   * itself (drag release/autosize) — pair with `onColumnLayoutChange` if you need that too.
   */
  onColumnResizing?: (columnId: string, width: number) => void;
};

/**
 * Second argument to `onSelectionChange` (PLAN events-state gap fix 2). `getValues()` reads the
 * CURRENT `selection.current.range` only — a multi-range selection (ctrl-click stack) is not
 * flattened or concatenated, matching clipboard copy's own "primary range only" scope
 * (`resolveCopyScope`) — call it once per range in `selection.current.rangeStack` yourself if you
 * need the others. Returns `[]` when there's no active range (row/column-channel-only selection,
 * or a clear). Deliberately lazy: built fresh from the store snapshot only when called, so a
 * consumer that ignores it (the common case) never pays for reading/allocating a value matrix on
 * every drag step.
 */
export type SelectionChangeDetails = {
  /** Raw cell VALUES (not clipboard text) over the primary range, view-row-major: `values[0][0]` is the range's top-left cell. */
  getValues: () => unknown[][];
  /** Row ids of every selected row, view order, across both the row channel (checkboxes) and any cell range. */
  getRowIds: () => string[];
};

// The store is generic-erased to TData = unknown past this boundary (InternalSyncProps below): one
// runtime engine serves every consumer's row type, and unknown (not never) keeps every ColumnDef
// function field (accessorFn/setValue/readOnly/validate) callable with the store's own `row: unknown`
// values with no cast needed — safe because a column and the row it's called with always came from
// the same consumer-typed `data` array passed in through DataGridSyncProps<TData>. This is also what
// useDataGridVisibleColumns/useDataGridAllColumns return, so a consumer building custom column UI can
// call those same fields without a cast either.
/** `DataGridSyncProps` cast to the store's internal row-agnostic shape; the one unsafe cast, applied once at the boundary. */
export type InternalSyncProps = DataGridSyncProps<unknown>;

/**
 * `ColumnDef` widened to the store's internal row-agnostic shape (see the erasure comment above).
 * `validate`'s own value type erases to `any` (the third param, not `unknown`) — a union of a
 * function and a non-callable Standard Schema can't stay bivariant as a plain property the way a
 * pure method-shorthand function could, so narrow-`TValue` columns need this one documented,
 * single-field cast to widen into this shared type (see types.ts's `ColumnDef.validate` doc).
 */
export type AnyColumnDef = ColumnDef<unknown, unknown, any>; // eslint-disable-line @typescript-eslint/no-explicit-any

/**
 * `ColumnDef<TData, unknown, any>` — the same TValidate-erased-to-`any` widening as `AnyColumnDef`
 * (see its doc comment), but keeping `TData` open for call sites that are still generic over the
 * consumer's row type (sync-prop declarations, the public `useDataGridVisibleColumns`/`useDataGridAllColumns`
 * hooks) rather than already erased to `unknown`. Named once here (was 10 verbatim repeats across
 * store.tsx/data-grid.tsx, each with its own eslint-disable) so the widening reason lives in one place.
 */
export type ColumnDefOf<TData> = ColumnDef<TData, unknown, any>; // eslint-disable-line @typescript-eslint/no-explicit-any

/** `processCellForClipboard`/`processCellFromClipboard`'s callback context — named since it repeats identically across both callbacks in both `DataGridSyncProps` and `DataGridProps`. */
export type ClipboardProcessCtx<TData> = { row: TData; column: ColumnDefOf<TData> };

/**
 * `CellType<any, any, any>` — the `cellTypes` registry-prop widening (same single-point `any`
 * erasure as {@link AnyColumnDef}): `Cell`/`Editor` are `FC<...>` (strictly contravariant in their
 * props), so without erasing TData/TValue/TOptions neither the built-ins (concrete TValue) nor a
 * consumer's per-column `CellType<TData, TValue, TOptions>` is cast-free assignable to an
 * erased-to-`unknown` entry type — the registry prop is the one place a spread of the exported
 * `cellTypes` plus a custom type must compile with no cast.
 */
export type AnyCellType = CellType<any, any, any>; // eslint-disable-line @typescript-eslint/no-explicit-any

export function toInternalSyncProps<TData>(props: DataGridSyncProps<TData>): InternalSyncProps {
  return props as unknown as InternalSyncProps;
}

/** Options passed to selectRow/selectColumn actions; mirrors lib/selection's SelectLineOptions. */
export type SelectLineActionOptions = Omit<SelectLineOptions, "from">;

/**
 * One targeted cell write for {@link DataGridActions.updateCells}, addressed by STABLE ROW ID —
 * never a view or data index. A streaming producer cannot know view coordinates under an active
 * sort, and row ids are already what {@link DataOp} uses, so history survives sort/filter.
 */
export type CellPatch = {
  /** The row's `getRowId()` value. An id not present in `data` is skipped. */
  rowId: string;
  /** Any column id, including a hidden one. An unknown id is skipped. */
  columnId: string;
  value: unknown;
};

/** One whole-row update for {@link DataGridActions.updateRows}: a partial row shallow-merged per column id. */
export type RowPatch = {
  rowId: string;
  /** Column id -> new value. Each entry is applied exactly as the matching {@link CellPatch} would be. */
  changes: Readonly<Record<string, unknown>>;
};

/** How a `updateCells`/`updateRows` batch reconciles with an active sort or filter. */
export type UpdateCellsReorder = "defer" | "immediate" | "never";

/** One rowId+columnId target, addressed the same STABLE-ROW-ID way as {@link CellPatch} (no `value` — used only to name a cell for {@link DataGridActions.setCellErrors}/{@link DataGridActions.clearCellErrors}). */
export type CellErrorTarget = {
  /** The row's `getRowId()` value. An id not present in `data` is stored/cleared anyway (see `cellErrors`' doc) and simply never renders. */
  rowId: string;
  columnId: string;
};

/** One entry for {@link DataGridActions.setCellErrors}: the target cell plus its rejection message. */
export type CellErrorEntry = CellErrorTarget & { message: string };

/** Options for {@link DataGridActions.updateCells} and {@link DataGridActions.updateRows}. */
export type UpdateCellsOptions = {
  /**
   * Default `"defer"`.
   * - `"defer"` — values update in place and rows keep their view position; `viewStale` flips.
   *   The view reconciles on the next sort/filter/search change, or on `reconcileView()`. A
   *   `"defer"` batch that touches no active sort or filter column downgrades to `"never"`
   *   automatically, so `viewStale` never flips for a ticker on a non-sort column.
   * - `"immediate"` — moves the patched rows to their new positions now, by removing each one,
   *   re-testing filter membership, and binary-searching it back in under the same comparator chain
   *   a full sort uses. Cost scales with the batch size, not the row count: measured 0.3 / 0.9 /
   *   7.6 ms for 1 / 20 / 256 patched rows at 100k. Batches over
   *   {@link INCREMENTAL_PATCH_LIMIT} rows, a same-tick sort/filter change, or a column with its own
   *   comparator fall back to the full O(n log n) rebuild.
   * - `"never"` — updates in place and never marks the view stale. The caller asserts that no
   *   touched column feeds the sort or filter.
   */
  reorder?: UpdateCellsReorder;
  /** `DataChange` source tag; default `"stream"`. Pass `"edit"` to make the batch undoable. */
  source?: DataChange<unknown>["source"];
  /** Skips each column's `validate`. Default `false`. */
  skipValidation?: boolean;
};

/** Full per-grid interaction + derived state; internally typed over `unknown` rows. */
export type DataGridStoreState = Omit<
  InternalSyncProps,
  | "data"
  | "defaultData"
  | "cellTypes"
  | "rowMarkers"
  | "enableRowSelection"
  | "enableColumnSelection"
  | "enableRangeSelection"
  | "enableMultiRange"
  | "enableColumnResize"
  | "enableColumnReorder"
  | "enableColumnPinning"
  | "headerClickBehavior"
  | "labels"
  | "overlayPlugins"
  | "rowBands"
  | "defaultColumnLayout"
> & {
  /** Always defined: controlled mode mirrors the `data` prop every sync; uncontrolled mode seeds from `defaultData` once and the store owns it thereafter (mutated in place by the commit actions). */
  data: readonly unknown[];
  /** Whether `data` is controlled (the `data` prop was defined on the last `_syncProps`/init) — see `data`'s doc comment and `defaultData`. Mirrors the `sortControlled`-style pattern below. */
  dataControlled: boolean;
  /** Row-agnostic view of the cell-type registry; the `never`-typed sync prop is widened once at the store boundary. */
  cellTypes: Record<string, CellType>;
  /** Defaulted (never undefined) — see `resolveSelectionConfig`. */
  rowMarkers: RowMarkersMode;
  enableRowSelection: boolean;
  enableColumnSelection: boolean;
  enableRangeSelection: boolean;
  enableMultiRange: boolean;
  enableColumnResize: boolean;
  enableColumnReorder: boolean;
  enableColumnPinning: boolean;
  headerClickBehavior: HeaderClickBehavior;
  activeCell: CellCoord | null;
  selection: GridSelection;
  /**
   * Two-stage Ctrl+A progression (select-all-progression.ts): which stage the last `selectAll`
   * produced, plus the exact `selection`/`activeCell` object identities it produced them against.
   * Any other action that replaces `selection` or `activeCell` (selectCell/extendTo/pushRange/
   * selectRow/selectColumn/_moveActiveCell/edits/row ops) changes that identity, so `selectAll`
   * detects the mismatch and restarts from stage 1 — no need to instrument every reset site.
   */
  selectAllStage: { stage: "region" | "all"; selection: GridSelection; activeCell: CellCoord | null } | null;
  editing: { coord: CellCoord; initialText?: string } | null;
  /** Transient rejection message from the last failed commitCellEdit; cleared on the next startEditing/commit/cancel. */
  editingError: string | null;
  /**
   * Rejection nonce for the current edit session: increments on every rejected commit attempt
   * (the sync `validate` rejection in `commitCellEdit`, or an async schema resolving with issues
   * via `setEditingError`) and resets to 0 on `startEditing`. Editors re-arm their one-shot commit
   * guard when this changes: a REJECTION is the only signal that the edit is still open and a
   * fresh commit attempt is expected, never "pending cleared", which also happens on
   * Escape/cancel right before the editor unmounts. The store is the single source of truth for
   * both rejection paths.
   */
  editingRejectionCount: number;
  /**
   * Post-commit server-rejection messages, keyed `"rowId:columnId"` — set via
   * `actions.setCellErrors` after an async `onDataChange` round-trip rejects (e.g. a 422), painted
   * with the SAME visual language as a sync `validate` rejection (ring/tint + message,
   * `aria-invalid`). Deliberately NOT part of the edit lifecycle: `setCellErrors`/`clearCellErrors`
   * never touch `data`, never emit a `DataChange`/`onDataChange`, and are excluded from history —
   * this is metadata ABOUT a cell, not a data change. Auto-cleared for a cell the instant ANY write
   * path (`commitCellEdit`, `commitCellValue`, `applyCellUpdates`, `updateCells`, `deleteSelection`)
   * successfully commits a new value there — the user fixed it, so the stale error must not linger;
   * the server can always re-set it if the fix is still wrong. Pruned of any rowId no longer present
   * in `data` on every row-shape change (delete/duplicate/insert/a consumer `data` replacement) —
   * same maintenance discipline as `RowIndexCache`. Always {@link EMPTY_CELL_ERRORS} when empty, so
   * `useDataGridCellErrors`-style reads never allocate on the common no-error path.
   */
  cellErrors: ReadonlyMap<string, string>;
  /** Always defined: defaults to {@link EMPTY_OVERLAY_PLUGINS} so `useDataGridOverlayPlugins` never returns undefined. See `overlayPlugins`'s doc comment (DataGridSyncProps). */
  overlayPlugins: readonly OverlayPlugin[];
  /** Always defined: defaults to {@link EMPTY_ROW_BANDS} (zero-length top/bottom, `render` never called) so `useDataGridRowBands` never returns undefined. See `rowBands`'s doc comment (DataGridSyncProps). */
  rowBands: RowBandsSpec;
  lastHighlightedRow: number | null;
  lastHighlightedCol: number | null;
  columnWidths: Record<string, number>;
  /** null = follow the `columns` prop order. */
  columnOrder: string[] | null;
  hiddenColumns: readonly string[];
  sortState: SortSpec[];
  filterState: FilterSpec[];
  /** How `filterState`'s rows combine; default `"and"`. See `FilterJoinOperator`. */
  joinOperator: FilterJoinOperator;
  /** Quick-search text; never affects `viewIndex` (search highlights + navigates, it doesn't filter). */
  searchText: string;
  /**
   * Whether `sortState`/`filterState`/`joinOperator`/`searchText` are controlled (their sync prop
   * was defined on the last `_syncProps`), set once per sync and read by `toggleSort`/`setSorts`/
   * `setFilters`/`setJoinOperator`/`setSearch` (server escape hatch). Controlled mode:
   * the action still fires its `onXChange` callback but does NOT write the corresponding state
   * field itself — `_syncProps` is the only writer once the consumer's prop (and thus the store)
   * actually changes, standard controlled-input semantics (a callback-ignoring consumer's grid
   * stays visually fixed).
   */
  sortControlled: boolean;
  filterControlled: boolean;
  joinOperatorControlled: boolean;
  searchControlled: boolean;
  /** Every cell matching `searchText`, view-space row-major order; computed once per `setSearch`/`_syncProps`/`setSorts`/`setFilters`, capped at 1000 hits with early exit. */
  searchMatches: SearchMatch[];
  /** `searchMatches` as a `"${viewRow}:${columnId}"` Set for O(1) per-cell highlight lookup ({@link useDataGridIsSearchMatch}). */
  searchMatchSet: ReadonlySet<string>;
  /**
   * `searchMatches` grouped by view row -> matched column indices, for {@link computeRowCellState}'s
   * per-row derivation (perf audit 2026-07-17: the previous per-row `for` loop over every visible
   * column, each doing a `searchMatchSet.has(`${row}:${columnId}`)` string-key lookup, cost ~44ms/2000
   * ticks at 100k rows/8 cols with an active search — measured 29x faster building this map once per
   * search-text change and doing an O(1) `Map.get` per row per tick instead).
   */
  searchMatchRows: ReadonlyMap<number, ReadonlySet<number>>;
  /** True when `searchMatches` hit the 1000-match cap (more matches exist but weren't collected). */
  searchMatchesCapped: boolean;
  /** Recomputed by _syncProps/toggleSort/setSorts/setFilters only — search no longer affects it. */
  viewIndex: number[];
  /**
   * True when at least one deferred `updateCells`/`updateRows` batch changed a value that the active
   * sort or filter reads, so the displayed order no longer matches the data. Drives a "re-sort"
   * affordance; `reconcileView()` (or any sort/filter/search change) clears it. See
   * {@link useDataGridViewStale}.
   */
  viewStale: boolean;
  /** Recomputed by _syncProps/setColumnOrder-ish actions that touch order/visibility. */
  visibleColumns: readonly AnyColumnDef[];
  /**
   * Imperative scroll-into-view, registered by the mounted `DataGridRoot` (null before mount/after
   * unmount). Lets add-ons outside the root's subtree (e.g. `data-grid-toolbar`'s search, which sits
   * as a `DataGridRoot` sibling) move the viewport without reaching into
   * root-internal refs. See {@link useDataGridScrollToCell}.
   */
  scrollToCellImpl: ((coord: CellCoord) => void) | null;
  /**
   * Fill-handle keymap handlers, registered by the `data-grid-fill` add-on's tracker
   * component — which must render somewhere inside `DataGridRoot`'s subtree to reach `scrollRef`/
   * layout via `useDataGridRootContext()`, a level `DataGridRoot`'s OWN `useGridInteraction` call
   * (which needs these three callbacks) sits above. Registering through the store the same way
   * `scrollToCellImpl` does resolves that ordering: `DataGridRoot` reads this slot and forwards it
   * to `useGridInteraction` on every render; `null` (pre-mount, post-unmount, or add-on absent)
   * makes mod+D/mod+R/Escape-mid-drag the documented no-ops.
   */
  fillHandlers: { fillDown: () => void; fillRight: () => void; cancelFillDrag: () => void } | null;
  /**
   * Mirrors `DataGridRoot`'s `readOnly` prop, registered on mount, so
   * mutation surfaces outside the root's subtree (context menu, `useDataGridClipboard`) can see it
   * too — the root prop alone only reached its own local `useGridInteraction`/`useGridClipboard`.
   * `false` before mount/after unmount.
   */
  readOnly: boolean;
  /**
   * Mirrors `DataGridRoot`'s effective keymap — `DEFAULT_KEYMAP` merged with its `keymap` prop —
   * registered on mount (backing the `data-grid-keybindings` add-on) so surfaces outside
   * the root's subtree (e.g. the keybindings dialog) can read the single source of truth for
   * bindings instead of re-deriving it. `DEFAULT_KEYMAP` before mount/after unmount.
   */
  keymap: Keymap;
  /** {@link DEFAULT_LABELS} deep-merged with the `labels` sync prop; see {@link useDataGridLabels}. */
  labels: DataGridLabels;
  actions: DataGridActions;
};

/** Mutations for a single grid instance, nested under the stable `actions` key. */
export type DataGridActions = {
  /**
   * Moves ONLY the active cell, leaving the selection (range, row and column channels) untouched,
   * and fires NO `onSelectionChange` (contrast `selectCell`, which sets a single-cell selection
   * and fires it). After Escape/`clearSelection`, `selection.current` is `null` while `activeCell`
   * still exists — read the active cell from `activeCell`, not from `selection.current.cell`.
   */
  setActiveCell(coord: CellCoord | null): void;
  selectCell(coord: CellCoord): void;
  extendTo(coord: CellCoord): void;
  extendSelection(direction: ExtendDirection, opts?: { toEdge?: boolean }): void;
  pushRange(coord: CellCoord): void;
  selectRow(index: number, opts?: SelectLineActionOptions): void;
  selectColumn(index: number, opts?: SelectLineActionOptions): void;
  selectAll(): void;
  /** Checkbox marker: sets one row's membership in the rows channel absolutely (add if `checked`, remove otherwise) — never a toggle — independent of the last-highlighted/range mechanics `selectRow` uses for click gestures. No-op when `enableRowSelection` is false. */
  setRowSelected(index: number, checked: boolean): void;
  /** Sets the row-drag anchor without touching the rows/columns selection channel — lets a checkbox-marker press arm a potential row-range drag while leaving a stationary click's own toggle untouched. No-op when `enableRowSelection` is false. */
  armRowDragAnchor(index: number): void;
  /** Header marker select-all checkbox: sets every view row's membership in the rows channel at once. No-op when `enableRowSelection` is false. */
  setAllRowsSelected(checked: boolean): void;
  clearSelection(): void;
  /** Live per-frame width write during a resize drag; fires `onColumnResizing` (not `onColumnLayoutChange` — see `commitColumnWidth` for the commit point). */
  setColumnWidth(id: string, width: number): void;
  /** Sets the column's width AND fires `onColumnLayoutChange` once — the resize-drag-release/autosize commit point. */
  commitColumnWidth(id: string, width: number): void;
  /**
   * Reorders visible columns. `id` moves to sit immediately before/after `targetId` (per `position`).
   * Pinned columns only reorder within their own pin zone (left/right/unpinned) — a cross-zone
   * request is a no-op recompute (dropping a left-pinned column onto the unpinned band does nothing).
   * No-op when the column's own `reorderable: false` or the grid-wide `enableColumnReorder` is false.
   * Fires `onColumnLayoutChange` once on an actual move.
   */
  setColumnOrder(id: string, targetId: string, position: "before" | "after"): void;
  /** Pins/unpins a column (`null` = unpinned). No-op when the column's `pinnable: false` or grid-wide `enableColumnPinning` is false. Fires `onColumnLayoutChange` once. */
  setColumnPin(id: string, pin: "left" | "right" | null): void;
  /** Shows/hides a column via the `hiddenColumns` set. Fires `onColumnLayoutChange` once. */
  setColumnHidden(id: string, hidden: boolean): void;
  toggleSort(columnId: string, additive: boolean): void;
  setSorts(sorts: SortSpec[]): void;
  setFilters(filters: FilterSpec[]): void;
  /** Sets how `filterState`'s rows combine ("and" every filter must match, "or" any one does). */
  setJoinOperator(joinOperator: FilterJoinOperator): void;
  /** Sets quick-search text and recomputes `searchMatches`/`searchMatchSet`/`searchMatchesCapped` once; never touches `viewIndex`. */
  setSearch(text: string): void;
  /** Enters edit mode at `coord` (view-space); no-op when the column is readOnly or its type is unregistered. */
  startEditing(coord: CellCoord, initialText?: string): void;
  /** Discards the in-progress edit without emitting a change. */
  cancelEditing(): void;
  /** Validates and commits the in-progress edit; rejects (keeps editing, sets editingError) or emits one DataChange and moves activeCell by `movement`. */
  commitCellEdit(value: unknown, movement?: { dx: number; dy: number }): void;
  /** Direct-write path for types with no edit mode (checkbox): validates and commits `value` at `coord` without requiring `startEditing` first, and never moves the active cell. */
  commitCellValue(coord: CellCoord, value: unknown): void;
  /**
   * Sets `editingError` and bumps `editingRejectionCount` (the editors' commit-guard re-arm
   * nonce) without touching `editing`/`data` — used by the async Standard Schema commit path (see
   * cell.tsx/use-async-validate.ts): an async `validate` resolves AFTER `commitCellEdit` would
   * have run, so the editor-commit layer calls this directly instead of going through the
   * (synchronous) commit action. No-op if editing has since ended (race guard is the caller's
   * job — see the generation counter in use-async-validate.ts).
   */
  setEditingError(message: string): void;
  /**
   * Merges `errors` into `cellErrors` per-key (an existing entry for a cell not named here
   * survives untouched). NOT a data change: no `DataChange`, no history entry, no `onDataChange`
   * echo — see `cellErrors`' doc comment. The typical caller is an `onDataChange` handler's
   * `.catch()` after a server 422, mapping its field errors to `{ rowId, columnId, message }[]`.
   */
  setCellErrors(errors: readonly CellErrorEntry[]): void;
  /** Clears `cellErrors` for `targets`, or every entry when `targets` is omitted. Same non-data-change contract as `setCellErrors`. */
  clearCellErrors(targets?: readonly CellErrorTarget[]): void;
  /** Clears every non-readOnly cell in the current selection to its type's clearValue(), as one batch DataChange. */
  deleteSelection(): void;
  /**
   * The one generic multi-cell write path: applies `updates` (view-space coords via `viewRow`) as
   * a single `source`-tagged DataChange batch. Dedupes multiple updates to the same row/column
   * (last write wins), skips readOnly cells and no-op writes, preserves identity of untouched rows,
   * suppresses an empty batch entirely, and moves the selection to cover the touched view rect.
   */
  applyCellUpdates(updates: { viewRow: number; columnId: string; value: unknown }[], source: DataChange<unknown>["source"]): void;
  /**
   * The streaming write path: applies id-keyed {@link CellPatch}es in ONE `set()` and skips the
   * `computeViewIndex`/`computeSearchMatches` rebuild that a `data` prop replacement forces. This is
   * what makes streaming under an active sort viable — a controlled `data` replacement costs ~56 ms
   * per tick at 100k rows with one sort column, against ~0.15 ms here.
   *
   * Unlike `applyCellUpdates` it never moves the selection, the active cell, or the editing session,
   * so a live feed cannot pull the grid out from under a user mid-edit. Emits one batched
   * `{source: "stream"}` `DataChange` through `onDataChange`, in both controlled and uncontrolled
   * mode. See {@link UpdateCellsOptions} for the sort/filter interaction.
   */
  updateCells(patches: readonly CellPatch[], options?: UpdateCellsOptions): void;
  /** {@link updateCells} keyed by whole row: each {@link RowPatch}'s `changes` expands to one patch per column id. */
  updateRows(updates: readonly RowPatch[], options?: UpdateCellsOptions): void;
  /** Rebuilds the view index that a deferred `updateCells` postponed, and clears `viewStale`. No-op when the view is not stale. */
  reconcileView(): void;
  /**
   * Inserts one row built by the `createRow` sync prop above/below `viewRowIndex` (view-space).
   * External name that maps to the single internal batch path - it runs
   * {@link insertRows} with count 1, so both share one implementation, one `onDataChange`,
   * and one undo step.
   */
  insertRow(viewRowIndex: number, position: "above" | "below"): void;
  /**
   * Inserts `count` rows built by the `createRow` sync prop (called with `dataRowIndex + i`)
   * above/below `viewRowIndex` (view-space) as ONE `{source: 'row-op'}` DataChange with one
   * id-keyed `insert` op per row - a single undo entry. Dev-warning no-op when `createRow` is
   * absent; silent no-op for `count <= 0`.
   */
  insertRows(viewRowIndex: number, count: number, position?: "above" | "below"): void;
  /** Deletes the rows at `viewRowIndexes` (view-space) as one `{source: 'row-op'}` DataChange with id-keyed `delete` ops. */
  deleteRows(viewRowIndexes: number[]): void;
  /**
   * Duplicates the rows at `viewRowIndexes` (view-space), inserting each copy directly after its
   * source row, as one `{source: 'row-op'}` DataChange with id-keyed `insert` ops. Dev-warning
   * no-op when the `duplicateRow` sync prop is absent — required so
   * every duplicated row gets a distinct id, never colliding with its source's React key.
   */
  duplicateRows(viewRowIndexes: number[]): void;
  /** @internal keyboard nav helper: moves/extends the active cell by a view-space delta, clamped to view bounds. */
  _moveActiveCell(d: { dx: number; dy: number }, opts?: { extend?: boolean; retain?: boolean }): void;
  /** @internal syncs live consumer props and recomputes derived state; not part of the public hook surface. */
  _syncProps(props: InternalSyncProps): void;
  /** @internal `DataGridRoot` registers/clears its scroll-into-view on mount/unmount; not part of the public hook surface. */
  _registerScrollToCell(impl: ((coord: CellCoord) => void) | null): void;
  /** @internal `DataGridRoot` syncs its `readOnly` prop into the store on every render/unmount; not part of the public hook surface. */
  _registerReadOnly(readOnly: boolean): void;
  /** @internal `DataGridRoot` syncs its effective (merged) keymap into the store on every render/unmount; not part of the public hook surface. */
  _registerKeymap(keymap: Keymap): void;
  /** @internal the `data-grid-fill` add-on's tracker component registers/clears its keymap handlers on mount/unmount; not part of the public hook surface. */
  _registerFillHandlers(handlers: { fillDown: () => void; fillRight: () => void; cancelFillDrag: () => void } | null): void;
};

/** Full store shape: interaction state + the stable actions object. */
export type DataGridStore = DataGridStoreState;

/**
 * Everything `computeViewIndex`/`computeSearchMatches`/`computeVisibleColumns` read on a
 * `_syncProps` sync, captured by reference. All fields `===`-equal to the previous sync's means
 * their outputs (`viewIndex`/`searchMatches`/`visibleColumns`) are also unchanged, so `_syncProps`
 * can skip recomputing them and reuse the previous references (a controlled parent re-rendering
 * for unrelated reasons — e.g. its own local state — shouldn't pay full buildViewIndex cost).
 */
export type SyncInputs = {
  data: readonly unknown[];
  columns: readonly AnyColumnDef[];
  /** Sort reads each column's cell-type `compare`, so a swapped registry changes `viewIndex`. */
  cellTypes: Record<string, CellType>;
  sortState: SortSpec[];
  filterState: FilterSpec[];
  joinOperator: FilterJoinOperator;
  searchText: string;
  columnOrder: string[] | null;
  hiddenColumns: readonly string[];
};

export function syncInputsEqual(a: SyncInputs, b: SyncInputs): boolean {
  return (
    a.data === b.data &&
    a.columns === b.columns &&
    a.cellTypes === b.cellTypes &&
    a.sortState === b.sortState &&
    a.filterState === b.filterState &&
    a.joinOperator === b.joinOperator &&
    a.searchText === b.searchText &&
    a.columnOrder === b.columnOrder &&
    a.hiddenColumns === b.hiddenColumns
  );
}

/** Result of a successful direct-write commit; `null` state fields mean "leave editing/editingError untouched". */
export type CommitResult = { data: readonly unknown[]; change: DataChange<unknown> } | { error: string } | { noop: true };

/** Per-row accumulator: the row as edited so far, plus its per-column cell deltas (columnId -> entry). */
export type RowEdit = { row: unknown; cells: Map<string, { columnId: string; value: unknown; prev: unknown }> };

/** Props for {@link DataGridProvider}. */
export type DataGridProviderProps<TData = unknown> = DataGridSyncProps<TData> & { children: ReactNode };

/** {@link useDataGridCellState}'s return shape — the 5 primitives `DataGridCell` reads every render. */
export type DataGridCellState = {
  isActive: boolean;
  /** True for any selected cell (active cell, inside the primary range/range stack, or its row/column channel) — drives `aria-selected` (WAI-ARIA grid pattern: every selected cell reports it, not just the focused one). */
  isSelected: boolean;
  isEditing: boolean;
  initialText: string | undefined;
  isSearchMatch: boolean;
  /** This cell's `cellErrors` message, or null when it has none — same visual language as a sync `validate` rejection. */
  cellError: string | null;
};

/**
 * {@link useDataGridRowCellState}'s return shape — one row's worth of interactive cell state,
 * derived ONCE per row instead of once per cell. `selectedColRanges` is a rectangle-based summary
 * (a row's selected columns are a small union of `[start,end)` runs), so it stays cheap to compute
 * and to compare by content.
 */
export type DataGridRowCellState = {
  /** The active cell's column in this row, or null if the active cell isn't in this row. */
  activeCol: number | null;
  /** The editing cell's column in this row, or null if editing isn't happening in this row. */
  editingCol: number | null;
  /** Only set when `editingCol` is non-null (mirrors {@link useDataGridCellInitialText}'s per-cell scoping). */
  editingInitialText: string | undefined;
  /** Every column index in this row matching the current search, or null when search is inactive/no row match — null (not an empty Set) lets a row with no matches skip allocating one. */
  searchMatchCols: ReadonlySet<number> | null;
  /** This row's errored columns (column index -> message), or null when this row has none — same zero-render contract as `searchMatchCols`. */
  errorCols: ReadonlyMap<number, string> | null;
  selectedColRanges: readonly ColRange[];
};

import type { FC, ReactNode } from "react";

/**
 * Vendored from `@standard-schema/spec` v1 (https://github.com/standard-schema/standard-schema) so
 * shipped registry code has zero runtime/type dependency on the package — the same choice TanStack
 * Form makes for the identical reason (references/form's standardSchemaValidator.ts). The spec is
 * frozen at version 1, so drift risk is ~nil; a type-level conformance test (data-grid.type-test.ts)
 * asserts this vendored copy stays assignable to/from the real package's type in both directions,
 * so any future drift fails `tsc` instead of silently diverging. `@standard-schema/spec` is still a
 * repo devDependency (types-only, for that conformance test) — never imported by shipped code.
 */
export type StandardSchemaV1<Input = unknown, Output = Input> = {
  /** The Standard Schema properties. */
  readonly "~standard": StandardSchemaV1Props<Input, Output>;
};

interface StandardSchemaV1Props<Input = unknown, Output = Input> {
  /** The version number of the standard. */
  readonly version: 1;
  /** The vendor name of the schema library. */
  readonly vendor: string;
  /** Validates unknown input values. */
  readonly validate: (value: unknown) => StandardSchemaV1Result<Output> | Promise<StandardSchemaV1Result<Output>>;
  /** Inferred types associated with the schema. */
  readonly types?: StandardSchemaV1Types<Input, Output> | undefined;
}

/** Result of one `"~standard".validate()` call: `issues` set means failure, never thrown. */
export type StandardSchemaV1Result<Output> = StandardSchemaV1SuccessResult<Output> | StandardSchemaV1FailureResult;

interface StandardSchemaV1SuccessResult<Output> {
  /** The typed output value. */
  readonly value: Output;
  /** A falsy value for `issues` indicates success. */
  readonly issues?: undefined;
}

interface StandardSchemaV1FailureResult {
  /** The issues of failed validation. */
  readonly issues: ReadonlyArray<StandardSchemaV1Issue>;
}

/** One validation failure; cell values are scalars so `path` (when present) is a flat dot-joined prefix. */
export interface StandardSchemaV1Issue {
  /** The error message of the issue. */
  readonly message: string;
  /** The path of the issue, if any. */
  readonly path?: ReadonlyArray<PropertyKey | StandardSchemaV1PathSegment> | undefined;
}

interface StandardSchemaV1PathSegment {
  /** The key representing a path segment. */
  readonly key: PropertyKey;
}

interface StandardSchemaV1Types<Input = unknown, Output = Input> {
  /** The input type of the schema. */
  readonly input: Input;
  /** The output type of the schema. */
  readonly output: Output;
}

// Namespace-merged onto the `StandardSchemaV1` type (matching the official package's own
// declaration, and how consumers write `StandardSchemaV1.InferInput<S>`) — not a general-purpose
// namespace, so the lint rule's usual "prefer ES modules" concern doesn't apply here.
// eslint-disable-next-line @typescript-eslint/no-namespace
export namespace StandardSchemaV1 {
  /** Infers the input type of a Standard Schema. */
  export type InferInput<Schema extends StandardSchemaV1> = NonNullable<Schema["~standard"]["types"]>["input"];
  /** Infers the output type of a Standard Schema. */
  export type InferOutput<Schema extends StandardSchemaV1> = NonNullable<Schema["~standard"]["types"]>["output"];
}

// `keyof TData & string` alone resolves to `never` (not `string`) when TData=unknown — unlike
// `never`, where `keyof never` is the universal key type `string | number | symbol` — so the
// erasure boundary's `ColumnDef<unknown, ...>` (see store.tsx's AnyColumnDef) needs this special
// case, else `accessorKey` collapses to an uninhabited `undefined` field.
export type AccessorKeyOf<TData> = unknown extends TData ? string : keyof TData & string;

/** Cell coordinate in data space: col/row are 0-based data indices (marker columns excluded). */
export type CellCoord = { col: number; row: number };

/**
 * Marker column mode: a pinned-left column rendered BEFORE all data columns, outside the data
 * column index space (CellCoord.col / aria-colindex / aria-colcount are all untouched by it).
 * `'number'` shows the 1-based view row index; `'checkbox'` drives the rows selection channel;
 * `'both'` shows the number, replaced by the checkbox on hover/selected (group-hover pattern).
 */
export type RowMarkersMode = "none" | "number" | "checkbox" | "both";

/** Rectangular cell region, half-open on the far edge (a cell c is inside if x <= c < x + width). */
export type GridRect = { x: number; y: number; width: number; height: number };

/**
 * Selection model (see research/glide-behavior-spec.md §1).
 * `cell` is the anchor (Excel's white cell) and is always inside `range`.
 * `rangeStack` holds additional rectangles from ctrl-click multi-range; never contains `range`.
 * `rows`/`columns` are whole-row/column selection channels, distinct from `current`.
 */
export type GridSelection = {
  current: {
    cell: CellCoord;
    range: GridRect;
    rangeStack: GridRect[];
  } | null;
  rows: CompactSelectionLike;
  columns: CompactSelectionLike;
};

/** Structural interface of CompactSelection so types.ts stays dependency-free. */
export type CompactSelectionLike = {
  readonly length: number;
  hasIndex(index: number): boolean;
  hasAll(range: [number, number]): boolean;
  toArray(): number[];
};

/**
 * Selection-gesture configuration (PLAN §3 "Selection configurability"). All default `true`.
 * Disabling a channel removes both its gestures (header/marker click, drag) AND its selection
 * channel: e.g. `enableColumnSelection: false` makes header clicks a no-op, not just un-rendered.
 */
export type SelectionConfig = {
  enableRowSelection: boolean;
  enableColumnSelection: boolean;
  enableRangeSelection: boolean;
  enableMultiRange: boolean;
};

/** One data mutation. Ops are id-keyed so history survives sort/filter (never index-keyed). */
export type DataOp<TData> =
  | {
      type: "update";
      rowId: string;
      row: TData;
      prev: TData;
      /** Per-cell detail when known (cell edits, paste, fill); absent for whole-row updates. */
      cells?: { columnId: string; value: unknown; prev: unknown }[];
    }
  | { type: "insert"; rowId: string; row: TData; index: number }
  | { type: "delete"; rowId: string; row: TData; index: number };

/** One user gesture = one batch (a paste, a fill, a delete-range is a single entry). */
export type DataChange<TData> = {
  ops: DataOp<TData>[];
  /**
   * Origin of the change, for history labeling and consumer filtering. `"stream"` tags a
   * `updateCells`/`updateRows` batch; `useDataGridHistory` drops it by default, because a
   * 100-updates/s feed would evict the user's whole undo stack in seconds. `"app"` tags an
   * imperative `record()` entry (a programmatic change the consumer applied itself).
   */
  source: "edit" | "paste" | "fill" | "delete" | "row-op" | "import" | "history" | "stream" | "app";
  /** Optional human-readable label for this entry (e.g. "Batch save rollback"); carried through the undo/redo stack as-is. */
  label?: string;
};

export type CellRenderProps<TData, TValue> = {
  /** The resolved cell value (through the column's `accessorKey`/`accessorFn`). */
  value: TValue;
  /** The full data row this cell belongs to. */
  row: TData;
  /** Display (view-space) row index: the sorted/filtered position, matching what the user sees. NOT a stable index into `data` — it reshuffles under sort and filter. Use `getRowId` for stable row identity. */
  rowIndex: number;
  // `column`'s own validate erases independently (3rd param `any`) — same reasoning as
  // CellClassNameCtx.column below; without it, renderCell's own bivariance gets re-poisoned by
  // validate's union whenever TValue is erased to `unknown` at the array-common-type boundary.
  column: ColumnDef<TData, TValue, any>; // eslint-disable-line @typescript-eslint/no-explicit-any
  /** True while this cell is the active cell. */
  isActive: boolean;
};

/** Context passed to the grid-level {@link ColumnDef}-agnostic `getCellClassName` prop. */
export type CellClassNameCtx<TData, TValue> = {
  value: TValue;
  row: TData;
  // `column`'s own validate erases independently (3rd param `any`) so THIS type's bivariance
  // (recovered via CellClassNameFnHolder below) doesn't get re-poisoned by validate's union when
  // TValue itself is erased to `unknown` at the array-common-type boundary — see types.ts's
  // ColumnDef.validate doc and store.tsx's AnyColumnDef doc for the full reasoning.
  column: ColumnDef<TData, TValue, any>; // eslint-disable-line @typescript-eslint/no-explicit-any
  /** Display (view-space) row index — the sorted/filtered position, matching what the user sees. */
  viewRowIndex: number;
};

/**
 * Grid-level row class callback (PLAN §6 "Programmatic style API"); merged via `cn()` after the
 * built-in row classes. `viewRowIndex` is the display (sorted/filtered) position. Pass a stable
 * function identity (module scope, or memoized) — like `columns`/`data`, its identity is a dev-mode
 * guardrail (unstable identity defeats row memoization) rather than a fresh per-render prop.
 */
export type GetRowClassName<TData> = (row: TData, viewRowIndex: number) => string | undefined;

/** Grid-level cell class callback; same stable-identity guidance as {@link GetRowClassName}. */
export type GetCellClassName<TData> = (ctx: CellClassNameCtx<TData, unknown>) => string | undefined;

/** Context passed to `onCellClick`. Same shape as {@link CellClassNameCtx} plus the column's real index (not just its view row). */
export type CellClickCtx<TData, TValue> = {
  value: TValue;
  row: TData;
  column: ColumnDef<TData, TValue>;
  /** Display (view-space) row index — matches {@link CellClassNameCtx.viewRowIndex}. */
  rowIndex: number;
  /** Data-column index (not the marker column) — matches `CellCoord.col`. */
  columnIndex: number;
};

/**
 * Fired on a plain click on any non-skeleton, non-pinned-row cell — attached to the cell's own
 * existing DOM click handler (no new subscription; see events-state.mdx). Fires alongside
 * whatever the click already does (select the cell, toggle a checkbox) — it's a pure
 * notification, never a veto point (contrast `onFillPattern`'s `preventDefault()`).
 */
export type OnCellClick<TData> = (ctx: CellClickCtx<TData, unknown>, event: MouseEvent) => void;

/** Context passed to `onRowClick` — the row is display-index only; map to a stable id via `getRowId` yourself if you need one. */
export type RowClickCtx<TData> = {
  row: TData;
  /** Display (view-space) row index — matches {@link CellClassNameCtx.viewRowIndex}. */
  rowIndex: number;
};

/** Same firing site as {@link OnCellClick}, once per click regardless of which column was clicked. */
export type OnRowClick<TData> = (ctx: RowClickCtx<TData>, event: MouseEvent) => void;

/**
 * Method-shorthand holder purely so {@link ColumnDef.cellClassName}'s function branch can pull its
 * signature via indexed access (`CellClassNameFnHolder<...>["fn"]`) instead of writing the function
 * type directly in the union — a function type embedded straight in a union property is checked
 * contravariantly, but one recovered from a method-shorthand declaration via indexed access keeps
 * that declaration's bivariant check, so a `defineColumns` literal's narrow `TValue`-specific
 * callback stays assignable to `ColumnDef<TData, unknown>` (see column-helpers.type-test.ts).
 */
type CellClassNameFnHolder<TData, TValue> = { fn(ctx: CellClassNameCtx<TData, TValue>): string | undefined };

/**
 * Editor contract, in order: the editor holds its own draft text; `onChange(value)` stashes the
 * CURRENT draft into the grid (this is the only way a value reaches the store); `commit()`
 * validates and applies whatever `onChange` last stashed, then closes the editor and moves the
 * active cell. Calling `commit()` without an `onChange` since the editor opened commits the OLD
 * value (the stash is seeded from it at editor-open, never from your local state); calling
 * `onChange` and never `commit` leaves the edit stranded. `cancel()` discards everything. The
 * built-in editors' `commitText(movement)` helper shows the canonical order: guard, `onChange`,
 * `commit`.
 */
export type CellEditorProps<TData, TValue> = {
  /** The last-COMMITTED value, as it was when the editor opened (seed for your initial draft). NOT your in-progress draft — that lives in your editor's local state. */
  value: TValue;
  /** Initial text seed when editing started by typing (type-to-replace); undefined for Enter/F2. */
  initialText?: string;
  /** The full data row this cell belongs to. */
  row: TData;
  // `column`'s own validate erases independently (3rd param `any`) — same reasoning as
  // CellRenderProps.column above.
  column: ColumnDef<TData, TValue, any>; // eslint-disable-line @typescript-eslint/no-explicit-any
  /** Stash the current draft. Takes effect on the next `commit` — it never writes the store by itself. */
  onChange: (value: TValue) => void;
  /** Validate and apply the last stashed value, close the editor, and move the active cell by the given delta (Enter = {0,1}, blur/click-away = {0,0}). */
  commit: (movement?: { dx: number; dy: number }) => void;
  /** Discard the edit without emitting a change. */
  cancel: () => void;
  /**
   * True while an async Standard Schema `validate` is awaiting its result for THIS commit attempt
   * (see interaction/use-async-validate.ts) — editing is still open. Built-in editors set their
   * input `readOnly` (not `disabled` — a disabled input can't receive Escape/blur) while pending;
   * a custom editor may ignore this or style it differently. Always `false`/`undefined` for the
   * function form and sync schemas.
   */
  pending?: boolean;
  /**
   * Increments on every rejected commit attempt (sync or async) for this cell, and resets to 0
   * when a new edit session starts. A built-in editor's own one-shot commit guard (see
   * interaction/use-commit-guard.ts) must re-arm on a REJECTION specifically — not on every
   * `pending` transition to false, which also happens on Escape/cancel right before the editor
   * unmounts; re-arming there would let the unmount's own blur event fire a second, stale commit
   * through the now-unguarded path.
   */
  rejectionCount?: number;
};

/**
 * A cell type implements rendering plus the value pipeline that powers copy, paste, fill,
 * delete, and import/export (see research/react-datasheet-grid-study.md §8). The pipelines read
 * the value through DIFFERENT surfaces, so one override does not reach all of them:
 *
 * - display (the cell's rendered text) = `toDisplayText` when present, else `toText`.
 * - clipboard copy and export = `toText`, always.
 * - sort = `compare` when the column declares this type, else a numeric-aware locale collation of
 *   the RAW `String(value)` — not of `toText` output.
 * - search and filter = `String(rawValue)`: the view pipeline is built WITHOUT cellTypes, so a
 *   custom `toText` never changes what search or filter see (a `select` column searches the
 *   stored VALUE, not the displayed label; a `number` with `decimals` searches the unrounded
 *   value; a `date` with a `displayFormat` matches the ISO string).
 * - fill (series inference) works on the raw value, not on any text form.
 */
export type CellType<TData = unknown, TValue = unknown, TOptions = unknown> = {
  Cell: FC<CellRenderProps<TData, TValue>>;
  Editor: FC<CellEditorProps<TData, TValue>>;
  /** Serialize for clipboard/export. Search and filter do NOT use this — they match on the raw `String(value)`. */
  toText(value: TValue, options?: TOptions): string;
  /** Optional display-only rendering (e.g. locale-formatted dates); the cell renders `toDisplayText ?? toText`. Clipboard/export always use `toText`. */
  toDisplayText?(value: TValue, options?: TOptions): string;
  /** Parse from paste/import/typing. Must never throw; return clearValue()'s result for garbage. */
  fromText(text: string, options?: TOptions): TValue;
  clearValue(options?: TOptions): TValue;
  isEmpty(value: TValue): boolean;
  /** Sort comparator for this type; when absent, sorting falls back to a numeric-aware locale collation of the raw `String(value)` — not of `toText` output. */
  compare?(a: TValue, b: TValue): number;
  align?: "left" | "right" | "center";
};

/**
 * `TValidate` defaults to `TValue` for normal authoring (nothing changes for consumers) but is a
 * SEPARATE type parameter so the store's erasure boundary (`AnyColumnDef`, `DataGridSyncProps.columns`)
 * can instantiate it independently as `any` (not `unknown` — proven necessary, see `validate`'s doc
 * below) while `TValue` (accessorFn/setValue/renderCell/etc.) keeps its real `unknown` erasure and
 * full type safety.
 */
export type ColumnDef<TData, TValue = unknown, TValidate = TValue> = {
  /** Stable identity — never derived from the header label. */
  id: string;
  /**
   * String headers render truncated and get the built-in sort-direction arrow in `sort`
   * header-click mode; a ReactNode header renders as-is and owns its own display (the built-in
   * arrow is NOT appended — embed DataGridSortIndicator inside it when you still want it).
   */
  header: string | ReactNode;
  /** Plain-text header for clipboard/export when `header` is a ReactNode. */
  headerText?: string;
  accessorKey?: AccessorKeyOf<TData>;
  /**
   * Read accessor for computed or derived values. A column with ONLY `accessorFn` (no
   * `accessorKey`/`setValue`) is read-only by construction: edits, pastes, and fills are dropped
   * for it. Pair it with `setValue` to make the computed value writable.
   */
  accessorFn?: (row: TData) => TValue;
  /** Immutable write-back; defaults to spreading `accessorKey`. Required for writability when `accessorKey` is absent. */
  setValue?(row: TData, value: TValue): TData;
  /** Cell type registry key; default "text". */
  type?: string;
  options?: unknown;
  readOnly?: boolean | ((row: TData) => boolean);
  /**
   * Rejects a value: the function form returns an error message (`null` accepts), or any
   * `StandardSchemaV1` for `TValue` (Zod/Valibot/ArkType/...) — detected at the call site via
   * `"~standard" in validate`. A schema's `validate` may resolve async; only the single-cell
   * editor commit path awaits it (see cell.tsx/use-commit-guard.ts), bulk paths (paste/fill/
   * import) treat a Promise result as unsupported and skip validation for that cell (dev warn).
   * On success the COMMITTED value is `result.value` (schemas may transform), documented in
   * editing-cell-types.mdx.
   * `TValidate` (not `TValue` directly): a union of a function type and a non-callable schema
   * object, as a plain property, is checked contravariantly as a WHOLE — unlike a pure
   * method-shorthand function, TS can't special-case just the function branch bivariant anymore.
   * That would break `defineColumns`' narrow-`TValue` columns widening into the shared
   * `ColumnDef<TData, unknown>` array every consumer prop uses (verified: it also cascades to
   * OTHER unrelated method-shorthand fields like `renderCell` in the same array literal — TS's
   * structural check on the whole object type gets stricter once ANY sibling property stops being
   * bivariant). Giving `validate` its own type parameter keeps that widening exact (`TValue` never
   * becomes incompatible) while only `TValidate` erases at the store boundary — a documented,
   * narrow, single-field cast (see `AnyColumnDef`), not a project-wide `any`.
   */
  validate?: ((value: TValidate, row: TData) => string | null) | StandardSchemaV1<TValidate>;
  width?: number;
  minWidth?: number;
  maxWidth?: number;
  /**
   * Proportional share of leftover viewport width. Columns with flex grow from their base
   * `width` to fill positive leftover space; clamped by `maxWidth`. A manual resize fixes the
   * column and removes it from flex distribution.
   */
  flex?: number;
  /** Initial pin direction; change it at runtime through `setColumnPin` or the context menu. Pinned columns only reorder within their own pin zone. */
  pin?: "left" | "right";
  /** Removes the column from click-to-sort (header clicks no longer sort it); programmatic `setSorts`/`toggleSort` still apply. Default true. */
  sortable?: boolean;
  /** Excludes the column from the filter menu's column picker. Existing filter specs on it keep applying. Default true. */
  filterable?: boolean;
  /** Initial visibility; toggle at runtime through `setColumnHidden` or the columns menu. */
  hidden?: boolean;
  /** Disables the resize handle for this column; default true. */
  resizable?: boolean;
  /** Disables drag-to-reorder for this column; default true. */
  reorderable?: boolean;
  /** Disables pin/unpin for this column; default true. */
  pinnable?: boolean;
  /** Display-only override that keeps the column's type pipeline; method-shorthand for the same bivariance reason as `validate`. */
  renderCell?(props: CellRenderProps<TData, TValue>): ReactNode;
  /**
   * Per-column cell class, merged via `cn()` after the built-in cell classes (PLAN §6 "Programmatic
   * style API") so it wins on conflicting utilities. A plain string applies to every cell in the
   * column; the function form gets the same per-cell context as the grid-level `getCellClassName`
